    function resetSimulasiTargetDistribusiManual() {
        targetDistribusiBebanManual = {};
        notifikasiTahapAwalManualSudahTampil = false;
        notifikasiOptimalisasiManualSudahTampil = false;
        setTargetDistribusiButuhOptimalisasi(false);
        batalkanStatusTargetDistribusiMulai();
        simpanPlottingKerma();
        renderEksporTargetDistribusiPlotting();
        renderEksporRekapitulasiPlotting();
        renderValidasiBatasanPlotSkBidang();
        updateStatusMulaiPlottingKerma();
        tampilkanAlertMulaiPlotting(
            alertSimpanTargetDistribusiMulai,
            'Simulasi Target Distribusi sudah direset. Simpan Target Distribusi jika hasil kosong ini akan dipakai.',
            false
        );
    }

    function keyPlotSkBidangManual(role, bidangIndex, noPks) {
        return `${role}|${Number(bidangIndex) || 0}|${Number(noPks) || 0}`;
    }

    function parseKeyPlotSkBidangManual(key = '') {
        const [role = '', bidangIndex = '0', noPks = '0'] = String(key || '').split('|');
        return {
            role,
            bidangIndex: Math.max(0, Math.floor(Number(bidangIndex) || 0)),
            noPks: Math.max(0, Math.floor(Number(noPks) || 0))
        };
    }

    function getPlotSkBidangManual(role, bidangIndex, noPks) {
        return plotSkBidangManual[keyPlotSkBidangManual(role, bidangIndex, noPks)] || { nama: '', bulan: '' };
    }

    function setPlotSkBidangManual(key, field, value) {
        if (!key || !['nama', 'bulan'].includes(field)) return;
        const current = plotSkBidangManual[key] || { nama: '', bulan: '' };
        const next = {
            ...current,
            [field]: String(value || '').trim()
        };
        if (!next.nama && !next.bulan) {
            delete plotSkBidangManual[key];
        } else {
            plotSkBidangManual[key] = next;
        }
        simpanPlottingKerma();
    }

    function hitungTargetBulanPlotSkBidang(nama, role) {
        const row = getPlottingKermaRowByNama(nama);
        if (!row || !isPegawaiAktifDenganTargetKerma(row)) return 0;
        const roles = getDistribusiRolesEfektifTargetPlotSk(row);
        return batasiBulanTargetDistribusiUntukRow(
            row,
            role,
            hitungBulanTargetDistribusiBeban(roles?.[role], role)
        );
    }

    function sinkronkanPlotSkBidangManualDenganTarget(manual = plotSkBidangManual) {
        const groups = new Map();
        const changes = [];
        let changed = false;

        Object.entries(manual || {}).forEach(([key, entry]) => {
            const parsed = parseKeyPlotSkBidangManual(key);
            const nama = String(entry?.nama || '').trim();
            if (!parsed.role || !nama || isPenandaSkTanpaNilaiPlotSk(entry?.bulan)) return;
            const bulan = hitungBulanPlotSkBidang(entry?.bulan, parsed.role);
            if (bulan <= 0) return;
            const personKey = normalisasiNamaPegawaiPlotting(nama);
            if (!personKey) return;
            const groupKey = `${personKey}|${parsed.role}`;
            if (!groups.has(groupKey)) groups.set(groupKey, []);
            groups.get(groupKey).push({ key, entry, parsed, nama, bulan });
        });

        groups.forEach(entries => {
            const targetBulan = hitungTargetBulanPlotSkBidang(entries[0].nama, entries[0].parsed.role);
            let totalBulan = entries.reduce((sum, item) => sum + item.bulan, 0);
            let kelebihan = totalBulan - targetBulan;
            if (kelebihan <= 0.0001) return;

            entries
                .slice()
                .sort((a, b) => (
                    (Number(b.parsed.noPks) || 0) - (Number(a.parsed.noPks) || 0) ||
                    (Number(b.parsed.bidangIndex) || 0) - (Number(a.parsed.bidangIndex) || 0)
                ))
                .forEach(item => {
                    if (kelebihan <= 0.0001) return;
                    const sisaBulan = Math.max(0, item.bulan - kelebihan);
                    const nilaiBaru = sisaBulan > 0.0001
                        ? formatBulanManualPlotSkBidangDariBulan(sisaBulan, getKonfigurasiRoleDistribusi(item.parsed.role).durasi)
                        : 'SK';
                    if (nilaiBaru === item.entry.bulan) return;
                    manual[item.key] = { ...item.entry, bulan: nilaiBaru };
                    const dikurangi = item.bulan - sisaBulan;
                    kelebihan -= dikurangi;
                    totalBulan -= dikurangi;
                    changed = true;
                    changes.push({
                        nama: item.nama,
                        role: item.parsed.role,
                        noPks: item.parsed.noPks,
                        sebelum: item.entry.bulan,
                        sesudah: nilaiBaru
                    });
                });
        });

        return { changed, changes };
    }

    function rowPerhitunganDasarRole(role) {
        return perhitunganDasarPlotting.rows.find(item => item.jabatan === role) || {};
    }

    function nilaiPosisiRolePlotSkBidang(role) {
        const row = rowPerhitunganDasarRole(role);
        const tarif = tarifPlotting(row.tarif ?? tarifMasterJabatanPlotting[role]);
        const durasi = angkaDesimalPlotting(row.durasi);
        return tarif * durasi;
    }

    function formatBulanManualPlotSkBidangDariBulan(value, durasi) {
        const bulan = Math.max(0, Number(value) || 0);
        const totalDurasi = Math.max(0, angkaDesimalPlotting(durasi));
        if (bulan <= 0) return '';
        if (totalDurasi <= 0) return bulan.toLocaleString('id-ID', { maximumFractionDigits: 2 });
        const durasiLabel = formatDurasiDistribusi(totalDurasi);
        const full = Math.floor((bulan + 0.000001) / totalDurasi);
        const sisaRaw = bulan - (full * totalDurasi);
        const sisa = Math.abs(sisaRaw) < 0.000001 ? 0 : sisaRaw;
        if (!full) return `${formatDurasiDistribusi(sisa)}/${durasiLabel}`;
        if (!sisa) return String(full);
        return `${full} + ${formatDurasiDistribusi(sisa)}/${durasiLabel}`;
    }

    function hitungTermBulanManualPlotSkBidang(term, durasi) {
        const teks = String(term || '').trim().replace(/[()]/g, '');
        if (!teks) return 0;
        const terminMatch = teks.match(/^(-?\d+(?:[,.]\d+)?)\s*\/\s*(-?\d+(?:[,.]\d+)?)$/);
        if (terminMatch) return Math.max(0, angkaDesimalPlotting(terminMatch[1]));
        const angka = Math.max(0, angkaDesimalPlotting(teks));
        if (durasi > 0 && angka === 1) return durasi;
        return angka;
    }

    function hitungBulanManualPlotSkBidang(value, role) {
        const raw = String(value || '').trim();
        if (!raw || /^sk$/i.test(raw)) return 0;
        const { durasi } = getKonfigurasiRoleDistribusi(role);
        const terms = raw.replace(/＋/g, '+').split('+').map(term => term.trim()).filter(Boolean);
        return terms.reduce((sum, term) => sum + hitungTermBulanManualPlotSkBidang(term, durasi), 0);
    }

    function normalisasiBulanManualPlotSkBidang(value, role) {
        const raw = String(value || '').trim();
        if (!raw) return '';
        if (/^sk$/i.test(raw)) return 'SK';
        const { durasi } = getKonfigurasiRoleDistribusi(role);
        const bulan = hitungBulanManualPlotSkBidang(raw, role);
        if (!Number.isFinite(bulan) || bulan <= 0) return '';
        return formatBulanManualPlotSkBidangDariBulan(bulan, durasi);
    }

    function hitungBulanPlotSkBidang(value, role) {
        const raw = String(value || '').trim();
        if (!raw || /^sk$/i.test(raw)) return 0;
        const normalized = normalisasiBulanManualPlotSkBidang(raw, role);
        if (!normalized || /^sk$/i.test(normalized)) return 0;
        return hitungBulanManualPlotSkBidang(normalized, role);
    }

    function tarifPerBulanPlotSkBidang(role) {
        const row = rowPerhitunganDasarRole(role);
        return tarifPlotting(row.tarif ?? tarifMasterJabatanPlotting[role]);
    }

    function kosongRealisasiRolePlotSkBidang() {
        return Object.fromEntries(rolePlottingKerma.map(role => [role, 0]));
    }

    function kosongBebanAlokasiRolePlotSkBidang() {
        return Object.fromEntries(rolePlottingKerma.map(role => [role, 0]));
    }

    function formatBebanAlokasiPlotSkBidang(bulan, role) {
        const totalBulan = Math.max(0, Number(bulan) || 0);
        if (totalBulan <= 0) return '-';
        const { durasi } = getKonfigurasiRoleDistribusi(role);
        const totalDurasi = Math.max(0, angkaDesimalPlotting(durasi));
        if (totalDurasi <= 0) return formatDurasiDistribusi(totalBulan);
        const full = Math.floor((totalBulan + 0.000001) / totalDurasi);
        const sisaRaw = totalBulan - (full * totalDurasi);
        const sisa = Math.abs(sisaRaw) < 0.000001 ? 0 : sisaRaw;
        const durasiLabel = formatDurasiDistribusi(totalDurasi);
        if (!full) return `${formatDurasiDistribusi(sisa)}/${durasiLabel}`;
        if (!sisa) return String(full);
        return `${full}+(${formatDurasiDistribusi(sisa)}/${durasiLabel})`;
    }

    function formatSelisihBebanAlokasiPlotSkBidang(bulan, role) {
        const nilai = Math.round((Number(bulan) || 0) * 100) / 100;
        if (Math.abs(nilai) < 0.000001) return '0';
        const display = formatBebanAlokasiPlotSkBidang(Math.abs(nilai), role);
        return nilai > 0 ? `+${display}` : `-${display}`;
    }

    function hitungTermBulanTargetDistribusiBeban(term, role) {
        const teks = String(term || '').trim().replace(/[()]/g, '');
        if (!teks) return 0;
        const { durasi } = getKonfigurasiRoleDistribusi(role);
        const totalDurasi = Math.max(0, angkaDesimalPlotting(durasi));
        const terminMatch = teks.match(/^(-?\d+(?:[,.]\d+)?)\s*\/\s*(-?\d+(?:[,.]\d+)?)$/);
        if (terminMatch) return Math.max(0, angkaDesimalPlotting(terminMatch[1]));
        const angka = Math.max(0, angkaDesimalPlotting(teks));
        return totalDurasi > 0 ? angka * totalDurasi : angka;
    }

    function hitungBulanTargetDistribusiBeban(value, role) {
        const raw = String(value || '').trim();
        if (!raw || /^sk$/i.test(raw)) return 0;
        return raw
            .replace(/＋/g, '+')
            .split('+')
            .map(term => term.trim())
            .filter(Boolean)
            .reduce((sum, term) => sum + hitungTermBulanTargetDistribusiBeban(term, role), 0);
    }

    function hitungRealisasiDistribusiPlotSkBidangDetailByNama(manualSource = null, opsi = {}) {
        pastikanRowsPerhitunganDasarPlotting();
        sinkronDurasiDariPeriodePengelola();
        const pakaiPlotSk = opsi?.pakaiPlotSk !== false;
        const map = pakaiPlotSk && Object.keys(plotSkBidangManual || {}).length ? dataEksporPlotSkBidangUntukFilter().reduce((hasil, row) => {
            const role = row.role || '';
            const tarif = tarifPerBulanPlotSkBidang(role);
            if (!role || tarif <= 0) return hasil;
            for (let noPks = 1; noPks <= jumlahPksPlotting; noPks += 1) {
                const nama = String(row[colKeyPksPlotSkBidang(noPks, 'nama')] || '').trim();
                if (!nama) continue;
                const bulan = hitungBulanPlotSkBidang(row[colKeyPksPlotSkBidang(noPks, 'bulan')], role);
                if (bulan <= 0) continue;
                const key = normalisasiNamaPegawaiPlotting(nama);
                const biaya = tarif * bulan;
                const detail = hasil.get(key) || {
                    total: 0,
                    byRole: kosongRealisasiRolePlotSkBidang(),
                    byRoleBulan: kosongBebanAlokasiRolePlotSkBidang()
                };
                detail.total += biaya;
                detail.byRole[role] = (Number(detail.byRole[role]) || 0) + biaya;
                detail.byRoleBulan[role] = (Number(detail.byRoleBulan[role]) || 0) + bulan;
                hasil.set(key, detail);
            }
            return hasil;
        }, new Map()) : new Map();

        if (!manualSource || typeof manualSource !== 'object') return map;

        Object.entries(manualSource || {}).forEach(([namaKey, roles]) => {
            if (!roles || typeof roles !== 'object') return;
            const key = normalisasiNamaPegawaiPlotting(namaKey);
            if (!key) return;
            const detail = map.get(key) || {
                total: 0,
                byRole: kosongRealisasiRolePlotSkBidang(),
                byRoleBulan: kosongBebanAlokasiRolePlotSkBidang()
            };
            rolePlottingKerma.forEach(role => {
                if (!Object.prototype.hasOwnProperty.call(roles, role)) return;
                const bulan = hitungBulanTargetDistribusiBeban(roles[role], role);
                detail.byRoleBulan[role] = bulan;
                detail.byRole[role] = tarifPerBulanPlotSkBidang(role) * bulan;
            });
            detail.total = rolePlottingKerma.reduce((sum, role) => sum + (Number(detail.byRole[role]) || 0), 0);
            map.set(key, detail);
        });

        return map;
    }

    function hitungTargetDistribusiBebanByNama(source = targetDistribusiBebanManual) {
        const map = new Map();
        getRowsEksporTargetDistribusi().forEach(row => {
            const key = normalisasiNamaPegawaiPlotting(row?.nama);
            if (!key) return;
            const rolesManual = getBebanTargetDistribusiManualRow(row, source);
            const roles = rolesManual || pastikanDistribusiRoles(row);
            const detail = {
                total: 0,
                byRole: kosongRealisasiRolePlotSkBidang(),
                byRoleBulan: kosongBebanAlokasiRolePlotSkBidang()
            };
            rolePlottingKerma.forEach(role => {
                const bulan = hitungBulanTargetDistribusiBeban(roles?.[role], role);
                detail.byRoleBulan[role] = bulan;
                detail.byRole[role] = tarifPerBulanPlotSkBidang(role) * bulan;
                detail.total += detail.byRole[role];
            });
            map.set(key, detail);
        });
        return map;
    }

    function hitungRealisasiDistribusiPlotSkBidangByNama() {
        return new Map([...hitungRealisasiDistribusiPlotSkBidangDetailByNama().entries()]
            .map(([key, detail]) => [key, Number(detail.total) || 0]));
    }

    function getPlottingKermaRowByNama(nama = '') {
        const key = normalisasiNamaPegawaiPlotting(nama);
        return plottingKermaRows.find(row => normalisasiNamaPegawaiPlotting(row.nama) === key) || null;
    }

    function isStafTargetDistribusiPlotSkBidang(row = {}) {
        return isStafDistribusi(row) && isPegawaiAktifDenganTargetKerma(row);
    }

    function namaSudahDipakaiDalamPksPlotSkBidang(nama, noPks, exceptKey = '', manual = plotSkBidangManual) {
        const personKey = normalisasiNamaPegawaiPlotting(nama);
        const nomorPks = Number(noPks) || 0;
        if (!personKey || nomorPks <= 0) return false;
        return Object.entries(manual || {}).some(([key, entry]) => {
            if (key === exceptKey) return false;
            const parsed = parseKeyPlotSkBidangManual(key);
            return parsed.noPks === nomorPks
                && normalisasiNamaPegawaiPlotting(entry?.nama) === personKey;
        });
    }

    function rapihkanAnggotaPlotSkBidangManual(manual = plotSkBidangManual) {
        if (!manual || typeof manual !== 'object') return false;
        let changed = false;
        const jumlahBarisAnggota = jumlahBarisPlotSkBidangUntukRole('Anggota');
        const namaTerpakaiPerPks = new Map();
        Object.entries(manual).forEach(([key, entry]) => {
            const parsed = parseKeyPlotSkBidangManual(key);
            if (parsed.role === 'Anggota') return;
            const namaKey = normalisasiNamaPegawaiPlotting(entry?.nama);
            if (!namaKey || parsed.noPks <= 0) return;
            if (!namaTerpakaiPerPks.has(parsed.noPks)) namaTerpakaiPerPks.set(parsed.noPks, new Set());
            namaTerpakaiPerPks.get(parsed.noPks).add(namaKey);
        });

        Object.entries(manual).forEach(([key, entry]) => {
            const parsed = parseKeyPlotSkBidangManual(key);
            if (parsed.role !== 'Anggota') return;
            const nama = String(entry?.nama || '').trim();
            const bulan = String(entry?.bulan || '').trim();
            const invalidSlot = parsed.bidangIndex >= jumlahBarisAnggota
                || parsed.noPks < 1
                || parsed.noPks > jumlahPksPlotting;
            if (invalidSlot || !nama) {
                if (manual[key]) {
                    delete manual[key];
                    changed = true;
                }
                return;
            }
            const pegawai = getPlottingKermaRowByNama(nama);
            const personKey = normalisasiNamaPegawaiPlotting(pegawai?.nama || nama);
            const sudahDipakai = namaTerpakaiPerPks.get(parsed.noPks)?.has(personKey);
            const isAssignmentFromWorkbook = entry?.sumber === 'excel-manual';
            if ((!isStafTargetDistribusiPlotSkBidang(pegawai) || sudahDipakai) && !isAssignmentFromWorkbook) {
                delete manual[key];
                changed = true;
                return;
            }
            if (!namaTerpakaiPerPks.has(parsed.noPks)) namaTerpakaiPerPks.set(parsed.noPks, new Set());
            namaTerpakaiPerPks.get(parsed.noPks).add(personKey);
            const namaCanonical = String(pegawai.nama || nama).trim();
            if (entry.nama !== namaCanonical || bulan !== 'SK') {
                manual[key] = { nama: namaCanonical, bulan: 'SK' };
                changed = true;
            }
        });
        return changed;
    }

    function isStafKepalaSubKoordinator(row = {}) {
        if (!isStafDistribusi(row)) return false;
        return [
            row.level_jabatan_1,
            row.level_jabatan_2,
            row.jabatan_sbm,
            row.jabatan_sbm_2
        ].some(value => /\b(kepala|kepala sub|koordinator)\b/i.test(normalisasiNamaJabatan(value)));
    }

    function isStafAsistenDistribusi(row = {}) {
        if (!isStafDistribusi(row)) return false;
        return [
            row.level_jabatan_1,
            row.level_jabatan_2,
            row.jabatan_sbm,
            row.jabatan_sbm_2
        ].some(value => /\basisten\b/i.test(normalisasiNamaJabatan(value)));
    }

    function hitungPemakaianPlotSkBidang() {
        const pksMap = new Map();
        const stafPksMap = new Map();
        const stafPenempatanMap = new Map();
        let jumlahPenempatan = 0;
        dataEksporPlotSkBidangUntukFilter().forEach(row => {
            const role = row.role || '';
            const tarif = tarifPerBulanPlotSkBidang(role);
            if (!role || tarif <= 0) return;
            for (let noPks = 1; noPks <= jumlahPksPlotting; noPks += 1) {
                const nama = String(row[colKeyPksPlotSkBidang(noPks, 'nama')] || '').trim();
                if (!nama) continue;
                const bulan = hitungBulanPlotSkBidang(row[colKeyPksPlotSkBidang(noPks, 'bulan')], role);
                if (bulan <= 0) continue;
                jumlahPenempatan += 1;
                const biaya = tarif * bulan;
                pksMap.set(noPks, (pksMap.get(noPks) || 0) + biaya);

                const pegawai = getPlottingKermaRowByNama(nama);
                if (!isStafDistribusi(pegawai)) continue;
                const namaKey = normalisasiNamaPegawaiPlotting(nama);
                const stafPksKey = `${namaKey}|${noPks}`;
                const stafPks = stafPksMap.get(stafPksKey) || {
                    nama: pegawai?.nama || nama,
                    noPks,
                    pegawai,
                    tarifBulanan: 0
                };
                stafPks.tarifBulanan += tarif;
                stafPksMap.set(stafPksKey, stafPks);

                const stafPenempatan = stafPenempatanMap.get(namaKey) || {
                    nama: pegawai?.nama || nama,
                    pegawai,
                    penempatan: []
                };
                stafPenempatan.penempatan.push({
                    noPks,
                    role,
                    jabatan: row.jabatan_per_bidang || labelJabatanPlotting(role)
                });
                stafPenempatanMap.set(namaKey, stafPenempatan);
            }
        });
        return {
            pksMap,
            stafPks: [...stafPksMap.values()],
            stafPenempatan: [...stafPenempatanMap.values()],
            jumlahPenempatan
        };
    }

    function ringkasDetailValidasiBatasan(items = [], max = 3) {
        const list = items.filter(Boolean);
        if (!list.length) return '';
        const ringkas = list.slice(0, max).join('; ');
        const sisa = list.length - max;
        return sisa > 0 ? `${ringkas}; dan ${sisa.toLocaleString('id-ID')} lainnya` : ringkas;
    }

    function hitungRingkasanPosisiKosongPlotSkBidang(manual = plotSkBidangManual) {
        const detail = getSlotBelumTeralokasiPlotSkBidang(manual).map(slot => {
            const pks = getPksAlokasiByNomor(slot.noPks);
            const kodeFile = pks?.kode_file || pks?.id_program || `PKS ${slot.noPks}`;
            const jabatan = labelJabatanPerBidangPlotSkBidang(slot.role, slot.index);
            const kurang = [
                slot.nama ? '' : 'Nama',
                slot.bulan ? '' : 'Bulan'
            ].filter(Boolean).join(' dan ');
            return `${kodeFile} - ${jabatan} belum berisi ${kurang || 'alokasi'}`;
        });
        return {
            total: detail.length,
            detail,
            detailRingkas: ringkasDetailValidasiBatasan(detail)
        };
    }

    function hitungValidasiBatasanPlotSkBidang() {
        const batasan = getBatasanSimulasi();
        const penggunaan = hitungPemakaianPlotSkBidang();
        const posisiKosongBidang = hitungRingkasanPosisiKosongPlotSkBidang();
        if (!penggunaan.jumlahPenempatan && !Object.keys(plotSkBidangManual || {}).length) return [];
        const realisasiByNama = hitungRealisasiDistribusiPlotSkBidangByNama();
        const hasil = [];

        if (isBatasanSimulasiAktif('batasSelisihAtas')) {
            const melewatiBatasAtas = getRowsEksporTargetDistribusi()
                .filter(row => isDosenDistribusi(row))
                .map(row => {
                    const target = hitungTargetDistribusiRow(row);
                    const realisasi = realisasiByNama.get(normalisasiNamaPegawaiPlotting(row.nama)) || 0;
                    return { row, selisih: realisasi - target };
                })
                .filter(item => item.selisih > Number(batasan.batasSelisihAtas))
                .map(item => `${item.row.nama} lebih ${formatRupiahKomaDash(item.selisih)}`);
            hasil.push({
                id: 'batasSelisihAtas',
                label: 'Batas selisih atas Dosen',
                ok: melewatiBatasAtas.length === 0,
                detailOk: 'Tidak ada Dosen yang melewati batas selisih atas.',
                detailError: ringkasDetailValidasiBatasan(melewatiBatasAtas)
            });
        }

        if (isBatasanSimulasiAktif('batasSelisihBawahPersonil')) {
            const melewatiBatasBawahPersonil = getRowsEksporTargetDistribusi()
                .filter(row => isBatasSelisihBawahPersonilBerlaku(row))
                .map(row => {
                    const target = hitungTargetDistribusiRow(row);
                    const realisasi = realisasiByNama.get(normalisasiNamaPegawaiPlotting(row.nama)) || 0;
                    return { row, selisih: realisasi - target };
                })
                .filter(item => item.selisih < -Number(batasan.batasSelisihBawahPersonil))
                .map(item => `${item.row.nama} kurang ${formatRupiahKomaDash(Math.abs(item.selisih))}`);
            hasil.push({
                id: 'batasSelisihBawahPersonil',
                label: 'Batas selisih bawah personil prioritas',
                ok: melewatiBatasBawahPersonil.length === 0,
                detailOk: 'Tidak ada personil prioritas yang berada di bawah batas selisih.',
                detailError: ringkasDetailValidasiBatasan(melewatiBatasBawahPersonil)
            });
        }

        if (isBatasanSimulasiAktif('batasSelisihBawah')) {
            const melewatiBatasBawahDosen = getRowsEksporTargetDistribusi()
                .filter(row => isDosenDistribusi(row))
                .filter(row => !isBatasSelisihBawahPersonilBerlaku(row))
                .map(row => {
                    const target = hitungTargetDistribusiRow(row);
                    const realisasi = realisasiByNama.get(normalisasiNamaPegawaiPlotting(row.nama)) || 0;
                    return { row, selisih: realisasi - target };
                })
                .filter(item => item.selisih < -Number(batasan.batasSelisihBawah))
                .map(item => `${item.row.nama} kurang ${formatRupiahKomaDash(Math.abs(item.selisih))}`);
            hasil.push({
                id: 'batasSelisihBawah',
                label: 'Batas selisih bawah Dosen',
                ok: melewatiBatasBawahDosen.length === 0,
                detailOk: 'Tidak ada Dosen yang melewati batas selisih bawah.',
                detailError: ringkasDetailValidasiBatasan(melewatiBatasBawahDosen)
            });
        }

        if (isBatasanSimulasiAktif('batasSelisihBawahStaf')) {
            const melewatiBatasBawahStaf = getRowsEksporTargetDistribusi()
                .filter(row => isStafDistribusi(row))
                .filter(row => !isBatasSelisihBawahPersonilBerlaku(row))
                .map(row => {
                    const target = hitungTargetDistribusiRow(row);
                    const realisasi = realisasiByNama.get(normalisasiNamaPegawaiPlotting(row.nama)) || 0;
                    return { row, selisih: realisasi - target };
                })
                .filter(item => item.selisih < -Number(batasan.batasSelisihBawahStaf))
                .map(item => `${item.row.nama} kurang ${formatRupiahKomaDash(Math.abs(item.selisih))}`);
            hasil.push({
                id: 'batasSelisihBawahStaf',
                label: 'Batas selisih bawah Staf',
                ok: melewatiBatasBawahStaf.length === 0,
                detailOk: 'Tidak ada Staf yang melewati batas selisih bawah.',
                detailError: ringkasDetailValidasiBatasan(melewatiBatasBawahStaf)
            });
        }

        if (isBatasanSimulasiAktif('sisaPaguPksTidakBolehMinus') && batasan.sisaPaguPksTidakBolehMinus) {
            const pksMinus = [];
            for (let noPks = 1; noPks <= jumlahPksPlotting; noPks += 1) {
                const terpakai = Number(penggunaan.pksMap.get(noPks)) || 0;
                const alokasi = getPksAlokasiByNomor(noPks);
                if (!alokasi && terpakai > 0) {
                    pksMinus.push(`PKS ${noPks} belum dipilih`);
                    continue;
                }
                const sisaAwal = Number(alokasi?.sisa_anggaran) || 0;
                const sisaAkhir = sisaAwal - terpakai;
                if (sisaAkhir < 0) {
                    const kodeFile = alokasi?.kode_file || alokasi?.id_program || `PKS ${noPks}`;
                    pksMinus.push(`${kodeFile} minus ${formatRupiahKomaDash(Math.abs(sisaAkhir))}`);
                }
            }
            hasil.push({
                id: 'sisaPaguPksTidakBolehMinus',
                label: 'Sisa PAGU PKS',
                ok: pksMinus.length === 0,
                detailOk: 'Tidak ada PKS yang minus setelah Plot SK Bidang.',
                detailError: ringkasDetailValidasiBatasan(pksMinus)
            });
        }

        if (isBatasanSimulasiAktif('plotSkBidangHarusTerisi') && batasan.plotSkBidangHarusTerisi) {
            hasil.push({
                id: 'plotSkBidangHarusTerisi',
                label: 'Seluruh posisi Plot SK Bidang',
                ok: posisiKosongBidang.total === 0,
                detailOk: 'Seluruh posisi Plot SK Bidang sudah memiliki Nama dan Bulan.',
                detailError: posisiKosongBidang.detailRingkas
            });
        }

        if (isCakupanSeluruhTargetDistribusiAktif()) {
            const belumTeralokasi = getRowsEksporTargetDistribusi()
                .filter(row => hitungTargetDistribusiRow(row) > 0)
                .filter(row => (Number(realisasiByNama.get(normalisasiNamaPegawaiPlotting(row.nama))) || 0) <= 0)
                .map(row => row.nama || '-')
                .filter(Boolean)
                .sort((a, b) => a.localeCompare(b, 'id', { sensitivity: 'base' }));
            hasil.push({
                id: 'seluruhPersonilTargetTeralokasikan',
                label: 'Seluruh personil target distribusi',
                ok: belumTeralokasi.length === 0,
                detailOk: 'Seluruh personil Target Distribusi sudah memiliki alokasi bernilai.',
                detailError: ringkasDetailValidasiBatasan(belumTeralokasi, 7)
            });
        }

        if (isBatasanKesesuaianKkPlotSkBidangAktif()) {
            const kkTidakSesuai = [];
            dataEksporPlotSkBidangUntukFilter().forEach(row => {
                for (let noPks = 1; noPks <= jumlahPksPlotting; noPks += 1) {
                    const nama = String(row[colKeyPksPlotSkBidang(noPks, 'nama')] || '').trim();
                    if (!nama) continue;
                    const pegawai = getPlottingKermaRowByNama(nama);
                    const detail = detailKesesuaianKkPlotSkBidang(pegawai || { nama }, row.role, row.bidang_index);
                    if (!detail.cocok) {
                        kkTidakSesuai.push(`${detail.nama} · ${detail.bidang} · KK: ${detail.kelompok}`);
                    }
                }
            });
            hasil.push({
                id: 'kesesuaianKk',
                label: 'Kesesuaian KK',
                ok: kkTidakSesuai.length === 0,
                detailOk: 'Seluruh personil Plot SK Bidang sesuai dengan Kelompok Keahlian pada bidangnya.',
                detailError: ringkasDetailValidasiBatasan(kkTidakSesuai)
            });
        }

        const stafBatas = penggunaan.stafPks
            .map(item => {
                const khusus = isStafKepalaSubKoordinator(item.pegawai);
                const batas = khusus
                    ? Number(batasan.stafLevelMaksPerPksPerBulan) || 0
                    : Number(batasan.stafMaksPerPksPerBulan) || 0;
                return { ...item, batas, khusus };
            })
            .filter(item => item.batas > 0 && item.tarifBulanan > item.batas);
        const stafRegulerMelewatiBatas = stafBatas
            .filter(item => !item.khusus)
            .map(item => `${item.nama} PKS ${item.noPks} ${formatRupiahKomaDash(item.tarifBulanan)}/bulan > ${formatRupiahKomaDash(item.batas)}`);
        const stafKhususMelewatiBatas = stafBatas
            .filter(item => item.khusus)
            .map(item => `${item.nama} PKS ${item.noPks} ${formatRupiahKomaDash(item.tarifBulanan)}/bulan > ${formatRupiahKomaDash(item.batas)}`);
        if (isBatasanSimulasiAktif('stafMaksPerPksPerBulan')) {
            hasil.push({
                id: 'stafMaksPerPksPerBulan',
                label: 'Batas staf reguler',
                ok: stafRegulerMelewatiBatas.length === 0,
                detailOk: 'Tidak ada Staf reguler yang melewati batas per PKS per bulan.',
                detailError: ringkasDetailValidasiBatasan(stafRegulerMelewatiBatas)
            });
        }
        if (isBatasanSimulasiAktif('stafLevelMaksPerPksPerBulan')) {
            hasil.push({
                id: 'stafLevelMaksPerPksPerBulan',
                label: 'Batas staf Kepala/Koordinator',
                ok: stafKhususMelewatiBatas.length === 0,
                detailOk: 'Tidak ada Staf Kepala/Kepala Sub/Koordinator yang melewati batas per PKS per bulan.',
                detailError: ringkasDetailValidasiBatasan(stafKhususMelewatiBatas)
            });
        }

        const stafMultiPenempatan = penggunaan.stafPenempatan
            .filter(item => item.penempatan.length > 1)
            .map(item => {
                const detail = item.penempatan
                    .slice(0, 3)
                    .map(posisi => `PKS ${posisi.noPks} ${posisi.jabatan}`)
                    .join(', ');
                const sisa = item.penempatan.length - 3;
                return `${item.nama}: ${detail}${sisa > 0 ? `, dan ${sisa.toLocaleString('id-ID')} lainnya` : ''}`;
            });
        if (isBatasanSimulasiAktif('stafSatuJabatanSeluruhPks') && batasan.stafSatuJabatanSeluruhPks) {
            hasil.push({
                id: 'stafSatuJabatanSeluruhPks',
                label: 'Staf satu penempatan',
                ok: stafMultiPenempatan.length === 0,
                detailOk: 'Setiap Staf hanya ditempatkan satu kali: satu PKS dan satu jabatan.',
                detailError: ringkasDetailValidasiBatasan(stafMultiPenempatan)
            });
        }

        return hasil.map(item => {
            if (item.ok || !item.id || isBatasanWajibSimulasi(item.id)) return item;
            return {
                ...item,
                ok: true,
                actualOk: false,
                preference: true,
                detailOk: `Preferensi dilanggar dan diizinkan sebagai fallback: ${item.detailError || 'aturan belum terpenuhi.'}`
            };
        });
    }

    function renderValidasiBatasanPlotSkBidang() {
        const containers = document.querySelectorAll('[data-batasan-validasi]');
        if (!containers.length) return;
        if (!isHasilMulaiPlottingKermaSelesai()) {
            containers.forEach(container => { container.innerHTML = ''; });
            return;
        }
        if (!isBatasanSimulasiGlobalAktif()) {
            const html = `
                <div class="plotting-rule-validation-summary is-info">
                    <span>Validasi Plot SK Bidang</span>
                    <strong>Batasan simulasi nonaktif</strong>
                </div>
            `;
            containers.forEach(container => { container.innerHTML = html; });
            return;
        }
        const hasil = hitungValidasiBatasanPlotSkBidang();
        if (!hasil.length) {
            containers.forEach(container => { container.innerHTML = ''; });
            return;
        }
        const pelanggaran = hasil.filter(item => !item.ok);
        const html = `
            <div class="plotting-rule-validation-summary ${pelanggaran.length ? 'is-error' : 'is-success'}">
                <span>Validasi Plot SK Bidang</span>
                <strong>${pelanggaran.length ? `${pelanggaran.length.toLocaleString('id-ID')} aturan wajib perlu diperbaiki` : 'Semua aturan wajib terpenuhi'}</strong>
            </div>
            <div class="plotting-rule-validation-grid">
                ${hasil.map(item => `
                    <article class="plotting-rule-validation-item ${item.preference ? 'is-info' : (item.ok ? (item.info ? 'is-info' : 'is-ok') : 'is-error')}"${item.preference ? ' title="Preferensi boleh dilanggar jika diperlukan untuk memenuhi aturan Wajib"' : ''}>
                        <strong>${esc(item.label)}</strong>
                        <span>${esc(item.actualOk === false ? item.detailOk : (item.ok ? item.detailOk : item.detailError))}</span>
                    </article>
                `).join('')}
            </div>
        `;
        containers.forEach(container => { container.innerHTML = html; });
    }

    function opsiNamaPlotSkBidang(role = '') {
        return plottingKermaRows
            .filter(row => isPegawaiAktifDenganTargetKerma(row))
            .filter(row => role !== 'Anggota' || isStafDistribusi(row))
            .map(row => String(row.nama || '').trim())
            .filter(Boolean)
            .filter((nama, index, arr) => arr.findIndex(item => item.toLowerCase() === nama.toLowerCase()) === index)
            .sort((a, b) => a.localeCompare(b, 'id', { sensitivity: 'base' }));
    }

    function htmlOpsiNamaPlotSkBidang(selected = '', role = '') {
        const selectedNama = String(selected || '').trim();
        const options = opsiNamaPlotSkBidang(role);
        return `
            <option value="">-</option>
            ${options.map(nama => `<option value="${esc(nama)}" ${nama === selectedNama ? 'selected' : ''}>${esc(nama)}</option>`).join('')}
        `;
    }

    function dataEksporPlotSkBidangUntukFilter() {
        pastikanRowsPerhitunganDasarPlotting();
        sinkronDurasiDariPeriodePengelola();
        const rows = [];
        const daftarJabatanAktif = new Map();
        dataEksporDaftarJabatanUntukFilter().forEach(item => {
            if (!item.aktif) return;
            if (!daftarJabatanAktif.has(item.role)) daftarJabatanAktif.set(item.role, []);
            daftarJabatanAktif.get(item.role).push(item);
        });
        rolePlottingKerma.forEach(role => {
            const { personilPerKerma } = getKonfigurasiRoleDistribusi(role);
            if (personilPerKerma <= 0) return;
            const jumlahBaris = jumlahBarisPlotSkBidangUntukRole(role);
            if (jumlahBaris <= 0) return;
            const nilaiPosisi = nilaiPosisiRolePlotSkBidang(role);
            Array.from({ length: jumlahBaris }, (_, index) => {
                const jabatanPerBidang = daftarJabatanAktif.get(role)?.[index]?.jabatan_per_bidang
                    || labelJabatanPerBidangPlotSkBidang(role, index);
                const row = {
                    no: rows.length + 1,
                    role,
                    bidang_index: index,
                    role_label: labelJabatanPlotting(role),
                    jabatan_per_bidang: jabatanPerBidang,
                    nilai_posisi: nilaiPosisi,
                    nilai_posisi_display: formatRupiahKomaDash(nilaiPosisi)
                };
                Array.from({ length: jumlahPksPlotting }, (_, pksIndex) => {
                    const noPks = pksIndex + 1;
                    const manual = getPlotSkBidangManual(role, index, noPks);
                    row[colKeyPksPlotSkBidang(noPks, 'nama')] = manual.nama || '';
                    row[colKeyPksPlotSkBidang(noPks, 'bulan')] = manual.bulan || '';
                    row[colKeyPksPlotSkBidang(noPks, 'key')] = keyPlotSkBidangManual(role, index, noPks);
                });
                rows.push(row);
            });
        });
        return rows;
    }

    function renderHeaderEksporPlotSkBidang() {
        if (!headTabelEksporPlotSkBidang) return;
        const pksHeaders = Array.from({ length: jumlahPksPlotting }, (_, idx) => {
            const no = idx + 1;
            const alokasi = getPksAlokasiByNomor(no);
            const kodeFile = alokasi?.kode_file || alokasi?.id_program || '';
            const sisaAnggaran = labelSisaAnggaranHeaderPksPlotSkBidang(no, alokasi);
            const sisaAnggaranNilai = hitungSisaAnggaranPksPlotSkBidang(no, alokasi);
            const title = alokasi
                ? `${kodeFile} - ${alokasi.judul_pks || '-'} - ${sisaAnggaran}`
                : `PKS ${no}`;
            return `
                <th class="plotting-pks-head" colspan="2" title="${esc(title)}">
                    <span>PKS ${no}</span>
                    ${alokasi ? `<small class="${sisaAnggaranNilai < 0 ? 'is-negative' : ''}">${esc(sisaAnggaran)}</small>` : ''}
                </th>
            `;
        }).join('');
        const roleHeaders = Array.from({ length: jumlahPksPlotting }, (_, idx) => {
            const noPks = idx + 1;
            return `
                <th class="plotting-bidang-name-head" data-col="${esc(colKeyPksPlotSkBidang(noPks, 'nama'))}">Nama</th>
                <th class="plotting-bidang-month-head" data-col="${esc(colKeyPksPlotSkBidang(noPks, 'bulan'))}" title="Jumlah bulan alokasi pada PKS ${noPks}. Nilai 1 berarti penuh 6 bulan, 2/6 berarti 2 bulan, dan 6/6 otomatis menjadi 1.">Bulan</th>
            `;
        }).join('');

        headTabelEksporPlotSkBidang.innerHTML = `
            <tr>
                <th rowspan="2" class="plotting-col-no" data-col="no">No.</th>
                <th rowspan="2" class="plotting-col-nama plotting-col-jabatan-bidang" data-col="jabatan_per_bidang">Jabatan per Bidang</th>
                <th rowspan="2" class="plotting-col-peran" data-col="role_label">Peran</th>
                <th rowspan="2" class="plotting-col-target" data-col="nilai_posisi_display">Nilai Posisi</th>
                ${pksHeaders}
            </tr>
            <tr>${roleHeaders}</tr>
        `;
        colFilterEksporPlotSkBidang?.initBtns();
        colFilterEksporPlotSkBidang?.updateIndicators();
    }

    function renderEksporPlotSkBidang() {
        if (!headTabelEksporPlotSkBidang || !bodyTabelEksporPlotSkBidang) return;
        if (rapihkanAnggotaPlotSkBidangManual(plotSkBidangManual)) simpanPlottingKerma();
        const tabel = document.getElementById('tabelEksporPlotSkBidang');
        if (tabel) {
            const lebarKolomPks = jumlahPksPlotting * 188;
            tabel.style.minWidth = `${560 + lebarKolomPks}px`;
        }
        renderHeaderEksporPlotSkBidang();
        const sumber = dataEksporPlotSkBidangUntukFilter();
        const rows = colFilterEksporPlotSkBidang ? colFilterEksporPlotSkBidang.applyTo(sumber) : sumber;
        const adaFilterKolom = colFilterEksporPlotSkBidang && Object.keys(colFilterEksporPlotSkBidang.colFilters).length > 0;
        if (!rows.length) {
            bodyTabelEksporPlotSkBidang.innerHTML = adaFilterKolom
                ? tableState(4 + (jumlahPksPlotting * 2), 'empty', 'Tidak ada Plot SK Bidang yang cocok', 'Ubah filter pada heading tabel untuk menampilkan data kembali.')
                : tableState(4 + (jumlahPksPlotting * 2), 'empty', 'Belum ada jabatan per bidang', 'Atur Perhitungan Dasar untuk menampilkan jabatan per bidang.');
            return;
        }
        bodyTabelEksporPlotSkBidang.innerHTML = rows.map((row, index) => {
            const pksCells = Array.from({ length: jumlahPksPlotting }, (_, idx) => {
                const noPks = idx + 1;
                const nama = row[colKeyPksPlotSkBidang(noPks, 'nama')] || '';
                const bulan = row[colKeyPksPlotSkBidang(noPks, 'bulan')] || '';
                const key = row[colKeyPksPlotSkBidang(noPks, 'key')] || '';
                const isBulanSk = isPenandaSkTanpaNilaiPlotSk(bulan);
                return `
                    <td class="plotting-bidang-name-cell ${nama ? 'is-filled' : ''}">
                        <select class="form-input plotting-input plotting-bidang-select" data-plot-sk-bidang-key="${esc(key)}" data-plot-sk-bidang-role="${esc(row.role || '')}" data-plot-sk-bidang-field="nama" aria-label="${esc(`Nama ${row.jabatan_per_bidang || ''} PKS ${noPks}`)}">
                            ${htmlOpsiNamaPlotSkBidang(nama, row.role || '')}
                        </select>
                    </td>
                    <td class="plotting-bidang-month-cell ${bulan ? 'is-filled' : ''}${isBulanSk ? ' is-sk-marker' : ''}">
                        <input type="text" inputmode="text" class="form-input plotting-input plotting-bidang-month-input${isBulanSk ? ' is-sk-marker' : ''}" data-plot-sk-bidang-key="${esc(key)}" data-plot-sk-bidang-role="${esc(row.role || '')}" data-plot-sk-bidang-field="bulan" value="${esc(bulan)}" placeholder="-" title="${row.role === 'Anggota' ? 'Anggota otomatis menggunakan penanda SK.' : 'Isi jumlah bulan. Nilai 1 otomatis menjadi 6 bulan; 4/6 menjadi 4 bulan.'}" ${row.role === 'Anggota' ? 'readonly aria-readonly="true"' : ''}>
                    </td>
                `;
                }).join('');
            return `
                <tr>
                    <td class="plotting-col-no">${esc(row.no || index + 1)}</td>
                    <td class="plotting-jabatan-bidang-cell"><strong>${esc(row.jabatan_per_bidang || '-')}</strong></td>
                    <td><span class="badge badge-realisasi-default">${esc(row.role_label || '-')}</span></td>
                    <td class="td-number">${esc(row.nilai_posisi_display || formatRupiahKomaDash(row.nilai_posisi))}</td>
                    ${pksCells}
                </tr>
            `;
        }).join('');
    }

    function syncPlotSkBidangManualInput(target, { normalisasiBulan = false } = {}) {
        if (!target?.dataset?.plotSkBidangKey || !target.dataset.plotSkBidangField) return;
        const field = target.dataset.plotSkBidangField;
        const role = target.dataset.plotSkBidangRole || '';
        const key = target.dataset.plotSkBidangKey;
        const parsed = parseKeyPlotSkBidangManual(key);
        const sebelumnya = getPlotSkBidangManual(parsed.role, parsed.bidangIndex, parsed.noPks);
        let value = target.value || '';
        if (role === 'Anggota') {
            if (field === 'nama' && value.trim()) {
                const pegawai = getPlottingKermaRowByNama(value);
                if (!isStafTargetDistribusiPlotSkBidang(pegawai)) {
                    target.value = sebelumnya.nama || '';
                    window.alert('Anggota hanya dapat diisi oleh staf aktif yang memiliki Target Distribusi lebih dari Rp0,-.');
                    return;
                }
                if (namaSudahDipakaiDalamPksPlotSkBidang(pegawai.nama, parsed.noPks, key)) {
                    target.value = sebelumnya.nama || '';
                    window.alert(`Nama ${pegawai.nama} sudah digunakan pada PKS ${parsed.noPks}. Pilih staf lain agar Anggota tidak double dalam satu PKS.`);
                    return;
                }
                value = String(pegawai.nama || value).trim();
            } else if (field === 'bulan') {
                value = sebelumnya.nama ? 'SK' : '';
                target.value = value;
            }
        }
        if (field === 'bulan' && normalisasiBulan) {
            value = normalisasiBulanManualPlotSkBidang(value, role);
            target.value = value;
        }
        if (field === 'nama' && value.trim() && isBatasanKesesuaianKkPlotSkBidangAktif()) {
            const parsed = parseKeyPlotSkBidangManual(target.dataset.plotSkBidangKey);
            const pegawai = getPlottingKermaRowByNama(value);
            const detail = detailKesesuaianKkPlotSkBidang(pegawai || { nama: value }, role, parsed.bidangIndex);
            if (!detail.cocok) {
                const sebelumnya = getPlotSkBidangManual(role, parsed.bidangIndex, parsed.noPks);
                target.value = sebelumnya.nama || '';
                window.alert(`Nama ${detail.nama} tidak sesuai dengan ${detail.bidang}. KK: ${detail.kelompok}.`);
                return;
            }
        }
        setPlotSkBidangManual(key, field, value);
        if (role === 'Anggota' && field === 'nama') {
            setPlotSkBidangManual(key, 'bulan', value ? 'SK' : '');
            renderEksporPlotSkBidang();
            renderEksporRekapitulasiPlotting();
            renderValidasiBatasanPlotSkBidang();
            return;
        }
        const penyesuaianTarget = sinkronkanPlotSkBidangManualDenganTarget();
        if (penyesuaianTarget.changed) {
            simpanPlottingKerma();
            renderEksporPlotSkBidang();
            renderEksporRekapitulasiPlotting();
            renderValidasiBatasanPlotSkBidang();
            return;
        }
        const isSkMarker = isPenandaSkTanpaNilaiPlotSk(value);
        target.classList.toggle('is-sk-marker', isSkMarker);
        target.closest('td')?.classList.toggle('is-filled', Boolean(String(value || '').trim()));
        target.closest('td')?.classList.toggle('is-sk-marker', isSkMarker);
        renderHeaderEksporPlotSkBidang();
        renderEksporRekapitulasiPlotting();
        renderValidasiBatasanPlotSkBidang();
    }

    function renderInputBebanTargetDistribusi(row, role, displayValue) {
        if (role === 'Anggota') {
            return '<span class="plotting-target-role-na" title="Anggota mengikuti Kepala Administrasi dan tidak memiliki target distribusi">-</span>';
        }
        const value = displayValue && displayValue !== '-' ? displayValue : '';
        return `
            <input
                type="text"
                inputmode="text"
                class="form-input plotting-input plotting-target-beban-input"
                data-target-beban-key="${esc(row.nama_key || row.nama || '')}"
                data-target-beban-role="${esc(role)}"
                value="${esc(value)}"
                placeholder="-"
                title="${esc(`${labelJabatanPlotting(role)} - isi seperti 1, 2/6, atau 1+(2/6). Kosongkan untuk kembali ke hasil Plot SK Bidang.`)}"
            >
        `;
    }

    function syncTargetDistribusiBebanManualInput(target) {
        if (!target?.dataset?.targetBebanKey || !target.dataset.targetBebanRole) return;
        const prepared = siapkanTargetDistribusiBebanManualBerikutnya(
            target.dataset.targetBebanKey,
            target.dataset.targetBebanRole,
            target.value
        );
        const validasi = validasiKapasitasBebanTargetDistribusi(prepared);
        if (!validasi.ok) {
            tampilkanAlertMulaiPlotting(alertSimpanTargetDistribusiMulai, validasi.message, true);
            renderEksporTargetDistribusiPlotting();
            return;
        }
        const normalized = setTargetDistribusiBebanManual(
            target.dataset.targetBebanKey,
            target.dataset.targetBebanRole,
            target.value
        );
        if (normalized) target.value = normalized.tersimpan && normalized.value !== '0' ? normalized.value : (normalized.tersimpan ? '0' : '');
        renderEksporTargetDistribusiPlotting();
        renderEksporRekapitulasiPlotting();
        renderValidasiBatasanPlotSkBidang();
        const masukan = buatMasukanManualTargetDistribusi(targetDistribusiBebanManual);
        tampilkanAlertMulaiPlotting(
            alertSimpanTargetDistribusiMulai,
            `Perubahan manual tersimpan. ${masukan.pesan}`,
            !masukan.ok
        );
        updateStatusMulaiPlottingKerma();
        void cekStatusManualTargetDistribusiSetelahEdit();
    }

    function renderEksporTargetDistribusiPlotting() {
        if (!bodyTabelEksporPlottingTargetDistribusi) return;
        try {
            const sumber = dataEksporTargetDistribusiUntukFilter();
            const rows = colFilterEksporTargetDistribusi ? colFilterEksporTargetDistribusi.applyTo(sumber) : sumber;
            const adaFilterKolom = colFilterEksporTargetDistribusi && Object.keys(colFilterEksporTargetDistribusi.colFilters).length > 0;
            const adaHasilSimulasiTarget = Object.keys(targetDistribusiBebanManual || {}).length > 0;
            renderRingkasanPosisiTargetDistribusi(sumber);
            const totalTargetDistribusi = rows.reduce((sum, row) => sum + (Number(row.target_distribusi) || 0), 0);
            const totalRealisasiDistribusi = rows.reduce((sum, row) => sum + (Number(row.total_realisasi) || 0), 0);
            const totalSelisihRealisasi = totalRealisasiDistribusi - totalTargetDistribusi;
            setText(eksporTargetDistribusiTotal, formatRupiahKomaDash(totalTargetDistribusi));
            setText(eksporTargetDistribusiRealisasiTotal, formatRupiahKomaDash(totalRealisasiDistribusi));
            setText(eksporTargetDistribusiSelisihTotal, formatRupiahKomaDash(totalSelisihRealisasi));
            if (eksporTargetDistribusiSelisihTotal) {
                eksporTargetDistribusiSelisihTotal.classList.toggle('is-warning', totalSelisihRealisasi < 0);
                eksporTargetDistribusiSelisihTotal.classList.toggle('is-match', Math.abs(totalSelisihRealisasi) < 1);
                eksporTargetDistribusiSelisihTotal.classList.toggle('is-info', totalSelisihRealisasi > 0);
            }
            const kebutuhanPksTarget = hitungKebutuhanPksTargetDistribusi(sumber);
            setText(eksporTargetDistribusiKebutuhanPks, formatJumlahPks(kebutuhanPksTarget.jumlah));
            setText(eksporTargetDistribusiPksDipakai, adaHasilSimulasiTarget ? 'Menjadi batas jabatan' : '-');
            if (eksporTargetDistribusiRealisasiCard) eksporTargetDistribusiRealisasiCard.hidden = !adaHasilSimulasiTarget;
            if (eksporTargetDistribusiSelisihCard) eksporTargetDistribusiSelisihCard.hidden = !adaHasilSimulasiTarget;
            if (eksporTargetDistribusiPksDipakaiCard) {
                eksporTargetDistribusiPksDipakaiCard.hidden = !adaHasilSimulasiTarget;
                eksporTargetDistribusiPksDipakaiCard.title = adaHasilSimulasiTarget
                    ? 'Sisa PAGU PKS aktif digunakan untuk menghitung kapasitas posisi kosong setiap jabatan. Penempatan rinci antar-PKS tetap diperiksa saat Plot SK.'
                    : '';
            }
            if (eksporTargetDistribusiKebutuhanPksCard) {
                eksporTargetDistribusiKebutuhanPksCard.hidden = !adaHasilSimulasiTarget;
                if (!adaHasilSimulasiTarget) {
                    eksporTargetDistribusiKebutuhanPksCard.title = '';
                } else if (kebutuhanPksTarget.sumber === 'role' && kebutuhanPksTarget.kebutuhanRole?.role) {
                    const role = kebutuhanPksTarget.kebutuhanRole.role;
                    const totalSlot = Number(kebutuhanPksTarget.totalSlotPerRole?.[role]) || 0;
                    const kapasitas = hitungKapasitasRolePlotSk(role);
                    eksporTargetDistribusiKebutuhanPksCard.title = `Informasi teoritis untuk Plot SK, bukan syarat Simulasi/Optimalisasi. Kebutuhan ditentukan oleh kapasitas ${labelJabatanPlotting(role)}: ${totalSlot.toLocaleString('id-ID')} slot / ${kapasitas.toLocaleString('id-ID')} posisi per PKS. Personil terbanyak: ${kebutuhanPksTarget.kebutuhanPersonil?.nama || '-'} (${formatJumlahPks(kebutuhanPksTarget.kebutuhanPersonil?.jumlah || 0)}).`;
                } else {
                    eksporTargetDistribusiKebutuhanPksCard.title = kebutuhanPksTarget.nama
                        ? `Informasi teoritis untuk Plot SK, bukan syarat Simulasi/Optimalisasi. Kebutuhan PKS ditentukan oleh personil dengan kebutuhan terbanyak: ${kebutuhanPksTarget.nama}.`
                        : 'Informasi teoritis untuk Plot SK, bukan syarat Simulasi/Optimalisasi.';
                }
            }
            if (!rows.length) {
                bodyTabelEksporPlottingTargetDistribusi.innerHTML = adaFilterKolom
                    ? tableState(13, 'empty', 'Tidak ada Target Distribusi yang cocok', 'Ubah filter pada heading tabel untuk menampilkan data kembali.')
                    : tableState(13, 'empty', 'Belum ada Target Distribusi', 'Target Distribusi hanya menampilkan pegawai aktif dengan target lebih dari Rp 0,-.');
                return;
            }
            bodyTabelEksporPlottingTargetDistribusi.innerHTML = rows.map((row, index) => `
                <tr>
                    <td>${esc(row.no || index + 1)}</td>
                    <td><strong>${esc(row.nama || '-')}</strong></td>
                    <td>${esc(row.peran || '-')}</td>
                    <td class="td-truncate" title="${esc(row.jabatan_sbm_display || '-')}">${esc(row.jabatan_sbm_display || '-')}</td>
                    <td class="td-number">${esc(row.target_distribusi_display || formatRupiahKomaDash(row.target_distribusi))}</td>
                    <td class="td-number">${renderInputBebanTargetDistribusi(row, 'PJ', row.pj_display)}</td>
                    <td class="td-number">${renderInputBebanTargetDistribusi(row, 'Pengarah', row.pg_display)}</td>
                    <td class="td-number">${renderInputBebanTargetDistribusi(row, 'Ketua', row.k_display)}</td>
                    <td class="td-number">${renderInputBebanTargetDistribusi(row, 'Kepala Admin', row.ka_display)}</td>
                    <td class="td-number">${renderInputBebanTargetDistribusi(row, 'Anggota', row.a_display)}</td>
                    <td class="td-number">${esc(row.total_realisasi_display || formatRupiahKomaDash(row.total_realisasi))}</td>
                    <td class="td-number ${Number(row.selisih) < 0 ? 'realisasi-sisa-negative' : ''}">${esc(row.selisih_display || formatRupiahKomaDash(row.selisih))}</td>
                    <td class="td-truncate" title="${esc(row.alasan_simulasi || '-')}">${esc(row.alasan_simulasi || '-')}</td>
                </tr>
            `).join('');
        } catch (err) {
            console.error('Gagal render tabel Target Distribusi.', err);
            const rowsDasar = getRowsEksporTargetDistribusi();
            renderRingkasanPosisiTargetDistribusi(rowsDasar);
            setText(eksporTargetDistribusiTotal, formatRupiahKomaDash(
                rowsDasar.reduce((sum, row) => sum + hitungTargetDistribusiRow(row), 0)
            ));
            setText(eksporTargetDistribusiRealisasiTotal, 'Rp 0,-');
            if (eksporTargetDistribusiRealisasiCard) eksporTargetDistribusiRealisasiCard.hidden = true;
            setText(eksporTargetDistribusiSelisihTotal, 'Rp 0,-');
            if (eksporTargetDistribusiSelisihCard) eksporTargetDistribusiSelisihCard.hidden = true;
            setText(eksporTargetDistribusiKebutuhanPks, '0 PKS');
            setText(eksporTargetDistribusiPksDipakai, 'Belum dihitung');
            if (eksporTargetDistribusiKebutuhanPksCard) {
                eksporTargetDistribusiKebutuhanPksCard.hidden = true;
                eksporTargetDistribusiKebutuhanPksCard.title = '';
            }
            if (eksporTargetDistribusiPksDipakaiCard) {
                eksporTargetDistribusiPksDipakaiCard.hidden = true;
                eksporTargetDistribusiPksDipakaiCard.title = '';
            }
            bodyTabelEksporPlottingTargetDistribusi.innerHTML = rowsDasar.length
                ? rowsDasar.map((row, index) => `
                    <tr>
                        <td>${index + 1}</td>
                        <td><strong>${esc(row.nama || '-')}</strong></td>
                        <td>${esc(row.peran || '-')}</td>
                        <td class="td-truncate" title="${esc(row.jabatan_sbm || '-')}">${esc(row.jabatan_sbm || '-')}</td>
                        <td class="td-number">${formatRupiahKomaDash(hitungTargetDistribusiRow(row))}</td>
                        <td class="td-number">-</td>
                        <td class="td-number">-</td>
                        <td class="td-number">-</td>
                        <td class="td-number">-</td>
                        <td class="td-number">-</td>
                        <td class="td-number">Rp 0,-</td>
                        <td class="td-number realisasi-sisa-negative">${formatRupiahKomaDash(-hitungTargetDistribusiRow(row))}</td>
                        <td class="td-truncate">Target Distribusi belum dapat dianalisis.</td>
                    </tr>
                `).join('')
                : tableState(13, 'error', 'Target Distribusi belum dapat ditampilkan', 'Data pegawai aktif dengan Target Distribusi tidak ditemukan.');
        }
    }

    function setStatusNilaiSelisihRekap(el, value) {
        if (!el) return;
        const nilai = Number(value) || 0;
        el.classList.toggle('is-warning', nilai < 0);
        el.classList.toggle('is-match', Math.abs(nilai) < 1);
        el.classList.toggle('is-info', nilai > 0);
    }

    function renderRingkasanRekapitulasiPlotting(rows = []) {
        const totalDosen = rows
            .filter(row => isDosenDistribusi(row))
            .reduce((sum, row) => sum + (Number(row.selisih_plot) || 0), 0);
        const totalStaf = rows
            .filter(row => isStafDistribusi(row))
            .reduce((sum, row) => sum + (Number(row.selisih_plot) || 0), 0);
        setText(eksporRekapSelisihDosen, formatRupiahKomaDash(totalDosen));
        setText(eksporRekapSelisihStaf, formatRupiahKomaDash(totalStaf));
        setStatusNilaiSelisihRekap(eksporRekapSelisihDosen, totalDosen);
        setStatusNilaiSelisihRekap(eksporRekapSelisihStaf, totalStaf);
    }

    function hasilSimulasiTerpilihUntukDihapus() {
        if (!bodyTabelDaftarHasilSimulasi) return [];
        return Array.from(bodyTabelDaftarHasilSimulasi.querySelectorAll('input[data-hasil-simulasi-select]:checked'))
            .map(input => String(input.dataset.hasilSimulasiSelect || '').trim())
            .filter(Boolean);
    }

    function perbaruiAksiHapusSimulasi() {
        const checks = bodyTabelDaftarHasilSimulasi
            ? Array.from(bodyTabelDaftarHasilSimulasi.querySelectorAll('input[data-hasil-simulasi-select]'))
            : [];
        const terpilih = checks.filter(input => input.checked);
        if (btnHapusSimulasi) btnHapusSimulasi.disabled = terpilih.length === 0;
        if (checkAllHasilSimulasi) {
            checkAllHasilSimulasi.checked = checks.length > 0 && terpilih.length === checks.length;
            checkAllHasilSimulasi.indeterminate = terpilih.length > 0 && terpilih.length < checks.length;
            checkAllHasilSimulasi.disabled = checks.length === 0;
        }
    }

    function bukaModalHapusSimulasi(ids = hasilSimulasiTerpilihUntukDihapus()) {
        const idsValid = [...new Set((Array.isArray(ids) ? ids : []).map(id => String(id || '').trim()).filter(id =>
            daftarHasilSimulasiPlotting.some(item => item.id === id)
        ))];
        if (!idsValid.length) {
            perbaruiAksiHapusSimulasi();
            return;
        }
        hasilSimulasiIdsMenungguDihapus = idsValid;
        const jumlah = idsValid.length;
        const label = jumlah === 1 ? 'sesi simulasi yang dipilih' : `${jumlah} sesi simulasi yang dipilih`;
        if (pesanKonfirmasiHapusSimulasi) {
            pesanKonfirmasiHapusSimulasi.textContent = `Apakah Anda yakin akan menghapus ${label}? Data yang dihapus tidak dapat dipulihkan.`;
        }
        if (modalHapusSimulasi) modalHapusSimulasi.style.display = 'flex';
        setTimeout(() => btnBatalHapusSimulasi?.focus(), 0);
    }

    function tutupModalHapusSimulasi() {
        if (modalHapusSimulasi) modalHapusSimulasi.style.display = 'none';
        hasilSimulasiIdsMenungguDihapus = [];
    }

    function hapusSimulasiTerpilih() {
        const ids = new Set(hasilSimulasiIdsMenungguDihapus);
        const daftarYangDihapus = daftarHasilSimulasiPlotting.filter(item => ids.has(item.id));
        if (!daftarYangDihapus.length) {
            tutupModalHapusSimulasi();
            return;
        }
        const sesiAktifDihapus = ids.has(sesiSimulasiAktifId);
        const namaYangDihapus = daftarYangDihapus.map(item => item.nama).filter(Boolean);
        daftarHasilSimulasiPlotting = normalisasiDaftarHasilSimulasi(
            daftarHasilSimulasiPlotting.filter(item => !ids.has(item.id))
        );
        daftarNominatifBySimulasi = Object.fromEntries(
            Object.entries(daftarNominatifBySimulasi || {}).filter(([id]) => !ids.has(id))
        );
        pengajuanPengeluaranBySimulasi = Object.fromEntries(
            Object.entries(pengajuanPengeluaranBySimulasi || {}).filter(([id]) => !ids.has(id))
        );
        if (sesiAktifDihapus) {
            nomorSkByPksTersimpan = {};
            sesiSimulasiAktifId = '';
            modeSesiSimulasi = 'edit';
            sesiSimulasiDirty = false;
            const snapshotKosong = snapshotSesiSimulasiKosong('', '');
            terapkanPayloadPlottingKerma({
                ...snapshotKosong,
                daftarHasilSimulasiPlotting,
                sesiSimulasiAktifId: '',
                nomorSkByPksTersimpan: {}
            });
            daftarHasilSimulasiPlotting = normalisasiDaftarHasilSimulasi(daftarHasilSimulasiPlotting);
        }
        simpanPlottingKerma({ syncSession: false });
        tutupModalHapusSimulasi();
        renderPlottingKermaViews();
        renderDaftarHasilSimulasiPlotting();
        setTabEksporPlottingKerma('hasilSimulasi');
        setStatusMulaiPlotting(
            `${namaYangDihapus.length} simulasi berhasil dihapus.`,
            'success'
        );
    }

    function renderDaftarHasilSimulasiPlotting() {
        if (!bodyTabelDaftarHasilSimulasi) return;
        const daftar = daftarHasilSimulasiPlotting;
        if (!daftar.length) {
            bodyTabelDaftarHasilSimulasi.innerHTML = tableState(10, 'empty', 'Belum ada sesi simulasi', 'Klik Buat Simulasi Baru untuk membuat ruang kerja per periode.');
            perbaruiAksiHapusSimulasi();
            return;
        }
        bodyTabelDaftarHasilSimulasi.innerHTML = daftar.map((item, index) => {
            const ringkasan = item.ringkasan || {};
            const statusClass = item.status === STATUS_SESI_SIMULASI.DRAF ? 'is-draft'
                : item.status === STATUS_SESI_SIMULASI.PERLU_PERBAIKAN ? 'is-fix'
                    : item.status === STATUS_SESI_SIMULASI.SIAP_GENERATE_SK ? 'is-ready'
                        : item.status === STATUS_SESI_SIMULASI.SELESAI ? 'is-done'
                            : 'is-empty';
            const aktif = item.id === sesiSimulasiAktifId;
            const dapatDilanjutkan = [STATUS_SESI_SIMULASI.DRAF, STATUS_SESI_SIMULASI.PERLU_PERBAIKAN].includes(item.status);
            return `
                <tr class="${aktif ? 'is-active-session' : ''}">
                    <td class="plotting-simulation-select-cell"><input type="checkbox" data-hasil-simulasi-select="${esc(item.id)}" aria-label="Pilih ${esc(item.nama || 'hasil simulasi')}"></td>
                    <td>${index + 1}</td>
                    <td>
                        <strong>${esc(item.nama || '-')}</strong>
                        <small class="plotting-saved-simulation-period">${esc(item.deskripsi || ringkasan.periode || `${item.periode_awal || '-'} sampai ${item.periode_akhir || '-'}`)}</small>
                    </td>
                    <td class="plotting-saved-simulation-status"><span class="plotting-session-badge ${statusClass}">${esc(item.status)}</span></td>
                    <td class="plotting-saved-simulation-stage">${esc(item.tahap || TAHAP_SESI_SIMULASI.PERSIAPAN)}</td>
                    <td>${esc(formatTanggalWaktuSimulasi(item.updated_at || item.saved_at))}</td>
                    <td class="td-number">${esc(formatJumlahPks(Number(ringkasan.jumlahPks) || item.snapshot?.jumlahPksPlotting || 0))}</td>
                    <td class="td-number ${Number(ringkasan.selisihDosen) < 0 ? 'realisasi-sisa-warning' : ''}">${esc(formatRupiahKomaDash(ringkasan.selisihDosen))}</td>
                    <td class="td-number ${Number(ringkasan.selisihStaf) < 0 ? 'realisasi-sisa-warning' : ''}">${esc(formatRupiahKomaDash(ringkasan.selisihStaf))}</td>
                    <td>
                        <div class="pegawai-row-actions">
                            ${dapatDilanjutkan ? `<button type="button" class="btn-row-edit" data-hasil-simulasi-action="continue" data-hasil-simulasi-id="${esc(item.id)}">Lanjutkan</button>` : ''}
                            <button type="button" class="btn-row-edit" data-hasil-simulasi-action="view" data-hasil-simulasi-id="${esc(item.id)}">Buka</button>
                            ${[STATUS_SESI_SIMULASI.SIAP_GENERATE_SK, STATUS_SESI_SIMULASI.SELESAI].includes(item.status) ? `<button type="button" class="btn-row-edit" data-hasil-simulasi-action="sk" data-hasil-simulasi-id="${esc(item.id)}">Buat SK</button>` : ''}
                        </div>
                    </td>
                </tr>
            `;
        }).join('');
        perbaruiAksiHapusSimulasi();
    }

    function tampilkanAlertSimpanHasilSimulasi(message = '', type = 'error') {
        if (!alertSimpanHasilSimulasi) return;
        alertSimpanHasilSimulasi.textContent = message;
        alertSimpanHasilSimulasi.className = `form-alert form-alert--${type}`;
        alertSimpanHasilSimulasi.style.display = message ? '' : 'none';
    }

    function defaultNamaHasilSimulasi() {
        const now = new Date();
        const tanggal = now.toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' });
        return `Simulasi ${tanggal}`;
    }

    function bukaModalSimpanHasilSimulasi() {
        if (sesiSimulasiAktif()) {
            tetapkanSesiSimulasiSebagaiFinal();
            return;
        }
        window.alert('Buat Simulasi Baru terlebih dahulu. Hasil simulasi harus berada di dalam Sesi Simulasi.');
        setTabEksporPlottingKerma('hasilSimulasi');
        return;
        /* Legacy fallback retained for old local data only. */
        const adaPlot = Object.keys(plotSkBidangManual || {}).length > 0;
        const adaRekap = dataEksporRekapitulasiUntukFilter().length > 0;
        if (!adaPlot || !adaRekap) {
            tampilkanAlertMulaiPlotting(
                alertSimpanTargetDistribusiMulai,
                'Hasil simulasi belum dapat disimpan karena Plot SK Bidang atau Kontrol belum tersedia.',
                true
            );
            return;
        }
        if (inputNamaHasilSimulasi) inputNamaHasilSimulasi.value = defaultNamaHasilSimulasi();
        tampilkanAlertSimpanHasilSimulasi('');
        if (modalSimpanHasilSimulasi) modalSimpanHasilSimulasi.style.display = 'flex';
        setTimeout(() => {
            inputNamaHasilSimulasi?.focus();
            inputNamaHasilSimulasi?.select();
        }, 0);
    }

    function tutupModalSimpanHasilSimulasi() {
        if (modalSimpanHasilSimulasi) modalSimpanHasilSimulasi.style.display = 'none';
        tampilkanAlertSimpanHasilSimulasi('');
    }

    function simpanHasilSimulasiDariModal() {
        if (sesiSimulasiAktif()) {
            tetapkanSesiSimulasiSebagaiFinal();
            tutupModalSimpanHasilSimulasi();
            return;
        }
        const nama = String(inputNamaHasilSimulasi?.value || '').trim();
        if (!nama) {
            tampilkanAlertSimpanHasilSimulasi('Nama simulasi wajib diisi.');
            inputNamaHasilSimulasi?.focus();
            return;
        }
        const now = new Date();
        const item = {
            id: `simulasi-${now.getTime()}-${Math.random().toString(36).slice(2, 8)}`,
            nama,
            saved_at: now.toISOString(),
            ringkasan: hitungRingkasanHasilSimulasiAktif(),
            nomor_sk_by_pks: { ...nomorSkByPksTersimpan },
            snapshot: buatSnapshotHasilSimulasiAktif()
        };
        daftarHasilSimulasiPlotting = normalisasiDaftarHasilSimulasi([item, ...daftarHasilSimulasiPlotting]);
        resetDataAktifSetelahSimpanHasilSimulasi();
        simpanPlottingKerma();
        tutupModalSimpanHasilSimulasi();
        renderDaftarHasilSimulasiPlotting();
        setTabEksporPlottingKerma('hasilSimulasi');
    }

    function bukaHasilSimulasiTersimpan(id, { viewOnly = false } = {}) {
        const item = daftarHasilSimulasiPlotting.find(simulasi => simulasi.id === id);
        if (!item) return;
        if (!konfirmasiPindahSesiSimulasi()) return;
        const arsip = daftarHasilSimulasiPlotting;
        terapkanPayloadPlottingKerma({
            ...item.snapshot,
            daftarHasilSimulasiPlotting: arsip,
            sesiSimulasiAktifId: item.id
        });
        daftarHasilSimulasiPlotting = arsip;
        sesiSimulasiAktifId = item.id;
        modeSesiSimulasi = viewOnly || sesiSimulasiTerkunci(item) ? 'view' : 'edit';
        sesiSimulasiDirty = false;
        simpanPlottingKerma({ syncSession: false });
        renderPlottingKermaViews();
        setTabEksporPlottingKerma('rekapitulasi');
    }

    function lanjutkanHasilSimulasiTersimpan(id) {
        const item = daftarHasilSimulasiPlotting.find(simulasi => simulasi.id === id);
        if (!item || !konfirmasiPindahSesiSimulasi()) return;
        if (![STATUS_SESI_SIMULASI.DRAF, STATUS_SESI_SIMULASI.PERLU_PERBAIKAN].includes(item.status)) {
            return bukaHasilSimulasiTersimpan(id);
        }
        bukaHasilSimulasiTersimpan(id);
        modeSesiSimulasi = 'edit';
        renderSesiSimulasiBar();
    }

    function tampilkanAlertGenerateSkTim(message = '', type = 'error') {
        if (!alertGenerateSkTim) return;
        alertGenerateSkTim.textContent = message;
        alertGenerateSkTim.className = `form-alert form-alert--${type}`;
        alertGenerateSkTim.style.display = message ? '' : 'none';
    }

    function programDariIdAtauKodeSkTim(id = '') {
        const key = String(id || '').trim();
        if (!key) return null;
        return allData.find(item =>
            String(item.id_program || '').trim() === key ||
            String(item.kode_file || '').trim() === key
        ) || null;
    }

    function daftarPksDariHasilSimulasiSkTim(item = {}) {
        const snapshot = item.snapshot || {};
        const ids = Array.isArray(snapshot.daftarPksTerpilihPlotting)
            ? snapshot.daftarPksTerpilihPlotting.map(id => String(id || '').trim())
            : [];
        const jumlah = Math.max(0, Math.floor(Number(snapshot.jumlahPksPlotting) || ids.length));
        return Array.from({ length: jumlah }, (_, index) => {
            const id = ids[index] || '';
            const program = programDariIdAtauKodeSkTim(id) || {};
            return {
                noPks: index + 1,
                id,
                id_program: program.id_program || id,
                kode_file: program.kode_file || id,
                nama_mitra: program.nama_mitra || '-',
                judul_pks: program.judul_pks || '-'
            };
        }).filter(row => row.id);
    }

    function tahunAkademikDariSnapshotSkTim(snapshot = {}) {
        const awal = String(snapshot?.periodePengelolaKerma?.awal || '').trim();
        const match = awal.match(/^(\d{4})-(\d{2})$/);
        if (!match) return '';
        const tahun = Number(match[1]);
        const bulan = Number(match[2]);
        if (!Number.isFinite(tahun) || !Number.isFinite(bulan)) return '';
        const mulai = bulan >= 7 ? tahun : tahun - 1;
        return `${mulai}/${mulai + 1}`;
    }

    function tanggalBerlakuSampaiDariSnapshotSkTim(snapshot = {}) {
        const akhir = String(snapshot?.periodePengelolaKerma?.akhir || '').trim();
        const match = akhir.match(/^(\d{4})-(\d{2})$/);
        if (!match) {
            const now = parseInputDate(todayInputDate()) || new Date();
            return `${now.getFullYear()}-12-31`;
        }
        const tahun = Number(match[1]);
        const bulan = Number(match[2]);
        if (!Number.isFinite(tahun) || !Number.isFinite(bulan)) return '';
        const d = new Date(tahun, bulan, 0);
        return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    }

    function nomorSkTersimpanUntukPks(item = {}, row = {}) {
        const nomorSkByPks = normalisasiNomorSkByPks(item.nomor_sk_by_pks);
        return nomorSkByPks[String(row.id || '').trim()]
            || nomorSkByPks[String(row.kode_file || '').trim()]
            || nomorSkByPks[String(row.noPks || '').trim()]
            || nomorSkByPksTersimpan[String(row.id || '').trim()]
            || nomorSkByPksTersimpan[String(row.kode_file || '').trim()]
            || nomorSkByPksTersimpan[String(row.noPks || '').trim()]
            || '';
    }

    function periodeNominatifDariSnapshot(snapshot = {}) {
        const awal = parseBulanPeriode(snapshot?.periodePengelolaKerma?.awal);
        const akhir = parseBulanPeriode(snapshot?.periodePengelolaKerma?.akhir);
        if (!awal || !akhir) return { awal: null, akhir: null, durasi: 0, label: '-' };
        const durasi = ((akhir.tahun - awal.tahun) * 12) + akhir.bulan - awal.bulan + 1;
        const labelAwal = `${labelBulanPanjang(awal.bulan)} ${awal.tahun}`;
        const labelAkhir = `${labelBulanPanjang(akhir.bulan)} ${akhir.tahun}`;
        return {
            awal,
            akhir,
            durasi: durasi > 0 ? durasi : 0,
            label: durasi === 1 ? labelAwal : `${labelAwal} - ${labelAkhir}`
        };
    }

    function konfigurasiRoleNominatif(snapshot = {}, role = '') {
        const daftarRows = Array.isArray(snapshot?.perhitunganDasarPlotting?.rows)
            ? snapshot.perhitunganDasarPlotting.rows
            : [];
        const row = daftarRows.find(item => item?.jabatan === role) || {};
        const periode = periodeNominatifDariSnapshot(snapshot);
        return {
            tarif: tarifPlotting(row.tarif ?? snapshot?.tarifMasterJabatanPlotting?.[role] ?? tarifDefaultJabatanPlotting[role]),
            durasi: angkaDesimalPlotting(row.durasi) || periode.durasi,
            personil: Math.max(0, Math.floor(angkaDesimalPlotting(row.personil_per_kerma ?? (personilPerKermaDefault[role] ?? 0))))
        };
    }

    function labelJabatanNominatif(snapshot = {}, role = '', index = 0) {
        const konfigurasi = normalisasiKonfigurasiJabatanBidangPlotting(snapshot?.jabatanBidangPlottingKerma);
        const aktif = Array.isArray(konfigurasi?.[role])
            ? konfigurasi[role].filter(item => item?.aktif !== false && item?.nama)
            : [];
        if (aktif[index]?.nama) return aktif[index].nama;
        const defaultLabels = Array.isArray(bidangRolePlottingKerma[role]) ? bidangRolePlottingKerma[role] : [];
        if (defaultLabels[index]) return defaultLabels[index];
        const label = namaJabatanPlotting(role);
        const baseline = Math.max(defaultLabels.length, aktif.length);
        return `${label} - Tambahan ${Math.max(1, index - baseline + 1)}`;
    }

    function hitungVolumeNominatif(value, durasi) {
        const raw = String(value || '').trim();
        if (!raw || /^sk$/i.test(raw)) return 0;
        return raw.replace(/＋/g, '+').split('+').map(term => term.trim()).filter(Boolean).reduce((sum, term) => {
            const fraction = term.replace(/[()]/g, '').match(/^(-?\d+(?:[,.]\d+)?)\s*\/\s*(-?\d+(?:[,.]\d+)?)$/);
            if (fraction) return sum + Math.max(0, angkaDesimalPlotting(fraction[1]));
            const angka = Math.max(0, angkaDesimalPlotting(term));
            return sum + (angka === 1 && durasi > 0 ? durasi : angka);
        }, 0);
    }

    function namaLengkapNominatif(row = {}) {
        return [row.gelar_depan, row.nama, row.gelar_belakang].map(value => String(value || '').trim()).filter(Boolean).join(' ');
    }

    function buatBarisDaftarNominatif(snapshot = {}, item = {}, pks = {}, role = '', bidangIndex = 0, entry = {}, employeeMap = new Map()) {
        const konfigurasi = konfigurasiRoleNominatif(snapshot, role);
        const periode = periodeNominatifDariSnapshot(snapshot);
        const markerSk = role === 'Anggota' || isPenandaSkTanpaNilaiPlotSk(entry.bulan);
        const volume = markerSk ? 0 : hitungVolumeNominatif(entry.bulan, konfigurasi.durasi || periode.durasi);
        const nilaiSatuan = Math.max(0, konfigurasi.tarif);
        const totalHonor = nilaiSatuan * volume;
        const employee = employeeMap.get(normalisasiNamaPegawaiPlotting(entry.nama)) || {};
        const months = Object.fromEntries(bulanDaftarNominatif.map((nama, index) => {
            const nomorBulan = index + 1;
            const dalamPeriode = periode.awal && periode.akhir
                && ((nomorBulan - periode.awal.bulan + 12) % 12) < periode.durasi
                && (periode.awal.tahun === periode.akhir.tahun || nomorBulan >= periode.awal.bulan || periode.awal.tahun < periode.akhir.tahun);
            const offset = periode.awal ? ((nomorBulan - periode.awal.bulan + 12) % 12) : -1;
            const terisi = !markerSk && dalamPeriode && offset >= 0 && offset < volume;
            return [nama, terisi ? nilaiSatuan : 0];
        }));
        const total = Object.values(months).reduce((sum, value) => sum + (Number(value) || 0), 0);
        const nomorSk = nomorSkTersimpanUntukPks(item, pks);
        return normalisasiBarisDaftarNominatif({
            nip: employee.nip || employee.no_pegawai || '',
            nama: namaLengkapNominatif(employee) || entry.nama,
            no_sk: nomorSk,
            jabatan: labelJabatanNominatif(snapshot, role, bidangIndex),
            kode_file: pks.kode_file || pks.id_program || pks.id || '',
            judul_kegiatan: pks.judul_pks || '',
            periode: periode.label,
            satuan_honor: 'Orang Bulan',
            tarif_maksimal: nilaiSatuan,
            nilai_satuan: nilaiSatuan,
            volume,
            total_honor: totalHonor,
            bulan: months,
            total,
            selisih: totalHonor - total,
            keterangan: markerSk ? 'SK' : ''
        });
    }

    function buatBarisDaftarNominatifDariSnapshot(item = {}, pks = {}) {
        const snapshot = item.snapshot || {};
        const manual = snapshot.plotSkBidangManual && typeof snapshot.plotSkBidangManual === 'object'
            ? snapshot.plotSkBidangManual
            : {};
        const employeeMap = new Map((Array.isArray(snapshot.rows) ? snapshot.rows : []).map(row => [
            normalisasiNamaPegawaiPlotting(row.nama), row
        ]));
        const rows = [];
        rolePlottingKerma.forEach(role => {
            const konfigurasi = konfigurasiRoleNominatif(snapshot, role);
            for (let bidangIndex = 0; bidangIndex < konfigurasi.personil; bidangIndex += 1) {
                const key = keyPlotSkBidangManual(role, bidangIndex, pks.noPks);
                const entry = manual[key];
                if (!entry?.nama) continue;
                rows.push(buatBarisDaftarNominatif(snapshot, item, pks, role, bidangIndex, entry, employeeMap));
            }
        });
        return rows;
    }

    function pksNominatifUntukSimulasi(item = {}) {
        return daftarPksDariHasilSimulasiSkTim(item);
    }

    function fileNominatifTersimpan(simulationId = '', kodeFile = '') {
        return daftarNominatifBySimulasi?.[String(simulationId)]?.[String(kodeFile)] || null;
    }

    function setInfoDaftarNominatif(message = '', isError = false) {
        if (!infoDaftarNominatif) return;
        infoDaftarNominatif.textContent = message;
        infoDaftarNominatif.classList.toggle('is-error', Boolean(isError));
    }

    function pengajuanPengeluaranUntukFile(simulationId = '', kodeFile = '') {
        return pengajuanPengeluaranBySimulasi?.[String(simulationId)]?.[String(kodeFile)] || null;
    }

    function pengajuanPengeluaranTerkunci(file = null) {
        return Boolean(file && [
            STATUS_PENGAJUAN_PENGELUARAN.DIAJUKAN,
            STATUS_PENGAJUAN_PENGELUARAN.DIPROSES,
            STATUS_PENGAJUAN_PENGELUARAN.SELESAI
        ].includes(file.status));
    }

    function ringkasanNominalNominatif(rows = []) {
        const daftar = Array.isArray(rows) ? rows : [];
        return {
            totalPengajuan: daftar.reduce((sum, row) => sum + (Number(row.total_honor) || 0), 0),
            totalBulanan: daftar.reduce((sum, row) => sum + (Number(row.total) || 0), 0),
            jumlahPenerimaHonor: daftar.filter(row => (Number(row.total_honor) || 0) > 0).length
        };
    }

    function kodeFileNominatifTerpilih() {
        return Array.from(bodyTabelDaftarNominatifKodeFile?.querySelectorAll('[data-nominatif-code-check]:checked') || [])
            .map(input => String(input.dataset.nominatifCodeCheck || '').trim())
            .filter(Boolean);
    }

    function perbaruiAksiKodeFileNominatif() {
        const item = daftarHasilSimulasiPlotting.find(candidate => candidate.id === nominatifSimulasiDipilihId);
        const selected = kodeFileNominatifTerpilih();
        const savedMap = item ? daftarNominatifBySimulasi[item.id] || {} : {};
        const pending = selected.filter(kode => {
            const file = savedMap[kode];
            return file?.rows?.length && !pengajuanPengeluaranTerkunci(pengajuanPengeluaranUntukFile(item?.id, kode));
        });
        if (btnDownloadDaftarNominatif) btnDownloadDaftarNominatif.disabled = selected.length === 0;
        if (btnAjukanDaftarNominatif) {
            btnAjukanDaftarNominatif.disabled = pending.length === 0;
            btnAjukanDaftarNominatif.title = pending.length
                ? `Ajukan ${pending.length} Kode File ke Pengeluaran`
                : 'Pilih Kode File yang sudah disimpan terlebih dahulu';
        }
    }

    function renderPilihanDaftarNominatif() {
        if (!selectDaftarNominatifSimulasi || !selectDaftarNominatifKodeFile) return;
        const daftarResmi = daftarHasilSimulasiPlotting.filter(item => [STATUS_SESI_SIMULASI.SIAP_GENERATE_SK, STATUS_SESI_SIMULASI.SELESAI].includes(item.status));
        const simulationIdValid = daftarResmi.some(item => item.id === nominatifSimulasiDipilihId);
        if (!simulationIdValid) nominatifSimulasiDipilihId = daftarResmi[0]?.id || '';
        selectDaftarNominatifSimulasi.innerHTML = `<option value="">Pilih hasil simulasi</option>${daftarResmi.map(item => `
            <option value="${esc(item.id)}" ${item.id === nominatifSimulasiDipilihId ? 'selected' : ''}>${esc(item.nama)}</option>
        `).join('')}`;
        const item = daftarResmi.find(candidate => candidate.id === nominatifSimulasiDipilihId);
        const pks = item ? pksNominatifUntukSimulasi(item) : [];
        if (!pks.some(row => row.kode_file === nominatifKodeFileDipilih)) nominatifKodeFileDipilih = '';
        selectDaftarNominatifKodeFile.innerHTML = `<option value="">Pilih kode file</option>${pks.map(row => {
            const kode = row.kode_file || row.id_program || row.id;
            return `<option value="${esc(kode)}" ${kode === nominatifKodeFileDipilih ? 'selected' : ''}>PKS ${esc(row.noPks)} - ${esc(kode)}</option>`;
        }).join('')}`;
        selectDaftarNominatifKodeFile.disabled = !item || !pks.length;
        btnBukaDaftarNominatif.disabled = !item || !nominatifKodeFileDipilih;
        const tersimpan = item && nominatifKodeFileDipilih ? fileNominatifTersimpan(item.id, nominatifKodeFileDipilih) : null;
        const pengajuanAktif = item && nominatifKodeFileDipilih
            ? pengajuanPengeluaranUntukFile(item.id, nominatifKodeFileDipilih)
            : null;
        btnSimpanDaftarNominatif.disabled = !nominatifRowsAktif.length || !item || !nominatifKodeFileDipilih || pengajuanPengeluaranTerkunci(pengajuanAktif);
        if (item && pks.length) {
            const statusInfo = pengajuanAktif?.status ? ` Status pengeluaran: ${pengajuanAktif.status}.` : '';
            setInfoDaftarNominatif(`${pks.length} kode file tersedia pada ${item.nama}. ${Object.keys(daftarNominatifBySimulasi[item.id] || {}).length} kode file sudah disimpan.${statusInfo}`);
        } else if (!daftarResmi.length) {
            setInfoDaftarNominatif('Belum ada hasil simulasi final. Draf dan sesi yang belum ditetapkan tidak masuk laporan resmi.');
        }
        renderDaftarKodeFileNominatif(item);
    }

    function renderTabelDaftarNominatif() {
        if (!bodyTabelDaftarNominatif) return;
        if (!nominatifRowsAktif.length) {
            bodyTabelDaftarNominatif.innerHTML = '<tr class="table-state-row"><td colspan="27"><div class="table-state table-state--empty"><strong>Belum ada baris nominatif</strong><small>Buka kode file yang dipilih untuk membentuk tabel dari Plot SK Bidang.</small></div></td></tr>';
            if (ringkasanDaftarNominatif) ringkasanDaftarNominatif.hidden = true;
            return;
        }
        const jumlahHonor = nominatifRowsAktif.reduce((sum, row) => sum + (Number(row.total_honor) || 0), 0);
        const jumlahBulanan = nominatifRowsAktif.reduce((sum, row) => sum + (Number(row.total) || 0), 0);
        if (ringkasanDaftarNominatif) {
            ringkasanDaftarNominatif.hidden = false;
            ringkasanDaftarNominatif.innerHTML = `<span><strong>${nominatifRowsAktif.length.toLocaleString('id-ID')}</strong> baris personil</span><span>Total Honor: <strong>${esc(formatRupiahKomaDash(jumlahHonor))}</strong></span><span>Total Bulanan: <strong>${esc(formatRupiahKomaDash(jumlahBulanan))}</strong></span>`;
        }
        const item = daftarHasilSimulasiPlotting.find(candidate => candidate.id === nominatifSimulasiDipilihId);
        const pengajuanAktif = item && nominatifKodeFileDipilih
            ? pengajuanPengeluaranUntukFile(item.id, nominatifKodeFileDipilih)
            : null;
        const readOnly = pengajuanPengeluaranTerkunci(pengajuanAktif);
        const readOnlyAttr = readOnly ? ' readonly' : '';
        bodyTabelDaftarNominatif.innerHTML = nominatifRowsAktif.map((row, index) => {
            const monthCells = bulanDaftarNominatif.map(nama => `<td class="nominatif-money nominatif-readonly">${row.bulan[nama] ? esc(formatRupiahKomaDash(row.bulan[nama])) : '-'}</td>`).join('');
            const selisihClass = Math.abs(Number(row.selisih) || 0) < 0.01 ? 'is-zero' : (Number(row.selisih) < 0 ? 'is-negative' : '');
            return `<tr>
                <td><input type="text" class="form-input nominatif-input" data-nominatif-index="${index}" data-nominatif-field="nip" value="${esc(row.nip)}" placeholder="NIP/No. Pegawai"${readOnlyAttr}></td>
                <td title="${esc(row.nama)}"><strong>${esc(row.nama || '-')}</strong></td>
                <td><input type="text" class="form-input nominatif-input" data-nominatif-index="${index}" data-nominatif-field="no_sk" value="${esc(row.no_sk)}" placeholder="Nomor SK"${readOnlyAttr}></td>
                <td>${esc(row.jabatan || '-')}</td>
                <td><span class="kode-file-tag">${esc(row.kode_file || '-')}</span></td>
                <td title="${esc(row.judul_kegiatan)}">${esc(row.judul_kegiatan || '-')}</td>
                <td>${esc(row.periode || '-')}</td>
                <td>${esc(row.satuan_honor || 'Orang Bulan')}</td>
                <td class="nominatif-money">${esc(formatRupiahKomaDash(row.tarif_maksimal))}</td>
                <td class="nominatif-money">${esc(formatRupiahKomaDash(row.nilai_satuan))}</td>
                <td class="nominatif-number">${esc(Number(row.volume || 0).toLocaleString('id-ID', { maximumFractionDigits: 2 }))}</td>
                <td class="nominatif-money">${esc(formatRupiahKomaDash(row.total_honor))}</td>
                ${monthCells}
                <td class="nominatif-money">${esc(formatRupiahKomaDash(row.total))}</td>
                <td class="nominatif-money nominatif-difference ${selisihClass}">${esc(formatRupiahKomaDash(row.selisih))}</td>
                <td><input type="text" class="form-input nominatif-input" data-nominatif-index="${index}" data-nominatif-field="keterangan" value="${esc(row.keterangan)}" placeholder="Keterangan"${readOnlyAttr}></td>
            </tr>`;
        }).join('');
    }

    function renderDaftarKodeFileNominatif(item = null) {
        if (!bodyTabelDaftarNominatifKodeFile) return;
        const rows = item ? pksNominatifUntukSimulasi(item) : [];
        if (!rows.length) {
            bodyTabelDaftarNominatifKodeFile.innerHTML = '<tr class="table-state-row"><td colspan="10"><div class="table-state table-state--empty"><strong>Belum ada daftar kode file</strong><small>Pilih hasil simulasi yang memiliki PKS.</small></div></td></tr>';
            if (btnDownloadDaftarNominatif) btnDownloadDaftarNominatif.disabled = true;
            if (btnAjukanDaftarNominatif) btnAjukanDaftarNominatif.disabled = true;
            if (checkAllDaftarNominatifKodeFile) checkAllDaftarNominatifKodeFile.checked = false;
            return;
        }
        const savedMap = daftarNominatifBySimulasi[item.id] || {};
        bodyTabelDaftarNominatifKodeFile.innerHTML = rows.map((row, index) => {
            const kode = row.kode_file || row.id_program || row.id;
            const tersimpan = Boolean(savedMap[kode]?.rows?.length);
            const pengajuan = pengajuanPengeluaranUntukFile(item.id, kode);
            const statusPengajuan = pengajuan?.status || (tersimpan ? STATUS_PENGAJUAN_PENGELUARAN.SIAP_DIAJUKAN : '-');
            const ringkasan = pengajuan || (tersimpan ? ringkasanNominalNominatif(savedMap[kode].rows) : null);
            return `<tr>
                <td><input type="checkbox" data-nominatif-code-check="${esc(kode)}" ${tersimpan ? '' : 'disabled'} aria-label="Pilih ${esc(kode)}"></td>
                <td>${index + 1}</td>
                <td><span class="kode-file-tag">${esc(kode)}</span></td>
                <td>${esc(row.nama_mitra || '-')}</td>
                <td>${esc(row.judul_pks || '-')}</td>
                <td>${esc(item.snapshot ? periodeNominatifDariSnapshot(item.snapshot).label : '-')}</td>
                <td>${Number(savedMap[kode]?.rows?.length || 0).toLocaleString('id-ID')}</td>
                <td class="${tersimpan ? 'nominatif-status-saved' : ''}">${tersimpan ? 'Tersimpan' : 'Belum disimpan'}</td>
                <td class="${pengajuan ? 'nominatif-status-saved' : ''}">${esc(statusPengajuan)}</td>
                <td class="nominatif-money">${ringkasan ? esc(formatRupiahKomaDash(ringkasan.total_pengajuan ?? ringkasan.totalPengajuan)) : '-'}</td>
            </tr>`;
        }).join('');
        if (checkAllDaftarNominatifKodeFile) checkAllDaftarNominatifKodeFile.checked = false;
        perbaruiAksiKodeFileNominatif();
    }

    function renderDaftarNominatif() {
        renderPilihanDaftarNominatif();
        renderTabelDaftarNominatif();
    }

    async function bukaTabelDaftarNominatif() {
        const item = daftarHasilSimulasiPlotting.find(candidate => candidate.id === nominatifSimulasiDipilihId);
        if (!item || !nominatifKodeFileDipilih) return;
        const pks = pksNominatifUntukSimulasi(item).find(row => (row.kode_file || row.id_program || row.id) === nominatifKodeFileDipilih);
        if (!pks) {
            setInfoDaftarNominatif('Kode file tidak ditemukan pada hasil simulasi.', true);
            return;
        }
        const tersimpan = fileNominatifTersimpan(item.id, nominatifKodeFileDipilih);
        nominatifRowsAktif = tersimpan?.rows?.length
            ? tersimpan.rows.map(normalisasiBarisDaftarNominatif)
            : buatBarisDaftarNominatifDariSnapshot(item, pks);
        renderTabelDaftarNominatif();
        renderPilihanDaftarNominatif();
        if (!nominatifRowsAktif.length) setInfoDaftarNominatif('Tidak ada personil pada kode file ini di Plot SK Bidang.', true);
        else setInfoDaftarNominatif(`${nominatifRowsAktif.length.toLocaleString('id-ID')} baris siap diperiksa. Simpan setelah data sudah benar.`);
    }

    async function simpanDaftarNominatifAktif() {
        const item = daftarHasilSimulasiPlotting.find(candidate => candidate.id === nominatifSimulasiDipilihId);
        if (!item || !nominatifKodeFileDipilih || !nominatifRowsAktif.length) return;
        if (pengajuanPengeluaranTerkunci(pengajuanPengeluaranUntukFile(item.id, nominatifKodeFileDipilih))) {
            setInfoDaftarNominatif('Daftar Nominatif sudah diajukan ke Pengeluaran dan dikunci.', true);
            return;
        }
        bodyTabelDaftarNominatif?.querySelectorAll('[data-nominatif-index][data-nominatif-field]')?.forEach(input => {
            const index = Number(input.dataset.nominatifIndex);
            const field = input.dataset.nominatifField;
            if (nominatifRowsAktif[index] && ['nip', 'no_sk', 'keterangan'].includes(field)) {
                nominatifRowsAktif[index][field] = String(input.value || '').trim();
            }
        });
        const pks = pksNominatifUntukSimulasi(item).find(row => (row.kode_file || row.id_program || row.id) === nominatifKodeFileDipilih) || {};
        if (!daftarNominatifBySimulasi[item.id]) daftarNominatifBySimulasi[item.id] = {};
        daftarNominatifBySimulasi[item.id][nominatifKodeFileDipilih] = {
            simulation_id: item.id,
            simulation_name: item.nama,
            kode_file: nominatifKodeFileDipilih,
            id_program: pks.id_program || pks.id || '',
            nama_mitra: pks.nama_mitra || '',
            judul_kegiatan: pks.judul_pks || '',
            periode: periodeNominatifDariSnapshot(item.snapshot).label,
            saved_at: new Date().toISOString(),
            rows: nominatifRowsAktif.map(normalisasiBarisDaftarNominatif)
        };
        simpanPlottingKerma();
        btnSimpanDaftarNominatif.disabled = true;
        setInfoDaftarNominatif('Daftar nominatif berhasil disimpan.');
        try {
            await simpanPlottingKermaKeServer(snapshotPlottingKerma());
        } finally {
            renderPilihanDaftarNominatif();
            renderTabelDaftarNominatif();
        }
    }

    function tampilkanAlertAjukanDaftarNominatif(message = '', type = 'error') {
        if (!alertAjukanDaftarNominatif) return;
        alertAjukanDaftarNominatif.textContent = message;
        alertAjukanDaftarNominatif.className = `form-alert form-alert--${type}`;
        alertAjukanDaftarNominatif.style.display = message ? '' : 'none';
    }

    function validasiFileNominatifUntukPengajuan(item = null, kodeFile = '') {
        const saved = item ? fileNominatifTersimpan(item.id, kodeFile) : null;
        if (!saved?.rows?.length) {
            return { ok: false, message: `${kodeFile}: Daftar Nominatif belum disimpan.` };
        }
        const pengajuan = pengajuanPengeluaranUntukFile(item.id, kodeFile);
        if (pengajuanPengeluaranTerkunci(pengajuan)) {
            return { ok: false, message: `${kodeFile}: sudah berstatus ${pengajuan.status} dan tidak dapat diajukan ulang.` };
        }
        const rows = saved.rows.map(normalisasiBarisDaftarNominatif);
        const rowsBerselisih = rows.filter(row => Math.abs(Number(row.selisih) || 0) > 0.01);
        if (rowsBerselisih.length) {
            return { ok: false, message: `${kodeFile}: masih ada ${rowsBerselisih.length} baris dengan selisih perhitungan.` };
        }
        const summary = ringkasanNominalNominatif(rows);
        if (summary.totalPengajuan <= 0) {
            return { ok: false, message: `${kodeFile}: tidak ada nominal honor yang dapat diajukan.` };
        }
        return { ok: true, kodeFile, file: saved, rows, summary };
    }

    function bukaModalAjukanDaftarNominatif() {
        const item = daftarHasilSimulasiPlotting.find(candidate => candidate.id === nominatifSimulasiDipilihId);
        const selected = kodeFileNominatifTerpilih();
        if (!item || !selected.length) {
            setInfoDaftarNominatif('Pilih Kode File yang sudah disimpan dan belum diajukan.', true);
            return;
        }
        const hasilValidasi = selected.map(kode => validasiFileNominatifUntukPengajuan(item, kode));
        const valid = hasilValidasi.filter(result => result.ok);
        const catatan = hasilValidasi.filter(result => !result.ok).map(result => result.message);
        if (!valid.length) {
            setInfoDaftarNominatif(catatan.join(' '), true);
            return;
        }
        nominatifPengajuanMenunggu = valid;
        const totalPengajuan = valid.reduce((sum, result) => sum + result.summary.totalPengajuan, 0);
        const jumlahPenerima = valid.reduce((sum, result) => sum + result.summary.jumlahPenerimaHonor, 0);
        if (pesanAjukanDaftarNominatif) {
            pesanAjukanDaftarNominatif.textContent = `Ajukan ${valid.length} Kode File dari simulasi “${item.nama}” ke Pengeluaran?`;
        }
        if (ringkasanAjukanDaftarNominatif) {
            ringkasanAjukanDaftarNominatif.innerHTML = `
                <article><span>Kode File</span><strong>${valid.length.toLocaleString('id-ID')}</strong></article>
                <article><span>Penerima Honor</span><strong>${jumlahPenerima.toLocaleString('id-ID')}</strong></article>
                <article><span>Total Pengajuan</span><strong>${esc(formatRupiahKomaDash(totalPengajuan))}</strong></article>
                <article><span>Periode</span><strong>${esc(item.snapshot ? periodeNominatifDariSnapshot(item.snapshot).label : '-')}</strong></article>
            `;
        }
        tampilkanAlertAjukanDaftarNominatif(
            catatan.length ? `Sebagian Kode File tidak ikut diajukan: ${catatan.join(' ')}` : '',
            catatan.length ? 'warning' : 'error'
        );
        if (btnKonfirmasiAjukanDaftarNominatif) btnKonfirmasiAjukanDaftarNominatif.disabled = false;
        if (modalAjukanDaftarNominatif) modalAjukanDaftarNominatif.style.display = 'flex';
        setTimeout(() => btnBatalAjukanDaftarNominatif?.focus(), 0);
    }

    function tutupModalAjukanDaftarNominatif() {
        if (modalAjukanDaftarNominatif) modalAjukanDaftarNominatif.style.display = 'none';
        nominatifPengajuanMenunggu = [];
        tampilkanAlertAjukanDaftarNominatif('');
    }

    async function konfirmasiAjukanDaftarNominatif() {
        const item = daftarHasilSimulasiPlotting.find(candidate => candidate.id === nominatifSimulasiDipilihId);
        if (!item || !nominatifPengajuanMenunggu.length) {
            tutupModalAjukanDaftarNominatif();
            return;
        }
        const now = new Date().toISOString();
        if (!pengajuanPengeluaranBySimulasi[item.id]) pengajuanPengeluaranBySimulasi[item.id] = {};
        nominatifPengajuanMenunggu.forEach(result => {
            const summary = result.summary;
            pengajuanPengeluaranBySimulasi[item.id][result.kodeFile] = {
                simulation_id: item.id,
                simulation_name: item.nama,
                kode_file: result.kodeFile,
                id_program: result.file.id_program || '',
                nama_mitra: result.file.nama_mitra || '',
                judul_kegiatan: result.file.judul_kegiatan || '',
                periode: result.file.periode || (item.snapshot ? periodeNominatifDariSnapshot(item.snapshot).label : ''),
                status: STATUS_PENGAJUAN_PENGELUARAN.DIAJUKAN,
                rka_id: '',
                rka_status: 'Belum dibuat',
                rka_category: 'Belanja Pegawai',
                rka_created_at: '',
                total_pengajuan: summary.totalPengajuan,
                total_bulanan: summary.totalBulanan,
                jumlah_baris: result.rows.length,
                jumlah_penerima_honor: summary.jumlahPenerimaHonor,
                submitted_at: now,
                updated_at: now,
                catatan: '',
                rows: cloneDataPlotting(result.rows, [])
            };
        });
        const jumlahDiajukan = nominatifPengajuanMenunggu.length;
        simpanPlottingKerma();
        if (btnKonfirmasiAjukanDaftarNominatif) {
            btnKonfirmasiAjukanDaftarNominatif.disabled = true;
            btnKonfirmasiAjukanDaftarNominatif.textContent = 'Menyimpan...';
        }
        let pesanSimpan = `${jumlahDiajukan} Kode File berhasil diajukan ke Pengeluaran.`;
        try {
            await simpanPlottingKermaKeServer(snapshotPlottingKerma());
        } catch {
            pesanSimpan += ' Data tersimpan di perangkat, tetapi sinkronisasi server perlu dicoba kembali.';
        } finally {
            if (btnKonfirmasiAjukanDaftarNominatif) {
                btnKonfirmasiAjukanDaftarNominatif.disabled = false;
                btnKonfirmasiAjukanDaftarNominatif.textContent = 'Ajukan';
            }
        }
        tutupModalAjukanDaftarNominatif();
        renderPilihanDaftarNominatif();
        renderTabelDaftarNominatif();
        renderTabelPengajuanPengeluaran();
        switchPage(menuPengeluaran, sectionRealisasi);
        setTabRealisasi('pengajuan');
        renderTabelPengajuanPengeluaran();
        setInfoDaftarNominatif(pesanSimpan);
    }

    function daftarPengajuanPengeluaranDatar() {
        return Object.values(pengajuanPengeluaranBySimulasi || {})
            .flatMap(files => Object.values(files || {}))
            .filter(file => file && file.kode_file)
            .sort((a, b) => new Date(b.updated_at || b.submitted_at).getTime() - new Date(a.updated_at || a.submitted_at).getTime());
    }

    function idPengajuanPengeluaran(file = {}) {
        return `${String(file.simulation_id || '').trim()}::${String(file.kode_file || '').trim()}`;
    }

    function rkaDariPengajuanPengeluaran(file = {}) {
        const idPengajuan = idPengajuanPengeluaran(file);
        return allRabAnggaranData.find(row => (
            String(row.sumber || '').trim() === 'daftar_nominatif'
            && String(row.id_pengajuan || '').trim() === idPengajuan
        )) || allRabAnggaranData.find(row => (
            file.rka_id && String(row.id_rab || '').trim() === String(file.rka_id).trim()
        )) || null;
    }

    function evaluasiRkaDariPengajuan(file = {}, kategori = 'Belanja Pegawai') {
        const kodeFile = String(file.kode_file || '').trim();
        const kategoriBelanja = String(kategori || '').trim();
        const fieldPagu = fieldPaguRabByKategori[kategoriBelanja];
        const rkaTersimpan = rkaDariPengajuanPengeluaran(file);
        if (rkaTersimpan || file.rka_id) {
            return { ok: false, alasan: 'sudah_dibuat', rka: rkaTersimpan };
        }
        if (!kodeFile || !fieldPagu) {
            return { ok: false, alasan: 'kategori_tidak_valid', pesan: 'Kode File dan kategori belanja wajib dipilih.' };
        }

        const rowPagu = rowPaguDariKodeFile(kodeFile);
        const paguTersedia = Math.max(
            angkaPaguAnggaran(rowPagu?.[fieldPagu]),
            nilaiRkaTerkunciKategori(rowPagu, kodeFile, fieldPagu)
        );
        const rkaTerkunci = nilaiRkaTerkunciKategori(rowPagu, kodeFile, fieldPagu);
        const sisaPagu = paguTersedia - rkaTerkunci;
        const kebutuhan = angkaPaguAnggaran(file.total_pengajuan);
        if (!rowPagu) {
            return {
                ok: false,
                alasan: 'pagu_tidak_ditemukan',
                kategori: kategoriBelanja,
                kebutuhan,
                paguTersedia,
                rkaTerkunci,
                sisaPagu
            };
        }
        return {
            ok: kebutuhan <= sisaPagu + 1,
            alasan: kebutuhan <= sisaPagu + 1 ? '' : 'pagu_tidak_cukup',
            kategori: kategoriBelanja,
            kebutuhan,
            paguTersedia,
            rkaTerkunci,
            sisaPagu,
            kekurangan: Math.max(0, kebutuhan - sisaPagu),
            fieldPagu
        };
    }

    function uraianRkaDariPengajuan(file = {}) {
        return String(file.rka_uraian || `Honor Daftar Nominatif - ${file.simulation_name || file.kode_file || ''}`)
            .replace(/\s+/g, ' ')
            .trim();
    }

    function tampilkanAlertBuatRka(message = '', type = 'error') {
        if (!alertBuatRkaDariPengajuan) return;
        alertBuatRkaDariPengajuan.textContent = message;
        alertBuatRkaDariPengajuan.className = `form-alert form-alert--${type}`;
        alertBuatRkaDariPengajuan.style.display = message ? '' : 'none';
    }

    function renderRingkasanBuatRkaDariPengajuan() {
        const file = pengajuanRkaAktif;
        if (!file || !ringkasanBuatRkaDariPengajuan) return null;
        const kategori = String(selectKategoriRkaDariPengajuan?.value || file.rka_category || 'Belanja Pegawai').trim();
        const evaluasi = evaluasiRkaDariPengajuan(file, kategori);
        const uraian = normalisasiUraianRab(inputUraianRkaDariPengajuan?.value || '');
        evaluasi.uraian = uraian;
        if (!uraian) {
            evaluasi.ok = false;
            evaluasi.alasan = 'uraian_kosong';
        }
        ringkasanBuatRkaDariPengajuan.innerHTML = `
            <article><span>Kode File</span><strong>${esc(file.kode_file || '-')}</strong></article>
            <article><span>Total Pengajuan</span><strong>${esc(formatRupiahKomaDash(evaluasi.kebutuhan || file.total_pengajuan || 0))}</strong></article>
            <article><span>PAGU ${esc(kategori.replace(/^Belanja\s+/i, ''))}</span><strong>${esc(formatRupiahKomaDash(evaluasi.paguTersedia || 0))}</strong></article>
            <article><span>Sisa Setelah RKA</span><strong>${esc(formatRupiahKomaDash(Math.max(0, evaluasi.sisaPagu || 0)))}</strong></article>
        `;
        if (infoBuatRkaDariPengajuan) {
            const info = evaluasi.alasan === 'sudah_dibuat'
                ? 'Pengajuan ini sudah memiliki RKA Kerma.'
                : `PAGU ${kategori}: ${formatRupiahKomaDash(evaluasi.paguTersedia || 0)} · RKA terkunci: ${formatRupiahKomaDash(evaluasi.rkaTerkunci || 0)} · sisa tersedia: ${formatRupiahKomaDash(Math.max(0, evaluasi.sisaPagu || 0))}.`;
            infoBuatRkaDariPengajuan.textContent = info;
            infoBuatRkaDariPengajuan.className = 'form-alert form-alert--warning';
            infoBuatRkaDariPengajuan.style.display = '';
        }
        let pesan = '';
        if (evaluasi.alasan === 'sudah_dibuat') {
            pesan = 'RKA Kerma untuk pengajuan ini sudah dibuat dan tidak dapat dibuat ulang.';
        } else if (evaluasi.alasan === 'pagu_tidak_ditemukan') {
            pesan = `PAGU untuk Kode File ${file.kode_file} belum tersedia.`;
        } else if (evaluasi.alasan === 'pagu_tidak_cukup') {
            pesan = `Sisa PAGU kategori ${kategori} tidak mencukupi. Kekurangan: ${formatRupiahKomaDash(evaluasi.kekurangan)}.`;
        } else if (evaluasi.alasan === 'kategori_tidak_valid') {
            pesan = evaluasi.pesan || 'Kategori belanja tidak valid.';
        } else if (evaluasi.alasan === 'uraian_kosong') {
            pesan = 'Uraian wajib diisi.';
        }
        tampilkanAlertBuatRka(pesan);
        if (btnKonfirmasiBuatRkaDariPengajuan) btnKonfirmasiBuatRkaDariPengajuan.disabled = !evaluasi.ok;
        return evaluasi;
    }

    async function bukaModalBuatRkaDariPengajuan(file = null) {
        if (!file) return;
        if (rkaDariPengajuanPengeluaran(file) || file.rka_id) {
            alert('RKA Kerma untuk pengajuan ini sudah dibuat.');
            return;
        }
        pengajuanRkaAktif = file;
        if (inputUraianRkaDariPengajuan) inputUraianRkaDariPengajuan.value = uraianRkaDariPengajuan(file);
        if (selectKategoriRkaDariPengajuan) selectKategoriRkaDariPengajuan.value = file.rka_category || 'Belanja Pegawai';
        if (modalBuatRkaDariPengajuan) modalBuatRkaDariPengajuan.style.display = 'flex';
        if (btnKonfirmasiBuatRkaDariPengajuan) {
            btnKonfirmasiBuatRkaDariPengajuan.disabled = true;
            btnKonfirmasiBuatRkaDariPengajuan.textContent = 'Memeriksa PAGU...';
        }
        tampilkanAlertBuatRka('');
        try {
            await muatPaguAnggaran();
            await muatRabAnggaran();
            renderRingkasanBuatRkaDariPengajuan();
        } catch (err) {
            tampilkanAlertBuatRka(err.message || 'Gagal memeriksa PAGU dan RKA Kerma.');
        } finally {
            if (btnKonfirmasiBuatRkaDariPengajuan) btnKonfirmasiBuatRkaDariPengajuan.textContent = 'Buat RKA Kerma';
        }
    }

    function tutupModalBuatRkaDariPengajuan() {
        if (modalBuatRkaDariPengajuan) modalBuatRkaDariPengajuan.style.display = 'none';
        pengajuanRkaAktif = null;
        tampilkanAlertBuatRka('');
    }

    async function konfirmasiBuatRkaDariPengajuan() {
        const file = pengajuanRkaAktif;
        if (!file) return;
        const kategori = String(selectKategoriRkaDariPengajuan?.value || 'Belanja Pegawai').trim();
        const evaluasi = renderRingkasanBuatRkaDariPengajuan();
        if (!evaluasi?.ok) return;
        const uraian = normalisasiUraianRab(inputUraianRkaDariPengajuan?.value || '');
        if (!uraian) return;
        const idPengajuan = idPengajuanPengeluaran(file);
        const now = new Date().toISOString();
        if (btnKonfirmasiBuatRkaDariPengajuan) {
            btnKonfirmasiBuatRkaDariPengajuan.disabled = true;
            btnKonfirmasiBuatRkaDariPengajuan.textContent = 'Menyimpan...';
        }
        try {
            const response = await fetch('/api/rab-anggaran', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'same-origin',
                body: JSON.stringify({
                    kode_file: file.kode_file,
                    kategori_belanja: kategori,
                    uraian,
                    satuan: 'Orang Bulan',
                    harga_satuan: Number(file.total_pengajuan) || 0,
                    volume: 1,
                    keterangan: `Dari Daftar Nominatif · ${file.simulation_name || '-'} · ${file.periode || '-'}`,
                    sumber: 'daftar_nominatif',
                    id_pengajuan: idPengajuan,
                    simulation_id: file.simulation_id || '',
                    simulation_name: file.simulation_name || ''
                })
            });
            let result = {};
            try {
                result = await response.json();
            } catch {
                result = {};
            }
            if (!response.ok) {
                throw new Error(result.pesan || `Gagal membuat RKA Kerma (HTTP ${response.status}).`);
            }
            const current = pengajuanPengeluaranUntukFile(file.simulation_id, file.kode_file) || file;
            current.status = STATUS_PENGAJUAN_PENGELUARAN.DIPROSES;
            current.rka_id = String(result.data?.id_rab || '').trim();
            current.rka_status = 'Tersimpan';
            current.rka_uraian = uraian;
            current.rka_category = kategori;
            current.rka_created_at = now;
            current.updated_at = now;
            simpanPlottingKerma();
            const tersinkron = await simpanPlottingKermaKeServer(snapshotPlottingKerma());
            tutupModalBuatRkaDariPengajuan();
            renderTabelPengajuanPengeluaran();
            setTabRealisasi('rab');
            setKodeFileRab(file.kode_file);
            await muatPaguAnggaran();
            await muatRabAnggaran();
            alert(`RKA Kerma berhasil dibuat untuk ${file.kode_file}.${tersinkron ? '' : ' Data sesi tersimpan di perangkat; sinkronisasi server perlu dicoba kembali.'}`);
        } catch (err) {
            tampilkanAlertBuatRka(err.message || 'Gagal membuat RKA Kerma.');
            if (btnKonfirmasiBuatRkaDariPengajuan) btnKonfirmasiBuatRkaDariPengajuan.disabled = false;
        } finally {
            if (btnKonfirmasiBuatRkaDariPengajuan && modalBuatRkaDariPengajuan?.style.display === 'flex') {
                btnKonfirmasiBuatRkaDariPengajuan.textContent = 'Buat RKA Kerma';
            }
        }
    }

    function renderTabelPengajuanPengeluaran() {
        if (!bodyTabelPengajuanPengeluaran) return;
        const sumber = daftarPengajuanPengeluaranDatar();
        const cari = String(filterPengajuanPengeluaranCari?.value || '').trim().toLowerCase();
        const rows = cari
            ? sumber.filter(file => [file.simulation_name, file.kode_file, file.nama_mitra, file.judul_kegiatan, file.periode, file.status]
                .some(value => String(value || '').toLowerCase().includes(cari)))
            : sumber;
        if (ringkasanPengajuanPengeluaran) {
            ringkasanPengajuanPengeluaran.hidden = !sumber.length;
            if (sumber.length) {
                const total = sumber.reduce((sum, file) => sum + (Number(file.total_pengajuan) || 0), 0);
                ringkasanPengajuanPengeluaran.innerHTML = `<span><strong>${sumber.length.toLocaleString('id-ID')}</strong> pengajuan</span><span>Total Pengajuan: <strong>${esc(formatRupiahKomaDash(total))}</strong></span>`;
            }
        }
        if (!rows.length) {
            bodyTabelPengajuanPengeluaran.innerHTML = tableState(11, 'empty', sumber.length ? 'Tidak ada pengajuan yang cocok' : 'Belum ada pengajuan pengeluaran', sumber.length ? 'Ubah kata pencarian untuk menampilkan data kembali.' : 'Ajukan Daftar Nominatif dari tab Daftar Kode File.');
            if (infoHasilPengajuanPengeluaran) infoHasilPengajuanPengeluaran.textContent = sumber.length ? `Menampilkan 0 dari ${sumber.length} pengajuan` : '';
            return;
        }
        bodyTabelPengajuanPengeluaran.innerHTML = rows.map((file, index) => `
            ${(() => {
                const rka = rkaDariPengajuanPengeluaran(file);
                const rkaTersimpan = Boolean(rka || file.rka_id || file.rka_status === 'Tersimpan');
                const kategori = rka?.kategori_belanja || file.rka_category || 'Belanja Pegawai';
                return `<tr>
                <td>${index + 1}</td>
                <td><strong>${esc(file.simulation_name || '-')}</strong></td>
                <td><span class="kode-file-tag">${esc(file.kode_file)}</span></td>
                <td class="td-truncate">${esc(file.nama_mitra || '-')}</td>
                <td>${esc(file.periode || '-')}</td>
                <td class="td-number">${Number(file.jumlah_penerima_honor || 0).toLocaleString('id-ID')}</td>
                <td class="nominatif-money">${esc(formatRupiahKomaDash(file.total_pengajuan))}</td>
                <td>${esc(formatTanggalWaktuSimulasi(file.submitted_at || file.updated_at))}</td>
                <td class="nominatif-status-saved">${esc(file.status || STATUS_PENGAJUAN_PENGELUARAN.DIAJUKAN)}</td>
                <td>${esc(rkaTersimpan ? kategori : 'Belum ditetapkan')}</td>
                <td>
                    ${rkaTersimpan
                        ? '<span class="nominatif-status-saved">RKA Tersimpan</span>'
                        : `<button type="button" class="btn-mini-action" data-pengajuan-buat-rka-simulasi="${esc(file.simulation_id)}" data-pengajuan-buat-rka-kode="${esc(file.kode_file)}">Buat RKA Kerma</button>`}
                </td>
            </tr>`;
            })()}
        `).join('');
        if (infoHasilPengajuanPengeluaran) infoHasilPengajuanPengeluaran.textContent = cari ? `Menampilkan ${rows.length} dari ${sumber.length} pengajuan` : '';
    }

    function setTabDaftarNominatif(tab = 'tabel') {
        const isTabel = tab === 'tabel';
        tabDaftarNominatifTabel?.classList.toggle('active', isTabel);
        tabDaftarNominatifKodeFile?.classList.toggle('active', !isTabel);
        tabDaftarNominatifTabel?.setAttribute('aria-selected', String(isTabel));
        tabDaftarNominatifKodeFile?.setAttribute('aria-selected', String(!isTabel));
        if (panelDaftarNominatifTabel) panelDaftarNominatifTabel.hidden = !isTabel;
        if (panelDaftarNominatifKodeFile) panelDaftarNominatifKodeFile.hidden = isTabel;
    }

    async function downloadDaftarNominatifTerpilih() {
        const item = daftarHasilSimulasiPlotting.find(candidate => candidate.id === nominatifSimulasiDipilihId);
        if (!item) return;
        const selected = [...(bodyTabelDaftarNominatifKodeFile?.querySelectorAll('[data-nominatif-code-check]:checked') || [])]
            .map(input => input.dataset.nominatifCodeCheck)
            .filter(Boolean);
        if (!selected.length) {
            setInfoDaftarNominatif('Pilih kode file yang sudah tersimpan pada tab Daftar Kode File.', true);
            return;
        }
        const files = selected.map(kode => daftarNominatifBySimulasi[item.id]?.[kode]).filter(Boolean);
        const response = await fetch('/api/daftar-nominatif/export', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            credentials: 'same-origin',
            body: JSON.stringify({ simulation_name: item.nama, files })
        });
        if (!response.ok) {
            let message = 'Gagal mengunduh daftar nominatif.';
            try { message = (await response.json())?.pesan || message; } catch { /* response bukan JSON */ }
            setInfoDaftarNominatif(message, true);
            return;
        }
        const blob = await response.blob();
        unduhBlobSkTim(blob, namaFileDariContentDisposition(response.headers.get('Content-Disposition'), 'Daftar Nominatif.xlsx'));
    }

    function renderTabelNomorSkTim(item = hasilSimulasiSkDipilih) {
        if (!bodyTabelNomorSkTim) return;
        const rows = daftarPksDariHasilSimulasiSkTim(item || {});
        if (!rows.length) {
            bodyTabelNomorSkTim.innerHTML = tableState(6, 'empty', 'Tidak ada PKS pada simulasi ini', 'Buka ulang hasil simulasi atau pilih simulasi lain.');
            return;
        }
        bodyTabelNomorSkTim.innerHTML = rows.map(row => `
            <tr>
                <td>${esc(row.noPks)}</td>
                <td><strong>PKS ${esc(row.noPks)}</strong></td>
                <td><span class="kode-file-tag">${esc(row.kode_file || row.id_program || '-')}</span></td>
                <td class="td-truncate">${esc(row.nama_mitra || '-')}</td>
                <td class="td-truncate">${esc(row.judul_pks || '-')}</td>
                <td>
                    <input type="text" class="form-input sk-team-no-input" data-sk-nomor-pks="${esc(row.noPks)}" data-sk-nomor-key="${esc(row.id || row.kode_file || row.noPks)}" value="${esc(nomorSkTersimpanUntukPks(item, row))}" placeholder="Nomor SK">
                </td>
            </tr>
        `).join('');
    }

    async function bukaModalGenerateSkTim(id) {
        const item = daftarHasilSimulasiPlotting.find(simulasi => simulasi.id === id);
        if (!item) return;
        if (![STATUS_SESI_SIMULASI.SIAP_GENERATE_SK, STATUS_SESI_SIMULASI.SELESAI].includes(item.status)) {
            window.alert(`Sesi “${item.nama}” belum dapat dibuatkan SK. Tetapkan sebagai Hasil Final setelah Target Distribusi, Plot SK, dan Kontrol terpenuhi.`);
            return;
        }
        hasilSimulasiSkDipilih = item;
        tampilkanAlertGenerateSkTim('');
        if (!allData.length) await muatDataEksporPlottingKerma();
        const rows = daftarPksDariHasilSimulasiSkTim(item);
        setText(labelSimulasiSkTim, item.nama || 'Simulasi');
        setText(ringkasanSkTim, `${rows.length.toLocaleString('id-ID')} PKS akan dibuatkan SK`);
        if (inputTanggalSkTim) inputTanggalSkTim.value = todayInputDate();
        if (inputTahunAkademikSkTim) inputTahunAkademikSkTim.value = tahunAkademikDariSnapshotSkTim(item.snapshot);
        if (inputTanggalBerlakuSkTim) inputTanggalBerlakuSkTim.value = tanggalBerlakuSampaiDariSnapshotSkTim(item.snapshot);
        if (selectFormatSkTim) selectFormatSkTim.value = 'docx';
        renderTabelNomorSkTim(item);
        if (modalGenerateSkTim) modalGenerateSkTim.style.display = 'flex';
    }

    function tutupModalGenerateSkTim() {
        if (modalGenerateSkTim) modalGenerateSkTim.style.display = 'none';
        hasilSimulasiSkDipilih = null;
        tampilkanAlertGenerateSkTim('');
    }

    function namaFileDariContentDisposition(header = '', fallback = 'SK Tim Pengelola Kerma.zip') {
        const utfMatch = String(header || '').match(/filename\*=UTF-8''([^;]+)/i);
        if (utfMatch) {
            try { return decodeURIComponent(utfMatch[1]); } catch { return utfMatch[1]; }
        }
        const match = String(header || '').match(/filename="?([^";]+)"?/i);
        return match?.[1] || fallback;
    }

    function unduhBlobSkTim(blob, filename) {
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = filename || 'SK Tim Pengelola Kerma.zip';
        document.body.appendChild(link);
        link.click();
        link.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
    }

    async function generateSkTimPengelola() {
        if (!hasilSimulasiSkDipilih) return;
        const tanggalSk = String(inputTanggalSkTim?.value || '').trim();
        const tahunAkademik = String(inputTahunAkademikSkTim?.value || '').trim();
        if (!tanggalSk) {
            tampilkanAlertGenerateSkTim('Tanggal SK wajib diisi.');
            inputTanggalSkTim?.focus();
            return;
        }
        if (!tahunAkademik) {
            tampilkanAlertGenerateSkTim('Tahun Akademik wajib diisi.');
            inputTahunAkademikSkTim?.focus();
            return;
        }
        const nomorInputs = [...(bodyTabelNomorSkTim?.querySelectorAll('[data-sk-nomor-pks]') || [])];
        const nomor_sk_by_pks = {};
        const nomorSkTersimpan = {};
        const kosong = [];
        nomorInputs.forEach(input => {
            const noPks = input.dataset.skNomorPks;
            const nomorKey = input.dataset.skNomorKey || noPks;
            const value = String(input.value || '').trim();
            nomor_sk_by_pks[noPks] = value;
            nomorSkTersimpan[nomorKey] = value;
            if (!value) kosong.push(input);
        });
        if (kosong.length) {
            tampilkanAlertGenerateSkTim(`Nomor SK masih kosong untuk ${kosong.length.toLocaleString('id-ID')} PKS.`);
            kosong[0]?.focus();
            return;
        }
        const nomorSkItem = daftarHasilSimulasiPlotting.find(item => item.id === hasilSimulasiSkDipilih.id);
        if (nomorSkItem) {
            nomorSkByPksTersimpan = {
                ...nomorSkByPksTersimpan,
                ...normalisasiNomorSkByPks(nomorSkTersimpan)
            };
            nomorSkItem.nomor_sk_by_pks = {
                ...normalisasiNomorSkByPks(nomorSkItem.nomor_sk_by_pks),
                ...normalisasiNomorSkByPks(nomorSkTersimpan)
            };
            nomorSkItem.snapshot = {
                ...nomorSkItem.snapshot,
                nomorSkByPksTersimpan: normalisasiNomorSkByPks(nomorSkItem.nomor_sk_by_pks)
            };
            hasilSimulasiSkDipilih = nomorSkItem;
            simpanPlottingKerma();
        }
        const labelAwal = btnGenerateSkTim?.textContent || 'Generate SK';
        try {
            if (btnGenerateSkTim) {
                btnGenerateSkTim.disabled = true;
                btnGenerateSkTim.textContent = 'Membuat SK...';
            }
            tampilkanAlertGenerateSkTim('Membuat dokumen SK. Mohon tunggu sebentar.', 'success');
            const res = await fetch('/api/plotting-kerma/sk-tim-pengelola', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    nama_simulasi: hasilSimulasiSkDipilih.nama || '',
                    status_sesi: hasilSimulasiSkDipilih.status || '',
                    snapshot: hasilSimulasiSkDipilih.snapshot || {},
                    nomor_sk_by_pks,
                    tanggal_sk: tanggalSk,
                    tahun_akademik: tahunAkademik,
                    tanggal_berlaku_sampai: inputTanggalBerlakuSkTim?.value || '',
                    format: selectFormatSkTim?.value || 'docx'
                })
            });
            if (!res.ok) {
                const contentType = res.headers.get('content-type') || '';
                const payload = contentType.includes('application/json') ? await res.json() : { pesan: await res.text() };
                throw new Error(payload.pesan || 'Gagal membuat SK Tim Pengelola Kerma.');
            }
            const blob = await res.blob();
            const filename = namaFileDariContentDisposition(res.headers.get('content-disposition'), 'SK Tim Pengelola Kerma.zip');
            unduhBlobSkTim(blob, filename);
            if (nomorSkItem) {
                const now = new Date().toISOString();
                nomorSkItem.status = STATUS_SESI_SIMULASI.SELESAI;
                nomorSkItem.tahap = TAHAP_SESI_SIMULASI.GENERATE;
                nomorSkItem.updated_at = now;
                nomorSkItem.saved_at = now;
                nomorSkItem.updated_by = namaPenggunaSesiSimulasi();
                nomorSkItem.finalized_at = nomorSkItem.finalized_at || now;
                if (nomorSkItem.id === sesiSimulasiAktifId) modeSesiSimulasi = 'view';
                simpanPlottingKerma({ syncSession: false });
                renderDaftarHasilSimulasiPlotting();
                renderSesiSimulasiBar();
            }
            tampilkanAlertGenerateSkTim('SK berhasil dibuat dan mulai diunduh.', 'success');
        } catch (err) {
            tampilkanAlertGenerateSkTim(err.message || 'Gagal membuat SK Tim Pengelola Kerma.');
        } finally {
            if (btnGenerateSkTim) {
                btnGenerateSkTim.disabled = false;
                btnGenerateSkTim.textContent = labelAwal;
            }
        }
    }

    function handleDaftarHasilSimulasiAction(target) {
        const button = target?.closest?.('[data-hasil-simulasi-action]');
        if (!button) return;
        const id = button.dataset.hasilSimulasiId || '';
        if (button.dataset.hasilSimulasiAction === 'open') bukaHasilSimulasiTersimpan(id);
        if (button.dataset.hasilSimulasiAction === 'view') bukaHasilSimulasiTersimpan(id, { viewOnly: true });
        if (button.dataset.hasilSimulasiAction === 'continue') lanjutkanHasilSimulasiTersimpan(id);
        if (button.dataset.hasilSimulasiAction === 'sk') void bukaModalGenerateSkTim(id);
        if (button.dataset.hasilSimulasiAction === 'delete') bukaModalHapusSimulasi([id]);
    }

    function renderEksporRekapitulasiPlotting() {
        if (!bodyTabelEksporPlottingRekapitulasi) return;
        const sumber = dataEksporRekapitulasiUntukFilter();
        const rows = colFilterEksporRekapitulasi ? colFilterEksporRekapitulasi.applyTo(sumber) : sumber;
        renderRingkasanRekapitulasiPlotting(rows);
        const adaFilterKolom = colFilterEksporRekapitulasi && Object.keys(colFilterEksporRekapitulasi.colFilters).length > 0;
        if (!rows.length) {
            bodyTabelEksporPlottingRekapitulasi.innerHTML = adaFilterKolom
                ? tableState(12, 'empty', 'Tidak ada Rekapitulasi yang cocok', 'Ubah filter pada heading tabel untuk menampilkan data kembali.')
                : tableState(12, 'empty', 'Belum ada Rekapitulasi', 'Rekapitulasi hanya menampilkan pegawai aktif dengan target lebih dari Rp 0,-.');
            return;
        }
        bodyTabelEksporPlottingRekapitulasi.innerHTML = rows.map((row, index) => {
            const selisihDistribusiClass = Number(row.selisih_distribusi) < 0 ? ' realisasi-sisa-warning' : '';
            const selisihDistribusiPlotSkClass = Number(row.selisih_distribusi_plot_sk) < 0 ? ' realisasi-sisa-warning' : '';
            const roleDiffCell = (value, display) => `<td class="td-number rekap-role-diff${Number(value) < 0 ? ' realisasi-sisa-warning' : ''}">${esc(display || formatRupiahKomaDash(value))}</td>`;
            return `
                <tr>
                    <td>${esc(row.no || index + 1)}</td>
                    <td><strong>${esc(row.nama || '-')}</strong></td>
                    ${roleDiffCell(row.selisih_target_pj, row.selisih_target_pj_display)}
                    ${roleDiffCell(row.selisih_target_pg, row.selisih_target_pg_display)}
                    ${roleDiffCell(row.selisih_target_k, row.selisih_target_k_display)}
                    ${roleDiffCell(row.selisih_target_ka, row.selisih_target_ka_display)}
                    ${roleDiffCell(row.selisih_target_a, row.selisih_target_a_display)}
                    <td class="td-number">${esc(row.target_distribusi_display || formatRupiahKomaDash(row.target_distribusi))}</td>
                    <td class="td-number">${esc(row.realisasi_distribusi_display || formatRupiahKomaDash(row.realisasi_distribusi))}</td>
                    <td class="td-number">${esc(row.realisasi_plot_sk_display || formatRupiahKomaDash(row.realisasi_plot_sk))}</td>
                    <td class="td-number${selisihDistribusiClass}">${esc(row.selisih_distribusi_display || formatRupiahKomaDash(row.selisih_distribusi))}</td>
                    <td class="td-number${selisihDistribusiPlotSkClass}">${esc(row.selisih_distribusi_plot_sk_display || formatRupiahKomaDash(row.selisih_distribusi_plot_sk))}</td>
                </tr>
            `;
        }).join('');
    }

    function renderEksporPerhitunganDasarPlotting() {
        if (!bodyTabelEksporPlottingPerhitunganDasar) return;
        pastikanRowsPerhitunganDasarPlotting();
        sinkronDurasiDariPeriodePengelola();
        updateTampilanPeriodePengelola();

        const totalPerKerma = hitungTotalPerKermaPlotting();
        setText(eksporPlottingPeriode, formatLabelPeriodePengelolaKerma());
        setText(eksporPlottingTotalPerKerma, formatRupiahKomaDash(totalPerKerma));
        updateTampilanTombolMasterTarif();
        renderTahapMulaiPlottingKerma();

        const sumber = dataEksporPerhitunganDasarUntukFilter();
        const rows = colFilterEksporPerhitunganDasar ? colFilterEksporPerhitunganDasar.applyTo(sumber) : sumber;
        const adaFilterKolom = colFilterEksporPerhitunganDasar && Object.keys(colFilterEksporPerhitunganDasar.colFilters).length > 0;

        if (!rows.length) {
            bodyTabelEksporPlottingPerhitunganDasar.innerHTML = adaFilterKolom
                ? tableState(6, 'empty', 'Tidak ada Perhitungan Dasar yang cocok', 'Ubah filter pada heading tabel untuk menampilkan data kembali.')
                : tableState(6, 'empty', 'Belum ada Perhitungan Dasar', 'Atur periode dan personil per Kerma untuk menampilkan data.');
            return;
        }

        bodyTabelEksporPlottingPerhitunganDasar.innerHTML = rows.map(row => {
            const personilTerkunci = isPersonilPerKermaTerkunci(row.jabatan);
            const rowIndex = Number(row.row_index);
            return `
            <tr>
                <td>
                    <strong>${esc(row.jabatan_label || `${labelJabatanPlotting(row.jabatan)}: ${namaJabatanPlotting(row.jabatan)}`)}</strong>
                    ${row.jabatan_bidang ? `<small class="plotting-role-field-list">${esc(row.jabatan_bidang)}</small>` : ''}
                </td>
                <td>
                    <input type="text" inputmode="numeric" class="form-input plotting-input plotting-input--number plotting-input--money" data-harga-row="${rowIndex}" data-ekspor-harga-row="${rowIndex}" data-harga-field="tarif" value="${esc(row.tarif_display || formatRupiahKomaDash(row.tarif))}" placeholder="Rp 0,-" ${row.jabatan === 'Anggota' || !modeEditMasterTarif ? 'readonly' : ''} ${row.jabatan === 'Anggota' ? 'aria-readonly="true" title="Tarif Anggota selalu Rp0,- dan tidak masuk target distribusi."' : ''}>
                </td>
                <td class="td-number">${esc(row.durasi ?? '-')}</td>
                <td>
                    <input type="number" min="0" step="1" class="form-input plotting-input plotting-input--number" data-harga-row="${rowIndex}" data-ekspor-harga-row="${rowIndex}" data-harga-field="personil_per_kerma" value="${esc(row.personil_per_kerma ?? '')}" placeholder="0" ${personilTerkunci ? 'readonly aria-readonly="true" title="Nilai ini dikunci oleh aturan perhitungan dasar."' : ''}>
                </td>
                <td class="td-number">${esc(row.total_rupiah_display || formatRupiahKomaDash(hitungTotalRupiahJabatan(row)))}</td>
                <td class="td-number">${esc(row.posisi_tersedia_display || hitungJumlahOrangJabatan(row).toLocaleString('id-ID', { maximumFractionDigits: 2 }))}</td>
            </tr>
        `;
        }).join('');
    }

    function renderEksporSisaPaguPlotting({ loading = false, error = '' } = {}) {
        if (!bodyTabelEksporPlottingSisaPagu) return;
        const setRingkasanSisaPagu = rows => {
            const rowsValid = Array.isArray(rows) ? rows : [];
            setText(eksporSisaPaguJumlahPks, rowsValid.length.toLocaleString('id-ID'));
            setText(eksporSisaPaguTotalNominal, formatRupiahKomaDash(
                rowsValid.reduce((sum, row) => sum + (Number(row.sisa_pagu_alokasi_kerma) || 0), 0)
            ));
            setText(eksporSisaPaguTotalRealisasiPlotting, formatRupiahKomaDash(
                rowsValid.reduce((sum, row) => sum + (Number(row.realisasi_pagu_plotting) || 0), 0)
            ));
            setText(eksporSisaPaguTotalSisaPaguPlotting, formatRupiahKomaDash(
                rowsValid.reduce((sum, row) => sum + (Number(row.sisa_pagu_plotting) || 0), 0)
            ));
        };
        if (loading) {
            setRingkasanSisaPagu([]);
            bodyTabelEksporPlottingSisaPagu.innerHTML = tableState(6, 'loading', 'Memuat Sisa PAGU', 'Menghitung Sisa PAGU Alokasi Kerma aktif.');
            return;
        }
        if (error) {
            setRingkasanSisaPagu([]);
            bodyTabelEksporPlottingSisaPagu.innerHTML = tableState(6, 'error', 'Gagal memuat Sisa PAGU', error);
            return;
        }
        const sumber = dataEksporSisaPaguUntukFilter();
        const rows = colFilterEksporSisaPagu ? colFilterEksporSisaPagu.applyTo(sumber) : sumber;
        const adaFilterKolom = colFilterEksporSisaPagu && Object.keys(colFilterEksporSisaPagu.colFilters).length > 0;
        setRingkasanSisaPagu(rows);
        if (!rows.length) {
            bodyTabelEksporPlottingSisaPagu.innerHTML = adaFilterKolom
                ? tableState(6, 'empty', 'Tidak ada Sisa PAGU yang cocok', 'Ubah filter pada heading tabel untuk menampilkan data kembali.')
                : tableState(6, 'empty', 'Belum ada kerma aktif', 'Tabel hanya menampilkan kode file dengan Status Alokasi Aktif.');
            return;
        }
        bodyTabelEksporPlottingSisaPagu.innerHTML = rows.map((row, index) => `
            <tr>
                <td>${esc(row.no || index + 1)}</td>
                <td><span class="kode-file-tag">${esc(row.kode_file || '-')}</span></td>
                <td><strong>${esc(row.nama_mitra || '-')}</strong></td>
                <td class="td-number">${esc(row.sisa_pagu_alokasi_kerma_display || formatRupiahKomaDash(row.sisa_pagu_alokasi_kerma))}</td>
                <td class="td-number${Number(row.sisa_pagu_plotting) < 0 ? ' realisasi-sisa-negative' : ''}">${esc(row.sisa_pagu_plotting_display || formatRupiahKomaDash(row.sisa_pagu_plotting))}</td>
                <td class="td-number">${esc(row.realisasi_pagu_plotting_display || formatRupiahKomaDash(row.realisasi_pagu_plotting))}</td>
            </tr>
        `).join('');
    }

    function bidangJabatanDariLabelPlotting(role, label) {
        if (role === 'Ketua') return '-';
        const prefixByRole = {
            PJ: /^Penanggung Jawab\s+/i,
            Pengarah: /^Pengarah(?: Kegiatan)?\s+/i,
            'Kepala Admin': /^Kepala Administrasi(?: Pengelola)?\s+/i,
            Anggota: /^Anggota(?: Pengelola| Administrasi)?\s+/i
        };
        return String(label || '-').replace(prefixByRole[role] || /^$/, '').trim() || '-';
    }

    function bidangJabatanUntukDaftarPlotting(role, index) {
        return bidangJabatanDariLabelPlotting(role, labelJabatanPerBidangPlotSkBidang(role, index));
    }

    function dataEksporDaftarJabatanUntukFilter() {
        pastikanRowsPerhitunganDasarPlotting();
        return rolePlottingKerma.flatMap(role => {
            const konfigurasi = daftarKonfigurasiJabatanBidangPlotting(role);
            const jumlahPosisi = jumlahBarisPlotSkBidangUntukRole(role);
            const tarif = tarifPerBulanPlotSkBidang(role);
            const rowsKonfigurasi = konfigurasi.map(item => ({
                id: item.id,
                role,
                jabatan: namaJabatanPlotting(role),
                jabatan_per_bidang: item.nama,
                bidang: bidangJabatanDariLabelPlotting(role, item.nama),
                tarif,
                tarif_display: formatRupiahKomaDash(tarif),
                aktif: item.aktif !== false,
                status_display: item.aktif !== false ? 'Aktif' : 'Nonaktif',
                sintetis: false
            }));
            const jumlahTambahan = Math.max(
                0,
                jumlahPosisi - konfigurasi.filter(item => item.aktif !== false).length
            );
            const rowsTambahan = Array.from({ length: jumlahTambahan }, (_, index) => ({
                id: `${role}-tambahan-${index + 1}`,
                role,
                jabatan: namaJabatanPlotting(role),
                jabatan_per_bidang: `${namaJabatanPlotting(role)} - Tambahan ${index + 1}`,
                bidang: `Tambahan ${index + 1}`,
                tarif,
                tarif_display: formatRupiahKomaDash(tarif),
                aktif: true,
                status_display: 'Otomatis',
                sintetis: true
            }));
            return [...rowsKonfigurasi, ...rowsTambahan];
        }).map((row, index) => ({ ...row, no: index + 1 }));
    }

    function renderEksporDaftarJabatanPlotting() {
        if (!bodyTabelEksporPlottingDaftarJabatan) return;
        const sumber = dataEksporDaftarJabatanUntukFilter();
        const rows = colFilterEksporDaftarJabatan
            ? colFilterEksporDaftarJabatan.applyTo(sumber)
            : sumber;
        const adaFilterKolom = colFilterEksporDaftarJabatan
            && Object.keys(colFilterEksporDaftarJabatan.colFilters).length > 0;
        setText(document.getElementById('eksporDaftarJabatanKelompok'), new Set(rows.map(row => row.jabatan)).size.toLocaleString('id-ID'));
        setText(document.getElementById('eksporDaftarJabatanPosisi'), rows.filter(row => row.aktif).length.toLocaleString('id-ID'));
        if (!rows.length) {
            bodyTabelEksporPlottingDaftarJabatan.innerHTML = adaFilterKolom
                ? tableState(6, 'empty', 'Tidak ada jabatan yang cocok', 'Ubah filter pada heading tabel untuk menampilkan data kembali.')
                : tableState(6, 'empty', 'Belum ada daftar jabatan', 'Struktur jabatan belum tersedia pada konfigurasi Plotting Kerma.');
            return;
        }
        bodyTabelEksporPlottingDaftarJabatan.innerHTML = rows.map(row => `
            <tr>
                <td class="td-number">${esc(row.no)}</td>
                <td><strong class="plotting-jabatan-role-label">${esc(row.jabatan)}</strong></td>
                <td>${esc(row.bidang)}</td>
                <td class="td-number">${esc(row.tarif_display)}</td>
                <td><span class="plotting-jabatan-status ${row.aktif ? 'is-active' : 'is-inactive'}">${esc(row.status_display)}</span></td>
                <td>
                    ${row.sintetis
                        ? '<span class="plotting-jabatan-system-note">Mengikuti Personil per Kerma</span>'
                        : `<div class="plotting-jabatan-actions">
                            <button type="button" class="btn-row-edit" data-jabatan-bidang-action="edit" data-jabatan-bidang-role="${esc(row.role)}" data-jabatan-bidang-id="${esc(row.id)}">Edit</button>
                            <button type="button" class="btn-row-secondary" data-jabatan-bidang-action="toggle" data-jabatan-bidang-role="${esc(row.role)}" data-jabatan-bidang-id="${esc(row.id)}">${row.aktif ? 'Nonaktifkan' : 'Aktifkan'}</button>
                            <button type="button" class="btn-row-delete" data-jabatan-bidang-action="delete" data-jabatan-bidang-role="${esc(row.role)}" data-jabatan-bidang-id="${esc(row.id)}">Hapus</button>
                        </div>`}
                </td>
            </tr>
        `).join('');
    }

    function cariKonfigurasiJabatanBidangPlotting(role, id) {
        return daftarKonfigurasiJabatanBidangPlotting(role).find(item => String(item.id) === String(id));
    }

    function refreshSetelahPerubahanDaftarJabatanPlotting() {
        simpanPlottingKerma();
        if (!sectionPlottingKerma?.classList.contains('active')) return;
        renderPlottingKermaViews();
    }

    function tampilkanAlertEditDaftarJabatanPlotting(pesan = '') {
        if (!alertEditDaftarJabatanPlotting) return;
        alertEditDaftarJabatanPlotting.textContent = pesan;
        alertEditDaftarJabatanPlotting.style.display = pesan ? '' : 'none';
    }

    function bukaModalEditDaftarJabatanPlotting(role, id) {
        const item = cariKonfigurasiJabatanBidangPlotting(role, id);
        if (!item || item.sintetis) return;
        jabatanBidangEditState = { role, id: String(id) };
        if (inputJabatanDaftarJabatanPlotting) inputJabatanDaftarJabatanPlotting.value = namaJabatanPlotting(role);
        if (inputNamaDaftarJabatanPlotting) inputNamaDaftarJabatanPlotting.value = item.nama;
        if (selectStatusDaftarJabatanPlotting) selectStatusDaftarJabatanPlotting.value = item.aktif === false ? 'nonaktif' : 'aktif';
        tampilkanAlertEditDaftarJabatanPlotting('');
        if (modalEditDaftarJabatanPlotting) modalEditDaftarJabatanPlotting.style.display = 'flex';
        inputNamaDaftarJabatanPlotting?.focus();
    }

    function tutupModalEditDaftarJabatanPlotting() {
        jabatanBidangEditState = null;
        tampilkanAlertEditDaftarJabatanPlotting('');
        if (modalEditDaftarJabatanPlotting) modalEditDaftarJabatanPlotting.style.display = 'none';
    }

    function simpanEditDaftarJabatanPlotting() {
        const state = jabatanBidangEditState;
        if (!state) return;
        const item = cariKonfigurasiJabatanBidangPlotting(state.role, state.id);
        const nama = String(inputNamaDaftarJabatanPlotting?.value || '').trim().replace(/\s+/g, ' ');
        if (!item) {
            tampilkanAlertEditDaftarJabatanPlotting('Jabatan tidak ditemukan. Muat ulang daftar dan coba kembali.');
            return;
        }
        if (!nama) {
            tampilkanAlertEditDaftarJabatanPlotting('Nama jabatan/bidang wajib diisi.');
            return;
        }
        const duplikat = daftarKonfigurasiJabatanBidangPlotting(state.role).some(candidate => (
            String(candidate.id) !== String(state.id)
            && candidate.nama.toLowerCase() === nama.toLowerCase()
        ));
        if (duplikat) {
            tampilkanAlertEditDaftarJabatanPlotting('Nama jabatan/bidang tersebut sudah ada pada kelompok jabatan ini.');
            return;
        }
        item.nama = nama;
        item.aktif = selectStatusDaftarJabatanPlotting?.value !== 'nonaktif';
        tutupModalEditDaftarJabatanPlotting();
        refreshSetelahPerubahanDaftarJabatanPlotting();
    }

    function handleDaftarJabatanPlottingAction(target) {
        const button = target?.closest?.('[data-jabatan-bidang-action]');
        if (!button) return;
        const action = button.dataset.jabatanBidangAction;
        const role = button.dataset.jabatanBidangRole || '';
        const id = button.dataset.jabatanBidangId || '';
        const item = cariKonfigurasiJabatanBidangPlotting(role, id);
        if (!item) return;

        if (action === 'edit') {
            bukaModalEditDaftarJabatanPlotting(role, id);
            return;
        }
        if (action === 'toggle') {
            item.aktif = item.aktif === false;
            refreshSetelahPerubahanDaftarJabatanPlotting();
            return;
        }
        if (action === 'delete') {
            const setuju = window.confirm(`Hapus ${item.nama}? Data Plot SK yang sudah ada tidak ikut dihapus, tetapi labelnya perlu diperiksa kembali.`);
            if (!setuju) return;
            const daftar = daftarKonfigurasiJabatanBidangPlotting(role);
            const index = daftar.findIndex(candidate => String(candidate.id) === String(id));
            if (index < 0) return;
            daftar.splice(index, 1);
            refreshSetelahPerubahanDaftarJabatanPlotting();
        }
    }

    function renderEksporPlottingKerma({ semuaTab = false } = {}) {
        const penyesuaianTarget = sinkronkanPlotSkBidangManualDenganTarget();
        if (penyesuaianTarget.changed) simpanPlottingKerma();
        const tab = tabAktifEksporPlottingKerma || 'batasan';
        const perluRender = namaTab => semuaTab || tab === namaTab;
        if (perluRender('hasilSimulasi')) renderDaftarHasilSimulasiPlotting();
        if (perluRender('target')) renderEksporTargetDistribusiPlotting();
        if (perluRender('batasan')) renderBatasanSimulasiPlotting();
        if (perluRender('dasar')) renderEksporPerhitunganDasarPlotting();
        if (perluRender('sisa')) renderEksporSisaPaguPlotting();
        if (perluRender('daftarJabatan')) renderEksporDaftarJabatanPlotting();
        if (perluRender('plotSkBidang')) renderEksporPlotSkBidang();
        if (perluRender('rekapitulasi')) renderEksporRekapitulasiPlotting();
        updateStatusMulaiPlottingKerma();
        renderSesiSimulasiBar();
    }

    async function muatDataEksporPlottingKerma() {
        if (sedangMemuatEksporPlottingKerma) return;
        sedangMemuatEksporPlottingKerma = true;
        renderEksporSisaPaguPlotting({ loading: true });
        try {
            await ensureKermaData();
            renderEksporPlottingKerma();
        } catch (err) {
            renderEksporSisaPaguPlotting({
                error: err?.message || 'Periksa koneksi server atau coba kembali.'
            });
        } finally {
            sedangMemuatEksporPlottingKerma = false;
        }
    }

    function setTabEksporPlottingKerma(tab = tabAktifEksporPlottingKerma) {
        const nextTab = ['hasilSimulasi', 'sisa', 'daftarJabatan', 'batasan', 'dasar', 'target', 'plotSkBidang', 'rekapitulasi'].includes(tab) ? tab : 'batasan';
        tabAktifEksporPlottingKerma = nextTab;
        const isHasilSimulasi = nextTab === 'hasilSimulasi';
        const isTarget = nextTab === 'target';
        const isBatasan = nextTab === 'batasan';
        const isDasar = nextTab === 'dasar';
        const isSisa = nextTab === 'sisa';
        const isDaftarJabatan = nextTab === 'daftarJabatan';
        const isPlotSkBidang = nextTab === 'plotSkBidang';
        const isRekapitulasi = nextTab === 'rekapitulasi';

        tabEksporPlottingDaftarSimulasi?.classList.toggle('active', isHasilSimulasi);
        tabEksporPlottingTargetDistribusi?.classList.toggle('active', isTarget);
        tabEksporPlottingBatasanSimulasi?.classList.toggle('active', isBatasan);
        tabEksporPlottingPerhitunganDasar?.classList.toggle('active', isDasar);
        tabEksporPlottingSisaPagu?.classList.toggle('active', isSisa);
        tabEksporPlottingDaftarJabatan?.classList.toggle('active', isDaftarJabatan);
        tabEksporPlottingPlotSkBidang?.classList.toggle('active', isPlotSkBidang);
        tabEksporPlottingRekapitulasi?.classList.toggle('active', isRekapitulasi);
        tabEksporPlottingDaftarSimulasi?.setAttribute('aria-selected', String(isHasilSimulasi));
        tabEksporPlottingTargetDistribusi?.setAttribute('aria-selected', String(isTarget));
        tabEksporPlottingBatasanSimulasi?.setAttribute('aria-selected', String(isBatasan));
        tabEksporPlottingPerhitunganDasar?.setAttribute('aria-selected', String(isDasar));
        tabEksporPlottingSisaPagu?.setAttribute('aria-selected', String(isSisa));
        tabEksporPlottingDaftarJabatan?.setAttribute('aria-selected', String(isDaftarJabatan));
        tabEksporPlottingPlotSkBidang?.setAttribute('aria-selected', String(isPlotSkBidang));
        tabEksporPlottingRekapitulasi?.setAttribute('aria-selected', String(isRekapitulasi));

        if (panelEksporPlottingDaftarSimulasi) panelEksporPlottingDaftarSimulasi.style.display = isHasilSimulasi ? '' : 'none';
        if (panelEksporPlottingTargetDistribusi) panelEksporPlottingTargetDistribusi.style.display = isTarget ? '' : 'none';
        if (panelEksporPlottingBatasanSimulasi) panelEksporPlottingBatasanSimulasi.style.display = isBatasan ? '' : 'none';
        if (panelEksporPlottingPerhitunganDasar) panelEksporPlottingPerhitunganDasar.style.display = isDasar ? '' : 'none';
        if (panelEksporPlottingSisaPagu) panelEksporPlottingSisaPagu.style.display = isSisa ? '' : 'none';
        if (panelEksporPlottingDaftarJabatan) panelEksporPlottingDaftarJabatan.style.display = isDaftarJabatan ? '' : 'none';
        if (panelEksporPlottingPlotSkBidang) panelEksporPlottingPlotSkBidang.style.display = isPlotSkBidang ? '' : 'none';
        if (panelEksporPlottingRekapitulasi) panelEksporPlottingRekapitulasi.style.display = isRekapitulasi ? '' : 'none';

        renderEksporPlottingKerma();
        if ((isSisa || isPlotSkBidang || isRekapitulasi) && !allData.length) void muatDataEksporPlottingKerma();
    }

    function renderTargetDistribusiPlotting() {
        if (!bodyTabelTargetDistribusi) return;
        if (!plottingKermaRows.length) plottingKermaRows.push(buatBarisPlottingKerma());
        const rowsAktif = plottingKermaRows
            .map((row, rowIndex) => ({ row, rowIndex }))
            .filter(({ row }) => isPegawaiAktifDenganTargetKerma(row))
            .sort(bandingkanTargetDistribusiDosenStaf);

        if (!rowsAktif.length) {
            bodyTabelTargetDistribusi.innerHTML = '<tr class="table-state-row"><td colspan="10"><div class="table-state">Belum ada pegawai aktif dengan Target Distribusi. Edit Target Distribusi pada Daftar Pegawai agar pegawai muncul di tabel ini.</div></td></tr>';
            updateRingkasanDasarPlotting();
            return;
        }

        bodyTabelTargetDistribusi.innerHTML = rowsAktif.map(({ row, rowIndex }, index) => {
            pastikanPksPlotting(row);
            const distribusiRoles = pastikanDistribusiRoles(row);
            const realisasiDistribusi = hitungRealisasiDistribusiRow(row);
            const selisihDistribusi = hitungSelisihDistribusiRow(row);
            const batasBawahRow = batasSelisihBawahEfektif(row);
            const melewatiBatasBawah = Number.isFinite(batasBawahRow) && selisihDistribusi < batasBawahRow;
            const selisihClass = melewatiBatasBawah
                ? ' realisasi-sisa-negative'
                : (isDosenDistribusi(row) && isBatasanSimulasiAktif('batasSelisihAtas') && selisihDistribusi > batasSelisihDistribusi ? ' realisasi-sisa-warning' : '');
            const roleCells = rolePlottingKerma.map(role => {
                const roleTerkunci = !isRoleBolehDistribusi(row, role);
                const nilaiRole = normalisasiNilaiDistribusiRole(distribusiRoles[role] ?? '', role);
                if (nilaiRole !== (distribusiRoles[role] ?? '')) distribusiRoles[role] = nilaiRole;
                const roleBolehLabel = labelRoleBolehDistribusi(row);
                const peranLabel = isStafDistribusi(row) ? 'Staf' : 'Dosen';
                return `
                    <td class="plotting-role-cell plotting-pks-role-cell">
                        <input type="text" inputmode="text" class="form-input plotting-input plotting-input--number plotting-input--role-count" data-row="${rowIndex}" data-distribusi-role="${esc(role)}" value="${esc(roleTerkunci ? '' : nilaiRole)}" placeholder="${esc(roleTerkunci ? '-' : formatPlaceholderDistribusiRole(role))}" title="${esc(roleTerkunci ? `${peranLabel} hanya dapat dialokasikan pada: ${roleBolehLabel}` : `${titleJabatanPlotting(role)} - isi seperti 1, 2, (4/6), atau 3 + (4/6)`)}" ${roleTerkunci ? 'readonly aria-disabled="true"' : ''}>
                    </td>
                `;
            }).join('');
            return `
                <tr>
                    <td class="plotting-col-no">${index + 1}</td>
                    <td class="plotting-name-cell">
                        <button type="button" class="plotting-name-ellipsis" data-target-name-toggle aria-expanded="false" title="${esc(row.nama || '-')}">${esc(row.nama || '-')}</button>
                    </td>
                    <td class="plotting-money-cell" data-target-distribusi-row="${rowIndex}">${formatRupiahKomaDash(hitungTargetDistribusiRow(row))}</td>
                    ${roleCells}
                    <td class="plotting-money-cell" data-realisasi-distribusi-row="${rowIndex}">${formatRupiahKomaDash(realisasiDistribusi)}</td>
                    <td class="plotting-money-cell${selisihClass}" data-selisih-distribusi-row="${rowIndex}">${formatRupiahKomaDash(selisihDistribusi)}</td>
                </tr>
            `;
        }).join('');
        updateKapasitasRoleTargetDistribusi();
        updateRingkasanDasarPlotting();
    }

    let sedangMemuatDaftarPksPlotting = false;
    let dataSisaAnggaranPlottingDimuat = false;
    let pesanErrorDaftarPksPlotting = '';

    function invalidasiDataSisaAnggaranPlotting() {
        if (sedangMemuatDaftarPksPlotting) return;
        dataSisaAnggaranPlottingDimuat = false;
        pesanErrorDaftarPksPlotting = '';
        allPksAlokasiData = [];
    }

    function statusSisaAnggaranPlotting(item) {
        if (String(item.status_alokasi || '').trim() !== 'Aktif') return 'Terserap';
        const sisa = Number(item.sisa_anggaran) || 0;
        if (sisa < 0) return 'Defisit';
        if (sisa > 0 && item.status_kontrak === 'Berakhir') return 'Perlu Dihitung Kembali';
        if (sisa > 0) return 'Dapat Dialokasikan';
        return 'Terserap';
    }

    function getDaftarPksDapatDialokasikan() {
        const minimalSisa = hitungMinimalSisaPksPlotting();
        if (minimalSisa <= 0) return [];
        return sumberPksAlokasiKermaPlotting()
            .filter(item => String(item.status_alokasi || '').trim() === 'Aktif')
            .filter(item => (Number(item.sisa_anggaran) || 0) > 0)
            .sort((a, b) => {
                const bySisa = (Number(b.sisa_anggaran) || 0) - (Number(a.sisa_anggaran) || 0);
                if (bySisa !== 0) return bySisa;
                return urutKodeFileTahunTerbaru(a, b);
            });
    }

    function getKandidatPksBerdasarkanSisaPaguAlokasi(minimalSisa = hitungMinimalSisaPksPlotting()) {
        if (minimalSisa <= 0) return [];
        return sumberPksAlokasiKermaPlotting()
            .filter(item => String(item.status_alokasi || '').trim() === 'Aktif')
            .filter(item => (Number(item.sisa_anggaran) || 0) > 0)
            .sort((a, b) => {
                const bySisa = (Number(b.sisa_anggaran) || 0) - (Number(a.sisa_anggaran) || 0);
                if (bySisa !== 0) return bySisa;
                return urutKodeFileTahunTerbaru(a, b);
            });
    }

    function normalisasiPksAlokasiKermaUntukPlotting(row = {}) {
        const sisaPaguAlokasi = angkaPaguAnggaran(row.sisa_pagu_alokasi_kerma);
        const pembayaran = angkaPaguAnggaran(row.pembayaran);
        const nilaiKontrak = angkaPaguAnggaran(row.nilai_kontrak);
        const kodeFile = row.kode_file || row.id_program || '';
        return {
            ...row,
            id_program: row.id_program || row.kode_file || '',
            status_alokasi: row.status_alokasi || statusAlokasiKodeFile(kodeFile, row.id_program),
            total_realisasi_pendapatan: pembayaran,
            total_realisasi_pendapatan_display: row.pembayaran_display || formatRupiahKomaDash(pembayaran),
            nilai_kontrak: nilaiKontrak,
            nilai_kontrak_display: row.nilai_kontrak_display || formatRupiahKomaDash(nilaiKontrak),
            sisa_anggaran: sisaPaguAlokasi,
            sisa_anggaran_display: row.sisa_pagu_alokasi_kerma_display || formatRupiahKomaDash(sisaPaguAlokasi),
            status_sisa_anggaran: sisaPaguAlokasi > 0 ? 'Dapat Dialokasikan' : 'Terserap'
        };
    }

    function dataPksAlokasiKermaLangsung() {
        return dataAlokasiKermaAktif().map(normalisasiPksAlokasiKermaUntukPlotting);
    }

    function sumberPksAlokasiKermaPlotting() {
        return allPksAlokasiData.length ? allPksAlokasiData : dataPksAlokasiKermaLangsung();
    }

    function getIdPksPlotting(item = {}) {
        return String(item.id_program || item.kode_file || '').trim();
    }

    function hitungJumlahKebutuhanPksTersimpan() {
        return hitungPksDitetapkanPlotting();
    }

    function hitungMinimalSisaPksPlotting() {
        return Math.max(0, hitungTotalPerKermaPlotting());
    }

    function hitungKuotaPilihanPksPlotting(totalPerKerma = totalPerKermaTersimpan || hitungTotalPerKermaPlotting()) {
        const ditetapkan = hitungPksDitetapkanPlotting();
        if (ditetapkan > 0) return ditetapkan;
        return hitungTotalKebutuhanPksDasar(totalPerKerma);
    }

    function hitungJumlahPksTerpilihPlotting() {
        return daftarPksTerpilihPlotting.filter(Boolean).length;
    }

    function getDataPksTerpilihPlotting(data = getDaftarPksDapatDialokasikan()) {
        const mapData = new Map(data.map(item => [getIdPksPlotting(item), item]));
        return daftarPksTerpilihPlotting
            .map(id => mapData.get(id))
            .filter(Boolean);
    }

    function nilaiKontrakPksPlotting(item = {}) {
        return Math.max(
            0,
            Number(item.nilai_kontrak) ||
            Number(item.nilai_kontrak_raw) ||
            parseNominalRupiah(item.nilai_kontrak_display || item.nilai_kontrak)
        );
    }

    function nilaiKontrakDiakuiPksPlotting(item = {}, acuanPerKerma = hitungMinimalSisaPksPlotting()) {
        const nilaiKontrak = nilaiKontrakPksPlotting(item);
        const acuan = Math.max(0, Number(acuanPerKerma) || 0);
        return acuan > 0 ? Math.min(nilaiKontrak, acuan) : nilaiKontrak;
    }

    function hitungTotalNominalKontrakTerpilihPlotting(dataTerpilih = [], acuanPerKerma = hitungMinimalSisaPksPlotting()) {
        return dataTerpilih.reduce((sum, item) => sum + nilaiKontrakDiakuiPksPlotting(item, acuanPerKerma), 0);
    }

    function updateRingkasanPilihanPksPlotting(data = []) {
        const jumlahKebutuhan = hitungKuotaPilihanPksPlotting();
        const dataTerpilih = getDataPksTerpilihPlotting(data);
        const totalTerpilih = hitungTotalNominalKontrakTerpilihPlotting(dataTerpilih);
        const target = hitungTotalTargetDistribusiPlotting();
        if (jumlahPksTerpilihPlottingLabel) {
            jumlahPksTerpilihPlottingLabel.textContent = `${dataTerpilih.length.toLocaleString('id-ID')}/${jumlahKebutuhan.toLocaleString('id-ID')}`;
        }
        if (totalSisaPksTerpilihPlotting) {
            totalSisaPksTerpilihPlotting.textContent = formatRupiahKomaDash(totalTerpilih);
        }
        if (!statusKecukupanPksTerpilihPlotting) return;
        setClassStatusRingkas(statusKecukupanPksTerpilihPlotting);
        if (jumlahKebutuhan <= 0) {
            statusKecukupanPksTerpilihPlotting.textContent = '-';
            return;
        }
        if (dataTerpilih.length < jumlahKebutuhan) {
            const kurang = jumlahKebutuhan - dataTerpilih.length;
            statusKecukupanPksTerpilihPlotting.textContent = `Kurang ${kurang.toLocaleString('id-ID')} PKS`;
            setClassStatusRingkas(statusKecukupanPksTerpilihPlotting, 'is-warning');
            return;
        }
        if (target <= 0) {
            statusKecukupanPksTerpilihPlotting.textContent = 'Belum ada target';
            setClassStatusRingkas(statusKecukupanPksTerpilihPlotting, 'is-warning');
            return;
        }
        if (totalTerpilih >= target) {
            statusKecukupanPksTerpilihPlotting.textContent = 'Cukup';
            setClassStatusRingkas(statusKecukupanPksTerpilihPlotting, 'is-match');
            return;
        }
        statusKecukupanPksTerpilihPlotting.textContent = `Kurang ${formatRupiahKomaDash(target - totalTerpilih)}`;
        setClassStatusRingkas(statusKecukupanPksTerpilihPlotting, 'is-warning');
    }

    function updateKontrolPilihSemuaPksPlotting(data = []) {
        if (!checkAllPksPlotting) return;
        const jumlahKebutuhan = hitungKuotaPilihanPksPlotting();
        const idsTersedia = data.map(getIdPksPlotting).filter(Boolean);
        const batasPilihan = Math.min(jumlahKebutuhan, idsTersedia.length);
        const idTersedia = new Set(idsTersedia);
        const jumlahTerpilih = daftarPksTerpilihPlotting
            .filter(id => id && idTersedia.has(id))
            .length;

        checkAllPksPlotting.disabled = batasPilihan <= 0;
        checkAllPksPlotting.checked = batasPilihan > 0 && jumlahTerpilih >= batasPilihan;
        checkAllPksPlotting.indeterminate = jumlahTerpilih > 0 && jumlahTerpilih < batasPilihan;
        checkAllPksPlotting.title = batasPilihan > 0
            ? `Pilih ${batasPilihan.toLocaleString('id-ID')} PKS sesuai batas PKS Ditetapkan Admin`
            : 'Tetapkan jumlah PKS terlebih dahulu';
    }

    function sinkronPilihanDaftarPks(data = []) {
        const idTersedia = new Set(data.map(getIdPksPlotting).filter(Boolean));
        const jumlahKebutuhan = hitungKuotaPilihanPksPlotting();
        const idSudahDipakai = new Set();
        daftarPksTerpilihPlotting = Array.from({ length: jumlahKebutuhan }, (_, index) => {
            const id = daftarPksTerpilihPlotting[index];
            if (!id || !idTersedia.has(id) || idSudahDipakai.has(id)) return '';
            idSudahDipakai.add(id);
            return id;
        });
    }

    function getNomorPksAlokasi(id) {
        const index = daftarPksTerpilihPlotting.indexOf(id);
        return index >= 0 ? index + 1 : '';
    }

    function getDaftarPksEfektifUntukPenempatanPlotSk() {
        const sumber = sumberPksAlokasiKermaPlotting();
        const byId = new Map(sumber.map(item => [getIdPksPlotting(item), item]));
        const terpilih = daftarPksTerpilihPlotting
            .map(id => byId.get(id))
            .filter(Boolean);
        const terpilihIds = new Set(terpilih.map(getIdPksPlotting));
        const aktif = getDataPksSimulasiTargetDistribusi()
            .filter(item => !terpilihIds.has(getIdPksPlotting(item)));
        return [...terpilih, ...aktif];
    }

    function getPksAlokasiByNomor(noPks) {
        return getDaftarPksEfektifUntukPenempatanPlotSk()[Math.max(0, Number(noPks) - 1)] || null;
    }

    function setNomorPksAlokasi(target) {
        const id = target?.dataset?.pksAlokasiId;
        if (!id) return;
        const jumlahKebutuhan = hitungKuotaPilihanPksPlotting();
        const nomorSebelumnya = getNomorPksAlokasi(id);
        let nomor = Math.trunc(Number(target.value) || 0);
        if (nomor < 1) nomor = 0;
        if (nomor > jumlahKebutuhan) nomor = jumlahKebutuhan;
        const idPadaNomor = nomor > 0 ? daftarPksTerpilihPlotting[nomor - 1] : '';

        if (idPadaNomor && idPadaNomor !== id) {
            window.alert('Nomor sudah dimasukkan');
            target.value = nomorSebelumnya || '';
            renderDaftarPksPlotting();
            return;
        }

        daftarPksTerpilihPlotting = Array.from({ length: jumlahKebutuhan }, (_, index) => (
            daftarPksTerpilihPlotting[index] === id ? '' : (daftarPksTerpilihPlotting[index] || '')
        ));
        if (nomor > 0) {
            daftarPksTerpilihPlotting[nomor - 1] = id;
        }

        tandaiPilihanPksPerhitunganDasarBerubah();
        simpanPlottingKerma();
        renderDaftarPksPlotting();
        if (tabAktifPlottingKerma === 'plot') renderPlottingKerma();
    }

    function togglePilihanPksAlokasi(target) {
        const id = target?.dataset?.pksPilihId;
        if (!id) return;
        const data = getDaftarPksDapatDialokasikan();
        const jumlahKebutuhan = hitungKuotaPilihanPksPlotting();
        sinkronPilihanDaftarPks(data);

        if (target.checked) {
            if (getNomorPksAlokasi(id)) {
                renderDaftarPksPlotting();
                return;
            }
            const jumlahTerpilih = hitungJumlahPksTerpilihPlotting();
            if (jumlahTerpilih >= jumlahKebutuhan) {
                window.alert(`PKS yang dipilih sudah mencapai PKS Ditetapkan Admin (${jumlahKebutuhan.toLocaleString('id-ID')} PKS).`);
                renderDaftarPksPlotting();
                return;
            }
            const slotKosong = daftarPksTerpilihPlotting.findIndex(item => !item);
            if (slotKosong >= 0) daftarPksTerpilihPlotting[slotKosong] = id;
        } else {
            daftarPksTerpilihPlotting = daftarPksTerpilihPlotting.filter(item => item && item !== id);
            while (daftarPksTerpilihPlotting.length < jumlahKebutuhan) daftarPksTerpilihPlotting.push('');
        }

        tandaiPilihanPksPerhitunganDasarBerubah();
        simpanPlottingKerma();
        renderDaftarPksPlotting();
        updateStatusPerhitunganDasar();
    }

    function togglePilihSemuaPksAlokasi(checked) {
        const data = getDaftarPksDapatDialokasikan();
        const jumlahKebutuhan = hitungKuotaPilihanPksPlotting();
        sinkronPilihanDaftarPks(data);

        if (checked && jumlahKebutuhan > 0) {
            const idsTersedia = data.map(getIdPksPlotting).filter(Boolean);
            const idTersedia = new Set(idsTersedia);
            const pilihanSaatIni = daftarPksTerpilihPlotting
                .filter(id => id && idTersedia.has(id));
            const pilihanBaru = [...new Set(pilihanSaatIni)];

            for (const id of idsTersedia) {
                if (pilihanBaru.length >= jumlahKebutuhan) break;
                if (!pilihanBaru.includes(id)) pilihanBaru.push(id);
            }

            daftarPksTerpilihPlotting = pilihanBaru.slice(0, jumlahKebutuhan);
        } else {
            daftarPksTerpilihPlotting = [];
        }

        while (daftarPksTerpilihPlotting.length < jumlahKebutuhan) daftarPksTerpilihPlotting.push('');

        tandaiPilihanPksPerhitunganDasarBerubah();
        simpanPlottingKerma();
        renderDaftarPksPlotting();
        updateStatusPerhitunganDasar();
    }

    function handlePilihSemuaPksPlottingChange(event) {
        const checked = Boolean(event?.target?.checked);
        mintaKonfirmasiUbahPerhitunganDasar(
            () => togglePilihSemuaPksAlokasi(checked),
            () => renderDaftarPksPlotting(),
            'Daftar PKS yang dialokasikan'
        );
    }

    async function muatDataSisaAnggaranPlotting() {
        if (sedangMemuatDaftarPksPlotting) return;
        sedangMemuatDaftarPksPlotting = true;
        pesanErrorDaftarPksPlotting = '';
        try {
            await ensureKermaData();
            const [resPembayaran, resPagu] = await Promise.all([
                fetch(`/api/daftar-realisasi-pembayaran?_=${Date.now()}`, { cache: 'no-store', credentials: 'same-origin' }),
                fetch(`/api/pagu-anggaran?_=${Date.now()}`, { cache: 'no-store', credentials: 'same-origin' })
            ]);
            const [payloadPembayaran, payloadPagu] = await Promise.all([
                resPembayaran.json(),
                resPagu.json()
            ]);
            if (!resPembayaran.ok) throw new Error(payloadPembayaran.pesan || 'Gagal memuat data pembayaran.');
            if (!resPagu.ok) throw new Error(payloadPagu.pesan || 'Gagal memuat data PAGU.');
            allPembayaranData = payloadPembayaran.data || [];
            allPaguAnggaranData = payloadPagu.data || [];
            allPksAlokasiData = dataPksAlokasiKermaLangsung()
                .sort((a, b) => {
                    const bySisa = (Number(b.sisa_anggaran) || 0) - (Number(a.sisa_anggaran) || 0);
                    if (bySisa !== 0) return bySisa;
                    return urutKodeFileTahunTerbaru(a, b);
                })
                .map((item, index) => ({ ...item, no: index + 1 }));
            dataSisaAnggaranPlottingDimuat = true;
        } catch {
            allPksAlokasiData = [];
            dataSisaAnggaranPlottingDimuat = true;
            pesanErrorDaftarPksPlotting = 'Gagal memuat Daftar PKS';
        } finally {
            sedangMemuatDaftarPksPlotting = false;
            renderDaftarPksPlotting();
            if (tabAktifPlottingKerma === 'plot') renderPlottingKerma();
        }
    }

    async function tungguDataSisaAnggaranPlottingSelesai() {
        while (sedangMemuatDaftarPksPlotting) {
            await new Promise(resolve => setTimeout(resolve, 40));
        }
    }

    async function pastikanDataSisaAnggaranPlottingUntukSimulasi() {
        if (dataSisaAnggaranPlottingDimuat && !pesanErrorDaftarPksPlotting) return true;
        if (!sedangMemuatDaftarPksPlotting) await muatDataSisaAnggaranPlotting();
        await tungguDataSisaAnggaranPlottingSelesai();
        return dataSisaAnggaranPlottingDimuat && !pesanErrorDaftarPksPlotting;
    }

    function renderDaftarPksPlotting() {
        if (!bodyTabelDaftarPksPlotting) return;
        const minimalSisa = hitungMinimalSisaPksPlotting();
        if (minimalSisaPksPlotting) minimalSisaPksPlotting.textContent = minimalSisa > 0 ? formatRupiahKomaDash(minimalSisa) : 'Isi Total per Kerma';

        if (minimalSisa <= 0) {
            if (jumlahPksDapatDialokasikan) jumlahPksDapatDialokasikan.textContent = '0';
            if (totalSisaPksDapatDialokasikan) totalSisaPksDapatDialokasikan.textContent = formatRupiahKomaDash(0);
            updateRingkasanPilihanPksPlotting([]);
            updateKontrolPilihSemuaPksPlotting([]);
            bodyTabelDaftarPksPlotting.innerHTML = tableState(7, 'empty', 'Isi Total per Kerma terlebih dahulu', 'Daftar PKS akan muncul otomatis setelah Total per Kerma lebih dari Rp 0,-.');
            return;
        }

        if (!dataSisaAnggaranPlottingDimuat) {
            if (jumlahPksDapatDialokasikan) jumlahPksDapatDialokasikan.textContent = '0';
            if (totalSisaPksDapatDialokasikan) totalSisaPksDapatDialokasikan.textContent = formatRupiahKomaDash(0);
            updateRingkasanPilihanPksPlotting([]);
            updateKontrolPilihSemuaPksPlotting([]);
            bodyTabelDaftarPksPlotting.innerHTML = tableState(7, 'loading', 'Memuat Daftar PKS', 'Mencari PKS dengan Sisa PAGU Alokasi Kerma positif.');
            muatDataSisaAnggaranPlotting();
            return;
        }
        if (pesanErrorDaftarPksPlotting) {
            if (jumlahPksDapatDialokasikan) jumlahPksDapatDialokasikan.textContent = '0';
            if (totalSisaPksDapatDialokasikan) totalSisaPksDapatDialokasikan.textContent = formatRupiahKomaDash(0);
            updateRingkasanPilihanPksPlotting([]);
            updateKontrolPilihSemuaPksPlotting([]);
            bodyTabelDaftarPksPlotting.innerHTML = tableState(7, 'error', pesanErrorDaftarPksPlotting, 'Periksa koneksi server atau coba kembali.');
            return;
        }

        const data = getDaftarPksDapatDialokasikan();
        sinkronPilihanDaftarPks(data);
        simpanPlottingKerma();
        const jumlahKebutuhan = hitungKuotaPilihanPksPlotting();
        const totalSisa = data.reduce((sum, item) => sum + (Number(item.sisa_anggaran) || 0), 0);
        if (jumlahPksDapatDialokasikan) jumlahPksDapatDialokasikan.textContent = data.length.toLocaleString('id-ID');
        if (totalSisaPksDapatDialokasikan) totalSisaPksDapatDialokasikan.textContent = formatRupiahKomaDash(totalSisa);
        updateRingkasanPilihanPksPlotting(data);
        updateKontrolPilihSemuaPksPlotting(data);
        if (!data.length) {
            bodyTabelDaftarPksPlotting.innerHTML = tableState(7, 'empty', 'Belum ada PKS yang dapat dialokasikan', 'Daftar membutuhkan PKS aktif dengan Sisa PAGU Alokasi Kerma lebih dari Rp 0,-.');
            return;
        }

        const jumlahTerpilih = hitungJumlahPksTerpilihPlotting();
        bodyTabelDaftarPksPlotting.innerHTML = data.map((item, index) => {
            const id = getIdPksPlotting(item);
            const nomorAlokasi = getNomorPksAlokasi(id);
            const isDipilih = Boolean(nomorAlokasi);
            const disabledPilih = !id || (!isDipilih && jumlahTerpilih >= jumlahKebutuhan);
            return `
                <tr>
                    <td>${index + 1}</td>
	                    <td>
	                        <input type="checkbox" class="plotting-pks-check" data-pks-pilih-id="${esc(id)}" aria-label="Pilih PKS ${esc(item.kode_file || item.id_program || '')}" ${isDipilih ? 'checked' : ''} ${disabledPilih ? 'disabled' : ''}>
	                    </td>
	                    <td><span class="plotting-pks-order-badge ${isDipilih ? '' : 'is-empty'}">${isDipilih ? esc(nomorAlokasi) : '-'}</span></td>
                    <td><span class="kode-file-tag">${esc(item.kode_file || item.id_program || '-')}</span></td>
                    <td class="td-truncate"><strong>${esc(item.nama_mitra || '-')}</strong></td>
                    <td class="td-truncate">${esc(item.judul_pks || '-')}</td>
                    <td class="plotting-money-cell">${esc(item.sisa_anggaran_display || 'Rp 0')}</td>
                </tr>
            `;
        }).join('');
    }

    function renderDaftarPegawai() {
        if (!bodyTabelPegawai) return;
        if (!plottingKermaRows.length) plottingKermaRows.push(buatBarisPlottingKerma());
        renderDatalistPegawai();
        bodyTabelPegawai.innerHTML = plottingKermaRows.map((row, rowIndex) => {
            const isEditing = pegawaiEditRowIndex === rowIndex;
            const level1 = getLevelJabatanMaster(row.jabatan_sbm) || '-';
            const level2 = getLevelJabatanMaster(row.jabatan_sbm_2) || '-';
            if (isEditing) {
                return `
                    <tr class="pegawai-row-editing">
                        <td class="plotting-col-no">${rowIndex + 1}</td>
                        <td><input type="text" class="form-input plotting-input" data-pegawai-field="gelar_depan" value="${esc(row.gelar_depan || '')}" placeholder="Contoh: Prof. Dr."></td>
                        <td><input type="text" class="form-input plotting-input" data-pegawai-field="nama" value="${esc(row.nama || '')}" placeholder="Nama pegawai"></td>
                        <td><input type="text" class="form-input plotting-input" data-pegawai-field="gelar_belakang" value="${esc(row.gelar_belakang || '')}" placeholder="Contoh: Ph.D."></td>
                        <td>
                            <select class="form-input plotting-input plotting-input--select" data-pegawai-field="peran">
                                ${renderSelectPegawaiOption('Dosen', row.peran)}
                                ${renderSelectPegawaiOption('Staf', row.peran)}
                            </select>
                        </td>
                        <td>
                            <select class="form-input plotting-input plotting-input--select" data-pegawai-field="jabatan_fungsional">
                                <option value="">Pilih Jabatan Fungsional</option>
                                ${jabatanFungsionalPegawai.map(value => renderSelectPegawaiOption(value, row.jabatan_fungsional)).join('')}
                                ${row.jabatan_fungsional && !jabatanFungsionalPegawai.includes(row.jabatan_fungsional)
                                    ? renderSelectPegawaiOption(row.jabatan_fungsional, row.jabatan_fungsional)
                                    : ''}
                            </select>
                        </td>
                        <td>
                            <select class="form-input plotting-input plotting-input--select" data-pegawai-field="kelompok_keahlian">
                                <option value="">Pilih Kelompok Keahlian</option>
                                ${daftarPilihanKelompokKeahlianPegawai().map(value => renderSelectPegawaiOption(value, row.kelompok_keahlian)).join('')}
                            </select>
                        </td>
                        <td>
                            <select class="form-input plotting-input plotting-input--select" data-pegawai-field="status">
                                ${statusDistribusiPlotting.map(status => renderSelectPegawaiOption(status, row.status)).join('')}
                            </select>
                        </td>
                        <td><input type="text" list="listJabatanSbm" class="form-input plotting-input plotting-input--dropdown" data-pegawai-field="jabatan_sbm" value="${esc(row.jabatan_sbm || '')}" placeholder="Pilih / ketik jabatan"></td>
                        <td><input type="text" list="listJabatanSbm" class="form-input plotting-input plotting-input--dropdown" data-pegawai-field="jabatan_sbm_2" value="${esc(row.jabatan_sbm_2 || '')}" placeholder="Pilih / ketik jabatan kedua"></td>
                        <td class="pegawai-level-auto">${esc(level1)}</td>
                        <td class="pegawai-level-auto">${esc(level2)}</td>
                        <td><input type="text" inputmode="numeric" class="form-input plotting-input plotting-input--money" data-pegawai-field="target_kerma" value="${esc(formatRupiahKomaDash(row.target_kerma))}" placeholder="Rp 0,-"></td>
                        <td><input type="text" class="form-input plotting-input" data-pegawai-field="keterangan" value="${esc(row.keterangan || '')}" placeholder="Keterangan"></td>
                        <td>
                            <div class="pegawai-row-actions">
                                <button type="button" class="btn-row-save" data-pegawai-row-action="save" data-row="${rowIndex}">Simpan</button>
                                <button type="button" class="btn-row-cancel" data-pegawai-row-action="cancel" data-row="${rowIndex}">Batal</button>
                            </div>
                        </td>
                    </tr>
                `;
            }
            return `
                <tr>
                    <td class="plotting-col-no">${rowIndex + 1}</td>
                    <td class="pegawai-readonly-cell pegawai-readonly-cell--truncate" title="${esc(row.gelar_depan || '-')}">${esc(row.gelar_depan || '-')}</td>
                    <td class="pegawai-readonly-cell pegawai-readonly-cell--truncate" title="${esc(row.nama || '-')}">${esc(row.nama || '-')}</td>
                    <td class="pegawai-readonly-cell pegawai-readonly-cell--truncate" title="${esc(row.gelar_belakang || '-')}">${esc(row.gelar_belakang || '-')}</td>
                    <td class="pegawai-readonly-cell">${esc(row.peran || '-')}</td>
                    <td class="pegawai-readonly-cell pegawai-readonly-cell--truncate" title="${esc(row.jabatan_fungsional || '-')}">${esc(row.jabatan_fungsional || '-')}</td>
                    <td class="pegawai-readonly-cell pegawai-readonly-cell--truncate" title="${esc(row.kelompok_keahlian || '-')}">${esc(row.kelompok_keahlian || '-')}</td>
                    <td class="pegawai-readonly-cell">${esc(row.status || '-')}</td>
                    <td class="pegawai-readonly-cell pegawai-readonly-cell--truncate" title="${esc(row.jabatan_sbm || '-')}">${esc(row.jabatan_sbm || '-')}</td>
                    <td class="pegawai-readonly-cell pegawai-readonly-cell--truncate" title="${esc(row.jabatan_sbm_2 || '-')}">${esc(row.jabatan_sbm_2 || '-')}</td>
                    <td class="pegawai-level-auto">${esc(level1)}</td>
                    <td class="pegawai-level-auto">${esc(level2)}</td>
                    <td class="pegawai-readonly-cell pegawai-money-cell">${formatRupiahKomaDash(row.target_kerma)}</td>
                    <td class="pegawai-readonly-cell pegawai-readonly-cell--truncate" title="${esc(row.keterangan || '-')}">${esc(row.keterangan || '-')}</td>
                    <td>
                        <button type="button" class="btn-row-edit" data-pegawai-row-action="edit" data-row="${rowIndex}">Edit</button>
                    </td>
                </tr>
            `;
        }).join('');
    }

    function renderSelectPegawaiOption(value, selectedValue) {
        return `<option value="${esc(value)}" ${value === selectedValue ? 'selected' : ''}>${esc(value)}</option>`;
    }

    const urutanLevelJabatanSbm = [
        'Dekan',
        'Wakil Dekan',
        'Guru Besar',
        'Kepala Senat',
        'Sekretaris Senat',
        'Ketua Kelompok Keahlian',
        'Ketua Program Studi',
        'Kepala Pusat',
        'Kepala Laboratorium',
        'Kepala Administrasi',
        'Ketua Urusan',
        'Wakil Kepala',
        'Kepala Sub Administrasi',
        'Koordinator',
        'Asisten'
    ];

    function normalisasiNamaJabatan(value) {
        let normalized = String(value || '').replace(/\s+/g, ' ').trim();
        normalized = normalized
            .replace(/^Kepala Adminsitrasi\b/i, 'Kepala Administrasi')
            .replace(/^Kepala Sub Adminsitrasi\b/i, 'Kepala Sub Administrasi');
        if (/^Ketua Kelompok Keahlian$/i.test(normalized)) {
            return '';
        }
        if (/^Kepala Management of Technology$/i.test(normalized)) {
            return 'Kepala Laboratorium Management of Technology';
        }
        if (/^Kepala Inkubator Bisnis$/i.test(normalized)) {
            return 'Kepala Laboratorium Inkubator Bisnis';
        }
        if (/^Ketua Program Magister Administrasi Bisnis Kampus Bandung$/i.test(normalized)) {
            return 'Ketua Program Studi Magister Administrasi Bisnis Kampus Bandung';
        }
        if (/^Ketua Program Magister Administrasi Bisnis Kampus Jakarta$/i.test(normalized)) {
            return 'Ketua Program Studi Magister Administrasi Bisnis Kampus Jakarta';
        }
        if (/^Ketua Program MSM dan DSM$/i.test(normalized)) {
            return 'Ketua Program Studi MSM dan DSM';
        }
        if (/^Ketua Program Sarjana Kewirausahaan$/i.test(normalized)) {
            return 'Ketua Program Studi Sarjana Kewirausahaan';
        }
        if (/^Ketua Program Sarjana Manajemen$/i.test(normalized)) {
            return 'Ketua Program Studi Sarjana Manajemen';
        }
        return normalized;
    }

    function normalisasiLevelJabatan(value) {
        return String(value || '').replace(/\s+/g, ' ').trim()
            .replace(/^Kepala Adminsitrasi\b/i, 'Kepala Administrasi')
            .replace(/^Kepala Sub Adminsitrasi\b/i, 'Kepala Sub Administrasi');
    }

    function keyMasterJabatan(value) {
        return normalisasiNamaJabatan(value).toLowerCase();
    }

    function hasMasterLevelJabatan(key) {
        return Object.prototype.hasOwnProperty.call(masterLevelJabatanPlotting, key);
    }

    function getLevelJabatanMaster(jabatan) {
        const key = keyMasterJabatan(jabatan);
        return key ? (masterLevelJabatanPlotting[key] || '') : '';
    }

    function setLevelJabatanMaster(jabatan, level) {
        const nama = normalisasiNamaJabatan(jabatan);
        const key = nama.toLowerCase();
        if (!key) return;
        masterLevelJabatanPlotting[key] = normalisasiLevelJabatan(level);
    }

    function sinkronMasterLevelJabatanDariRows() {
        plottingKermaRows.forEach(row => {
            [
                { nama: row.jabatan_sbm, level: row.level_jabatan_1 },
                { nama: row.jabatan_sbm_2, level: row.level_jabatan_2 }
            ].forEach(item => {
                const key = keyMasterJabatan(item.nama);
                if (!key || hasMasterLevelJabatan(key)) return;
                masterLevelJabatanPlotting[key] = normalisasiLevelJabatan(item.level);
            });
        });
    }

    function rankLevelJabatan(value) {
        const teks = normalisasiLevelJabatan(value).toLowerCase();
        if (!teks) return Number.POSITIVE_INFINITY;
        const index = urutanLevelJabatanSbm.findIndex(level => {
            const normalizedLevel = level.toLowerCase();
            return teks === normalizedLevel || teks.startsWith(`${normalizedLevel} `);
        });
        return index === -1 ? Number.POSITIVE_INFINITY : index;
    }

    function rankJabatanMaster(item) {
        const rankDariLevel = rankLevelJabatan(item.level);
        if (Number.isFinite(rankDariLevel)) return rankDariLevel;
        return rankLevelJabatan(item.nama);
    }

    function ambilNilaiUnikPegawai(fields) {
        const nilaiSet = new Map();
        plottingKermaRows.forEach(row => {
            fields.forEach(field => {
                const nilai = normalisasiNamaJabatan(row[field]);
                if (!nilai) return;
                nilaiSet.set(nilai.toLowerCase(), nilai);
            });
        });
        return [...nilaiSet.values()].sort((a, b) => a.localeCompare(b, 'id', { sensitivity: 'base' }));
    }

    function daftarPilihanKelompokKeahlianPegawai() {
        const values = [
            ...kelompokKeahlianBidangDefault,
            ...plottingKermaRows.map(row => String(row.kelompok_keahlian || '').trim())
        ].filter(Boolean);
        return [...new Set(values)].sort((a, b) => a.localeCompare(b, 'id', { sensitivity: 'base' }));
    }

    function renderOptionsDatalist(datalist, values) {
        if (!datalist) return;
        datalist.innerHTML = values.map(value => `<option value="${esc(value)}"></option>`).join('');
    }

    function ambilLevelJabatanOptions() {
        const nilaiSet = new Map();
        [
            ...urutanLevelJabatanSbm,
            ...ambilNilaiUnikPegawai(['level_jabatan_1', 'level_jabatan_2']),
            ...Object.values(masterLevelJabatanPlotting)
        ].forEach(value => {
            const nilai = normalisasiLevelJabatan(value);
            if (!nilai) return;
            nilaiSet.set(nilai.toLowerCase(), nilai);
        });
        return [...nilaiSet.values()].sort((a, b) => a.localeCompare(b, 'id', { sensitivity: 'base' }));
    }

    function renderDatalistPegawai() {
        renderOptionsDatalist(listJabatanSbm, ambilNilaiUnikPegawai(['jabatan_sbm', 'jabatan_sbm_2']));
        renderOptionsDatalist(
            listKelompokKeahlian,
            daftarPilihanKelompokKeahlianPegawai()
        );
        renderOptionsDatalist(listLevelJabatan, ambilLevelJabatanOptions());
    }

    function ambilDaftarJabatanMaster() {
        const jabatanMap = new Map();
        plottingKermaRows.forEach(row => {
            [
                { nama: row.jabatan_sbm, level: row.level_jabatan_1, posisi: 'Jabatan 1' },
                { nama: row.jabatan_sbm_2, level: row.level_jabatan_2, posisi: 'Jabatan 2' }
            ].forEach(item => {
                const nama = normalisasiNamaJabatan(item.nama);
                if (!nama) return;
                const key = nama.toLowerCase();
                if (!jabatanMap.has(key)) {
                    jabatanMap.set(key, {
                        nama,
                        key,
                        level: getLevelJabatanMaster(nama)
                    });
                }
                const level = normalisasiLevelJabatan(item.level);
                if (level && !hasMasterLevelJabatan(key)) {
                    setLevelJabatanMaster(nama, level);
                    jabatanMap.get(key).level = level;
                }
            });
        });
        return [...jabatanMap.values()].sort((a, b) => {
            const rankA = rankJabatanMaster(a);
            const rankB = rankJabatanMaster(b);
            if (rankA !== rankB) return rankA - rankB;
            return a.nama.localeCompare(b.nama, 'id', { sensitivity: 'base' });
        });
    }

    function renderDaftarJabatan() {
        if (!bodyTabelJabatan) return;
        const data = ambilDaftarJabatanMaster();
        if (infoJumlahJabatan) infoJumlahJabatan.textContent = `${data.length.toLocaleString('id-ID')} jabatan`;
        if (!data.length) {
            bodyTabelJabatan.innerHTML = '<tr class="table-state-row"><td colspan="4"><div class="table-state">Belum ada jabatan yang diinput pada Daftar Pegawai.</div></td></tr>';
            return;
        }
        bodyTabelJabatan.innerHTML = data.map((item, index) => {
            const isEditing = jabatanEditKey === item.key;
            return `
                <tr class="${isEditing ? 'jabatan-row-editing' : ''}">
                    <td class="plotting-col-no">${index + 1}</td>
                    <td>
                        ${isEditing
                            ? `<input type="text" list="listJabatanSbm" class="form-input plotting-input plotting-input--dropdown" data-jabatan-name-input value="${esc(item.nama)}" placeholder="Nama jabatan">`
                            : `<strong>${esc(item.nama)}</strong>`}
                    </td>
                    <td>
                        ${isEditing
                            ? `<input type="text" list="listLevelJabatan" class="form-input plotting-input plotting-input--dropdown" data-jabatan-level-input value="${esc(item.level || '')}" placeholder="Pilih / ketik level jabatan">`
                            : `<span class="jabatan-level-readonly">${esc(item.level || '-')}</span>`}
                    </td>
                    <td>
                        ${isEditing
                            ? `<div class="pegawai-row-actions">
                                    <button type="button" class="btn-row-save" data-jabatan-row-action="save" data-jabatan-key="${esc(item.key)}" data-jabatan-nama="${esc(item.nama)}">Simpan</button>
                                    <button type="button" class="btn-row-cancel" data-jabatan-row-action="cancel" data-jabatan-key="${esc(item.key)}">Batal</button>
                                </div>`
                            : `<button type="button" class="btn-row-edit" data-jabatan-row-action="edit" data-jabatan-key="${esc(item.key)}" data-jabatan-nama="${esc(item.nama)}">Edit</button>`}
                    </td>
                </tr>
            `;
        }).join('');
    }

    function renderBatasanSwitch(field, label) {
        const aktif = Boolean(getBatasanSimulasi()[field]) && isBatasanRuleAktifTersimpan(field);
        return `
            <label class="plotting-rule-switch">
                <input type="checkbox" data-batasan-simulasi-field="${esc(field)}" ${aktif ? 'checked' : ''}>
                <span>${esc(label)}</span>
            </label>
        `;
    }

    function renderStatusToggleBatasanRule(id, label = 'aturan') {
        const aktif = isBatasanRuleAktifTersimpan(id)
            && (id !== 'kesesuaianKk' || Boolean(getBatasanSimulasi().kesesuaianKk));
        return `
            <label class="plotting-rule-switch plotting-rule-switch--status ${aktif ? 'is-on' : 'is-off'}" title="${esc(`${aktif ? 'Nonaktifkan' : 'Aktifkan'} ${label}`)}">
                <input type="checkbox" data-batasan-toggle-id="${esc(id)}" ${aktif ? 'checked' : ''}>
                <span>${aktif ? 'Aktif' : 'Nonaktif'}</span>
            </label>
        `;
    }

    function renderAksiBatasanRule(id, label = 'aturan', extraAction = '') {
        return `
            <div class="plotting-rule-actions">
                ${renderStatusToggleBatasanRule(id, label)}
                ${extraAction}
            </div>
        `;
    }

    function renderKategoriBatasanSelect(id) {
        const kategori = kategoriBatasanSimulasi(id);
        return `
            <select class="form-input plotting-input plotting-input--select plotting-rule-category" data-batasan-kategori-id="${esc(id)}" aria-label="${esc(`Kategori batasan ${id}`)}">
                <option value="wajib" ${kategori === 'wajib' ? 'selected' : ''}>Wajib</option>
                <option value="preferensi" ${kategori === 'preferensi' ? 'selected' : ''}>Preferensi</option>
            </select>
        `;
    }

    function renderBadgeBatasan(label, tipe = 'locked') {
        return `<span class="plotting-rule-badge plotting-rule-badge--${esc(tipe)}">${esc(label)}</span>`;
    }

    function renderKategoriBatasanCell(row = {}) {
        if (row.kategoriDisplay) return renderBadgeBatasan(row.kategoriDisplay, row.kategoriTipe || 'locked');
        return renderKategoriBatasanSelect(row.id);
    }

    function renderStatusBatasanTetap(label = 'Terkunci') {
        return renderBadgeBatasan(label, 'locked');
    }

    function renderBatasanRoleDosen() {
        const selected = new Set(getBatasanSimulasi().roleDosen);
        return `
            <div class="plotting-role-checks">
                ${rolePlottingKerma.map(role => `
                    <label>
                        <input type="checkbox" data-batasan-dosen-role="${esc(role)}" ${selected.has(role) ? 'checked' : ''}>
                        <span>${esc(labelJabatanPlotting(role))}</span>
                    </label>
                `).join('')}
            </div>
        `;
    }

    function renderBatasanRoleStaf() {
        const selected = new Set(getBatasanSimulasi().roleStaf);
        return `
            <div class="plotting-role-checks">
                ${rolePlottingKerma.map(role => `
                    <label>
                        <input type="checkbox" data-batasan-staf-role="${esc(role)}" ${selected.has(role) ? 'checked' : ''}>
                        <span>${esc(labelJabatanPlotting(role))}</span>
                    </label>
                `).join('')}
            </div>
        `;
    }

    function renderBatasanLevelRoleCell(rule, role) {
        const checked = rule.roles.includes(role);
        const labelRule = rule.levels[0] || rule.nama;
        return `
            <label class="plotting-level-role-toggle" title="${esc(`${labelRule} - ${titleJabatanPlotting(role)}`)}">
                <input type="checkbox" aria-label="${esc(`${labelRule} - ${titleJabatanPlotting(role)}`)}" data-batasan-level-id="${esc(rule.id)}" data-batasan-level-role="${esc(role)}" ${checked ? 'checked' : ''}>
            </label>
        `;
    }

    function renderBatasanLevelLabel(rule) {
        if (rule.custom) {
            return `
                <input type="text" class="form-input plotting-input plotting-level-rule-input" data-batasan-level-id="${esc(rule.id)}" data-batasan-level-field="levels" value="${esc(rule.levels.join('; '))}" placeholder="Tulis level jabatan">
                <small>Batasan tambahan</small>
            `;
        }
        const helper = rule.id === 'dosenTanpaLevel'
            ? 'Dosen tanpa level jabatan'
            : (rule.id === 'stafTanpaLevel' ? 'Staf tanpa level jabatan' : (rule.levels[0] || rule.nama));
        return `
            <strong>${esc(rule.nama)}</strong>
            <small>${esc(helper)}</small>
        `;
    }

    function renderBatasanHapusButton(type, id, label = 'Hapus batasan') {
        const attr = type === 'level' ? 'data-hapus-batasan-level' : 'data-hapus-batasan-umum';
        return `<button type="button" class="plotting-rule-delete-btn" ${attr}="${esc(id)}" title="${esc(label)}">Hapus</button>`;
    }

    function renderStatusBatasanUmum(rule) {
        const analisis = analisisBatasanUmum(rule);
        const kelas = analisis.aktif ? 'is-active' : (analisis.tipe === 'empty' ? 'is-empty' : 'is-note');
        return `<small class="plotting-rule-status ${kelas}">${esc(analisis.label)}</small>`;
    }

