    function bukaPreviewBuktiKasMasuk(idPembayaran = '', rencanaKey = '', context = {}) {
        let data;
        try {
            data = dataBuktiKasMasuk(idPembayaran, rencanaKey, context);
        } catch (error) {
            console.error('Data BKM tidak lengkap, gunakan konteks tombol sebagai fallback.', error);
            data = dataBuktiKasMasukFallback(idPembayaran, rencanaKey, context);
        }
        if (!data) {
            alert('Data BKM tidak ditemukan. Muat ulang tabel Pembayaran lalu coba kembali.');
            return;
        }
        const previewWindow = window.open('', '_blank');
        if (!previewWindow) {
            alert('Jendela pratinjau diblokir browser. Izinkan pop-up untuk melihat BKM.');
            return;
        }
        previewWindow.document.write(htmlBuktiKasMasuk(data));
        previewWindow.document.close();
        previewWindow.focus();
    }

    async function cetakBuktiKasMasukDariModal() {
        if (!buktiKasMasukDraft) return;
        const data = dataBuktiKasMasukDariForm();
        if (!data.tanggal_masuk) {
            setAlertBuktiKasMasuk('Tanggal pembayaran wajib diisi.', 'error');
            inputTanggalMasukBkm?.focus();
            return;
        }
        if (!data.jumlah_bkm || data.jumlah_bkm <= 0) {
            setAlertBuktiKasMasuk('Jumlah pembayaran wajib diisi dan harus lebih dari 0.', 'error');
            bkmPreviewJumlah?.focus();
            return;
        }

        const submitButton = formBuktiKasMasuk?.querySelector('button[type="submit"]');
        const submitLabel = submitButton?.textContent || 'Simpan';
        if (submitButton) {
            submitButton.disabled = true;
            submitButton.textContent = 'Menyimpan...';
        }
        try {
            const response = await fetch('/api/bukti-kas-masuk', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    rencana_key: data.rencana_key,
                    kode_file: data.kode_file,
                    rencana_tahap: data.tahap,
                    rencana_tanggal: data.rencana_tanggal,
                    rencana_nominal: data.rencana_nominal,
                    nomor_bkm: data.nomor_bkm,
                    nomor_bkm_manual: data.nomor_bkm_manual,
                    tanggal_masuk: data.tanggal_masuk,
                    jumlah_bkm: data.jumlah_bkm,
                    nama_bank: data.nama_bank,
                    no_rekening: data.no_rekening,
                    nama_rekening: data.nama_rekening,
                    nama_unit: data.nama_unit,
                    no_bukti: data.no_bukti,
                    bkm_uraian: data.uraian
                })
            });
            const payload = await response.json();
            if (!response.ok) throw new Error(payload.pesan || 'Gagal menyimpan BKM.');

            const savedData = {
                ...data,
                nomor_bkm: payload.data?.bkm_nomor || data.nomor_bkm,
                no_rekening: payload.data?.bkm_no_rekening || data.no_rekening,
                bkm_sudah_disimpan: true,
                pembayaran_tercatat: true,
                bkm_tanggal: data.tanggal_masuk,
                bkm_jumlah: data.jumlah_bkm
            };
            buktiKasMasukDraftByPayment.set(
                data.draft_key || kunciDraftBuktiKasMasuk(data.id_pembayaran, data.rencana_key),
                savedData
            );
            setAlertBuktiKasMasuk('BKM berhasil disimpan. Status pembayaran sudah diperbarui.', 'success');

            // Refresh the payment table before printing so the Admin date,
            // amount, and status are immediately backed by persisted data.
            await AmbilDataRealisasiDanRender();

            const printWindow = window.open('', '_blank');
            if (!printWindow) {
                setAlertBuktiKasMasuk('BKM tersimpan, tetapi jendela cetak diblokir browser. Izinkan pop-up untuk mencetak.', 'error');
                return;
            }
            printWindow.document.write(htmlBuktiKasMasuk(savedData));
            printWindow.document.close();
            printWindow.focus();
            setTimeout(() => printWindow.print(), 250);
        } catch (error) {
            setAlertBuktiKasMasuk(error.message || 'Gagal menyimpan BKM.', 'error');
        } finally {
            if (submitButton) {
                submitButton.disabled = false;
                submitButton.textContent = submitLabel;
            }
        }
    }

    function cetakBuktiKasMasuk(idPembayaran = '', rencanaKey = '', context = {}) {
        bukaModalBuktiKasMasuk(idPembayaran, rencanaKey, context);
    }

    function cetakBuktiKasMasukLegacy(idPembayaran = '', rencanaKey = '') {
        const pembayaran = allPembayaranData.find(row => String(row.id_pembayaran || '') === String(idPembayaran || ''));
        if (!pembayaran) {
            alert('Pembayaran belum ditemukan. Muat ulang data lalu coba kembali.');
            return;
        }
        const term = allRencanaTerminData.find(row => String(row.rencana_key || '') === String(rencanaKey || '')) || {};
        const printWindow = window.open('', '_blank');
        if (!printWindow) {
            alert('Jendela cetak diblokir browser. Izinkan pop-up untuk mencetak Bukti Kas Masuk.');
            return;
        }
        const nominalBruto = nominalBrutoPembayaranTercatat(pembayaran);
        const nominalNetto = nominalNettoPembayaranTercatat(pembayaran);
        printWindow.document.write(`
            <!doctype html>
            <html lang="id">
            <head>
                <meta charset="utf-8">
                <title>Bukti Kas Masuk - ${esc(pembayaran.kode_file || '')}</title>
                <style>
                    * { box-sizing: border-box; }
                    body { margin: 0; padding: 36px; color: #172033; font: 14px Arial, sans-serif; }
                    main { max-width: 760px; margin: 0 auto; }
                    h1 { margin: 0; text-align: center; font-size: 22px; letter-spacing: .04em; }
                    .subtitle { margin: 8px 0 28px; text-align: center; color: #526078; }
                    table { width: 100%; border-collapse: collapse; }
                    th, td { padding: 10px 12px; border: 1px solid #cbd5e1; vertical-align: top; }
                    th { width: 34%; background: #eff6ff; text-align: left; }
                    .nominal { font-weight: 700; text-align: right; }
                    .note { margin-top: 28px; color: #526078; font-size: 12px; }
                    @media print { body { padding: 0; } }
                </style>
            </head>
            <body>
                <main>
                    <h1>BUKTI KAS MASUK</h1>
                    <p class="subtitle">Pencatatan pembayaran mitra</p>
                    <table>
                        <tr><th>Kode File</th><td>${esc(pembayaran.kode_file || '-')}</td></tr>
                        <tr><th>Mitra</th><td>${esc(pembayaran.nama_mitra || '-')}</td></tr>
                        <tr><th>Judul PKS</th><td>${esc(pembayaran.judul_pks || term.judul_pks || '-')}</td></tr>
                        <tr><th>Tahap Pembayaran</th><td>${esc(pembayaran.rencana_tahap || term.tahap || '-')}</td></tr>
                        <tr><th>Tgl. Rencana Pembayaran</th><td>${esc(pembayaran.tanggal_rencana || (term.tanggal_diterima || '-'))}</td></tr>
                        <tr><th>Tgl. Pembayaran</th><td>${esc(formatTanggalPembayaranAdmin(pembayaran) || '-')}</td></tr>
                        <tr><th>Jumlah Pembayaran</th><td class="nominal">${esc(formatRupiahKomaDash(nominalBruto))}</td></tr>
                        <tr><th>Realisasi Penerimaan (80%)</th><td class="nominal">${esc(formatRupiahKomaDash(nominalNetto))}</td></tr>
                    </table>
                    <p class="note">Dokumen ini dibuat berdasarkan pembayaran yang telah dicatat oleh admin pada sistem.</p>
                </main>
            </body>
            </html>
        `);
        printWindow.document.close();
        printWindow.focus();
        setTimeout(() => printWindow.print(), 250);
    }

    async function muatInvoicePembayaran() {
        const res = await fetch(`/api/invoice-pembayaran?_=${Date.now()}`, { cache: 'no-store' });
        const payload = await res.json();
        if (!res.ok) throw new Error(payload.pesan || 'Gagal memuat invoice.');
        allInvoicePembayaranData = payload.data || [];
        return payload;
    }

    function setAlertInvoice(message = '', type = 'error') {
        if (!formAlertInvoice) return;
        if (!message) {
            formAlertInvoice.style.display = 'none';
            formAlertInvoice.textContent = '';
            return;
        }
        formAlertInvoice.className = `form-alert form-alert--${type}`;
        formAlertInvoice.textContent = message;
        formAlertInvoice.style.display = 'inline-block';
    }

    function setFieldValue(el, value = '') {
        if (el) el.value = value || '';
    }

    function setModeInvoiceTersimpan(sudahTersimpan = false) {
        if (btnOkInvoice) btnOkInvoice.style.display = sudahTersimpan ? 'none' : '';
        if (btnPrintInvoice) btnPrintInvoice.style.display = sudahTersimpan ? '' : 'none';
        if (inputNomorInvoice) inputNomorInvoice.readOnly = sudahTersimpan;
        if (inputTanggalInvoice) inputTanggalInvoice.readOnly = sudahTersimpan;
    }

    function isiModalInvoice(data = {}) {
        setFieldValue(invoicePreviewKodeFile, data.kode_file);
        setFieldValue(invoicePreviewMitra, data.nama_mitra);
        setFieldValue(invoicePreviewJudulPks, data.judul_pks);
        setFieldValue(invoicePreviewTahap, data.rencana_tahap);
        setFieldValue(invoicePreviewJatuhTempo, data.rencana_tanggal);
        setFieldValue(invoicePreviewNominal, data.rencana_nominal_display);
        setFieldValue(invoicePreviewKontrakMitra, data.no_kontrak_mitra);
        setFieldValue(invoicePreviewKontrakInstitusi, data.no_kontrak_institusi);
        setFieldValue(invoicePreviewAlamat, [data.alamat_1, data.alamat_2].filter(Boolean).join('\n'));
        setFieldValue(invoicePreviewTerbilang, data.terbilang);
        setFieldValue(inputNomorInvoice, data.nomor_invoice);
        setFieldValue(inputTanggalInvoice, data.tanggal_invoice_input || todayInputDate());
    }

    function tutupModalInvoice() {
        if (!modalInvoicePembayaran) return;
        modalInvoicePembayaran.style.display = 'none';
        invoicePembayaranPreview = null;
        invoicePembayaranTersimpan = null;
        setAlertInvoice('');
        formInvoicePembayaran?.reset();
        setModeInvoiceTersimpan(false);
    }

    async function bukaModalInvoiceDariKey(rencanaKey = '', triggerBtn = null) {
        const key = String(rencanaKey || '').trim();
        if (!key) return;
        const item = allRencanaTerminData.find(row => String(row.rencana_key || '').trim() === key);
        if (!item) {
            alert('Rencana pembayaran tidak ditemukan.');
            return;
        }

        const originalText = triggerBtn?.textContent;
        if (triggerBtn) {
            triggerBtn.disabled = true;
            triggerBtn.textContent = 'Memuat...';
        }
        try {
            const params = new URLSearchParams({
                rencana_key: key,
                kode_file: item.kode_file || '',
                rencana_tahap: item.tahap || '',
                rencana_tanggal: item.tanggal_input || '',
                rencana_nominal: String(nominalRencanaTerm(item) || '')
            });
            const res = await fetch(`/api/invoice-pembayaran/preview?${params.toString()}`, { cache: 'no-store' });
            const payload = await res.json();
            if (!res.ok) throw new Error(payload.pesan || 'Gagal membuat preview invoice.');
            invoicePembayaranPreview = payload.data || {};
            invoicePembayaranTersimpan = payload.sudah_dibuat ? payload.data || null : null;
            isiModalInvoice(invoicePembayaranPreview);
            setModeInvoiceTersimpan(Boolean(invoicePembayaranTersimpan));
            setAlertInvoice(
                payload.sudah_dibuat
                    ? 'Invoice sudah tersimpan. BKM tersedia pada kolom Tgl. Pembayaran (Admin).'
                    : 'Periksa data invoice, lalu klik Simpan untuk menyimpannya ke database.',
                'success'
            );
            if (modalInvoicePembayaran) modalInvoicePembayaran.style.display = 'flex';
            requestAnimationFrame(() => inputNomorInvoice?.focus());
        } catch (err) {
            alert(err.message || 'Gagal membuka modal invoice.');
        } finally {
            if (triggerBtn) {
                triggerBtn.disabled = false;
                triggerBtn.textContent = originalText || 'Buat Invoice';
            }
        }
    }

    async function buatInvoiceTerminDariKey(rencanaKey = '', triggerBtn = null) {
        bukaModalInvoiceDariKey(rencanaKey, triggerBtn);
    }

    async function simpanInvoiceDariModal() {
        const key = String(invoicePembayaranPreview?.rencana_key || '').trim();
        if (!key) {
            setAlertInvoice('Rencana pembayaran belum dipilih.');
            return;
        }
        const nomorInvoice = String(inputNomorInvoice?.value || '').trim();
        const tanggalInvoice = String(inputTanggalInvoice?.value || '').trim();
        if (!nomorInvoice) {
            setAlertInvoice('Nomor invoice wajib diisi.');
            inputNomorInvoice?.focus();
            return;
        }
        if (!tanggalInvoice) {
            setAlertInvoice('Tanggal invoice wajib diisi.');
            inputTanggalInvoice?.focus();
            return;
        }

        const originalText = btnOkInvoice?.textContent;
        if (btnOkInvoice) {
            btnOkInvoice.disabled = true;
            btnOkInvoice.textContent = 'Menyimpan...';
        }
        try {
            const res = await fetch('/api/invoice-pembayaran', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    rencana_key: key,
                    kode_file: invoicePembayaranPreview.kode_file || '',
                    rencana_tahap: invoicePembayaranPreview.rencana_tahap || '',
                    rencana_tanggal: invoicePembayaranPreview.rencana_tanggal_input || '',
                    rencana_nominal: invoicePembayaranPreview.rencana_nominal || 0,
                    nomor_invoice: nomorInvoice,
                    tanggal_invoice: tanggalInvoice
                })
            });
            const payload = await res.json();
            if (!res.ok) throw new Error(payload.pesan || 'Gagal menyimpan invoice.');
            invoicePembayaranTersimpan = payload.data || {};
            await muatInvoicePembayaran();
            renderDetailRencanaPendapatan();
            setModeInvoiceTersimpan(true);
            setAlertInvoice('Invoice berhasil disimpan. BKM sekarang tersedia pada kolom Tgl. Pembayaran (Admin).', 'success');
        } catch (err) {
            setAlertInvoice(err.message || 'Gagal menyimpan invoice.');
        } finally {
            if (btnOkInvoice) {
                btnOkInvoice.disabled = false;
                btnOkInvoice.textContent = originalText || 'Simpan';
            }
        }
    }

    function bukaUrlInvoice(url = '', mode = 'download') {
        if (!url) {
            setAlertInvoice('File invoice belum tersedia.');
            return;
        }
        if (mode === 'print') {
            window.open(url, '_blank', 'noopener,noreferrer');
            return;
        }
        window.location.href = url;
    }

    function nilaiKontrakProgram(program = {}) {
        return Number(program.nilai_kontrak_raw) || Number(program.nilai_kontrak) || parseNominalRupiah(program.nilai_kontrak);
    }

    function updateRingkasanRencanaAnggaran(kodeFile, data = []) {
        const program = programDariKodeFile(kodeFile);
        if (!kodeFile) {
            setText(nilaiKontrakRencanaAnggaran, 'Rp 0,-');
            setText(saldoProyektifRencanaAnggaran, 'Rp 0,-');
            setText(saldoDefinitifRencanaAnggaran, 'Rp 0,-');
            setText(infoKontrakRencanaAnggaran, 'Pilih kode file untuk melihat data.');
            return;
        }
        if (!program) {
            setText(nilaiKontrakRencanaAnggaran, 'Rp 0,-');
            setText(saldoProyektifRencanaAnggaran, 'Rp 0,-');
            setText(saldoDefinitifRencanaAnggaran, 'Rp 0,-');
            setText(infoKontrakRencanaAnggaran, 'Kode file tidak ditemukan pada daftar Kerma.');
            return;
        }
        const saldo = data.reduce((acc, item) => {
            const pemasukan = Number(item.pemasukan) || 0;
            const ri = Number(item.ri) || 0;
            const realisasiRi = Number(item.pengeluaran_ri) || 0;
            acc.proyektif += pemasukan - ri;
            acc.definitif += pemasukan - realisasiRi;
            return acc;
        }, { proyektif: 0, definitif: 0 });
        setText(nilaiKontrakRencanaAnggaran, formatRupiahKomaDash(totalPenerimaanKodeFile(kodeFile)));
        setText(saldoProyektifRencanaAnggaran, formatRupiahKomaDash(saldo.proyektif));
        setText(saldoDefinitifRencanaAnggaran, formatRupiahKomaDash(saldo.definitif));
        const jumlahRows = data.length.toLocaleString('id-ID');
        setText(infoKontrakRencanaAnggaran, `${program.nama_mitra || '-'} · ${jumlahRows} baris transaksi`);
    }

    function tanggalSortRencanaAnggaran(row = {}) {
        const tanggal = parseInputDate(row.tanggal_sort_input || row.tanggal_ri_input || row.tanggal_realisasi_input || row.tanggal_input);
        if (tanggal) return tanggal.getTime();
        return row.sumber_ledger === 'penerimaan' ? 0 : Number.MAX_SAFE_INTEGER;
    }

    function barisPenerimaanUntukRealisasiRi(row = {}, index = 0) {
        const tanggalInput = row.tanggal_realisasi_input || row.tanggal_input || '';
        return {
            sumber_ledger: 'penerimaan',
            urutan_sumber: 0,
            kode_file: row.kode_file || '',
            judul_kerma: row.judul_pks || '',
            mitra: row.nama_mitra || '',
            tanggal_ri: row.tanggal_realisasi || row.tanggal || formatTanggalTermin(tanggalInput),
            tanggal_sort_input: tanggalInput,
            uraian: row.keterangan || row.rencana_tahap || `Realisasi Penerimaan ${index + 1}`,
            pemasukan: nominalNettoPembayaranTercatat(row),
            ri: 0,
            pengeluaran_ri: 0
        };
    }

    function barisRiUntukRealisasiRi(row = {}) {
        const tanggalInput = row.tanggal_ri_input || row.tgl_invoice_input || '';
        return {
            ...row,
            sumber_ledger: 'ri',
            urutan_sumber: 1,
            pemasukan: 0,
            ri: Number(row.ri) || 0,
            pengeluaran_ri: 0,
            realisasi_ri: 0,
            tgl_invoice: row.tanggal_ri || row.tgl_invoice || formatTanggalTermin(tanggalInput),
            tgl_invoice_input: tanggalInput,
            tanggal_sort_input: tanggalInput
        };
    }

    function barisRealisasiRiManualUntukLedger(row = {}) {
        const realisasiRi = Number(row.pengeluaran_ri) || Number(row.realisasi_ri) || 0;
        const tanggalInput = row.tanggal_realisasi_ri_input || row.tgl_invoice_input || row.tanggal_ri_input || '';
        return {
            ...row,
            sumber_ledger: 'realisasi_ri',
            urutan_sumber: 2,
            id_rencana_anggaran: row.id_rencana_anggaran ? `realisasi-ri-${row.id_rencana_anggaran}` : '',
            pemasukan: 0,
            ri: 0,
            pengeluaran_ri: realisasiRi,
            realisasi_ri: realisasiRi,
            tanggal_ri: row.tanggal_realisasi_ri || row.tgl_invoice || row.tanggal_ri || formatTanggalTermin(tanggalInput),
            tgl_invoice: row.tanggal_realisasi_ri || row.tgl_invoice || row.tanggal_ri || formatTanggalTermin(tanggalInput),
            tgl_invoice_input: tanggalInput,
            tanggal_sort_input: tanggalInput
        };
    }

    function barisRealisasiAnggaranUntukRi(row = {}) {
        const nominal = Number(row.nominal) || 0;
        return {
            sumber_ledger: 'realisasi_anggaran',
            urutan_sumber: 3,
            id_rencana_anggaran: row.id_realisasi ? `realisasi-${row.id_realisasi}` : '',
            id_realisasi: row.id_realisasi || '',
            kode_file: row.kode_file || '',
            judul_kerma: row.judul_pks || '',
            mitra: row.nama_mitra || '',
            tanggal_ri: row.tanggal || formatTanggalTermin(row.tanggal_input),
            tanggal_ri_input: row.tanggal_input || '',
            tgl_invoice: row.tanggal || formatTanggalTermin(row.tanggal_input),
            tgl_invoice_input: row.tanggal_input || '',
            tanggal_sort_input: row.tanggal_input || '',
            no_invoice: '',
            uraian: row.keterangan || row.kategori || 'Realisasi Anggaran',
            kategori_belanja: row.kategori || '',
            ri: 0,
            pengeluaran_ri: nominal,
            realisasi_ri: nominal,
            is_realisasi_anggaran: true
        };
    }

    function barisRiOtomatisDariRealisasi(row = {}, nominal = 0) {
        const tanggalInput = tanggalInputRiInvoice(row);
        const labelRealisasi = row.uraian || row.kategori_belanja || 'Realisasi RI';
        return {
            ...row,
            sumber_ledger: 'ri_auto',
            urutan_sumber: 1.5,
            id_rencana_anggaran: `ri-auto-${row.id_rencana_anggaran || row.id_realisasi || `${row.kode_file || 'kode'}-${tanggalInput}-${labelRealisasi}`}`,
            pemasukan: 0,
            ri: Number(nominal) || 0,
            pengeluaran_ri: 0,
            realisasi_ri: 0,
            no_invoice: row.no_invoice || row.nomor_invoice || row.invoice || '',
            uraian: `RI - ${labelRealisasi}`,
            tanggal_ri: row.tanggal_ri || row.tgl_invoice || formatTanggalTermin(tanggalInput),
            tgl_invoice: row.tgl_invoice || row.tanggal_ri || formatTanggalTermin(tanggalInput),
            tgl_invoice_input: tanggalInput,
            tanggal_sort_input: tanggalInput,
            is_ri_auto: true
        };
    }

    function urutTransaksiRi(a, b) {
        const tA = tanggalSortRencanaAnggaran(a);
        const tB = tanggalSortRencanaAnggaran(b);
        if (tA !== tB) return tA - tB;
        if ((a.urutan_sumber || 0) !== (b.urutan_sumber || 0)) return (a.urutan_sumber || 0) - (b.urutan_sumber || 0);
        return String(a.uraian || '').localeCompare(String(b.uraian || ''), 'id', { numeric: true });
    }

    function rowsRiLedger(kodeFile) {
        const kode = String(kodeFile || '').trim();
        if (!kode) return [];
        const riRows = allRencanaAnggaranData
            .filter(row => String(row.kode_file || '').trim() === kode)
            .filter(row => (Number(row.ri) || 0) > 0)
            .map(barisRiUntukRealisasiRi);
        const realisasiRiManualRows = allRencanaAnggaranData
            .filter(row => String(row.kode_file || '').trim() === kode)
            .filter(row => (Number(row.pengeluaran_ri) || Number(row.realisasi_ri) || 0) > 0)
            .map(barisRealisasiRiManualUntukLedger);

        return [...riRows, ...realisasiRiManualRows].sort(urutTransaksiRi);
    }

    function gabungDataRealisasiRi(kodeFile) {
        const kode = String(kodeFile || '').trim();
        if (!kode) return [];
        const penerimaanRows = allPembayaranData
            .filter(row => String(row.kode_file || '').trim() === kode)
            .map(barisPenerimaanUntukRealisasiRi);
        return [...penerimaanRows, ...rowsRiLedger(kode)].sort(urutTransaksiRi);
    }

    function nilaiKolomRi(row = {}, fieldNames = []) {
        for (const field of fieldNames) {
            const raw = row[field];
            if (raw == null || raw === '') continue;
            if (String(raw).trim() === '-') continue;
            const parsed = parseNominalRupiah(raw);
            if (Number.isFinite(parsed)) return parsed;
        }
        return 0;
    }

    function tanggalInputRiInvoice(row = {}) {
        return row.tgl_invoice_input || row.tanggal_invoice_input || row.tanggal_ri_input || row.tanggal_sort_input || '';
    }

    function tanggalDisplayRiInvoice(row = {}) {
        return row.tgl_invoice || row.tanggal_invoice || row.tanggal_ri || formatTanggalTermin(tanggalInputRiInvoice(row));
    }

    function nomorInvoiceRi(row = {}) {
        const nomor = row.no_invoice || row.nomor_invoice || row.invoice || '-';
        return String(nomor).trim().toUpperCase() === 'RAB' ? 'RKA Kerma' : nomor;
    }

    function opsiKategoriBelanjaRi(selected = '') {
        const aktif = String(selected || '').trim();
        return '<option value="">Pilih kategori</option>' + kategoriBelanjaOptions.map(kategori => `
            <option value="${esc(kategori)}"${aktif === kategori ? ' selected' : ''}>${esc(kategori)}</option>
        `).join('');
    }

    function tanggalMasukSaldoInput(rowTanggal, sampaiInput, hitungTanpaTanggal = true) {
        if (!sampaiInput) return true;
        const batas = parseInputDate(sampaiInput);
        if (!batas) return true;
        const tanggal = parseInputDate(rowTanggal);
        if (!tanggal) return hitungTanpaTanggal;
        return tanggal <= batas;
    }

    function totalPenerimaanKodeFile(kodeFile, sampaiInput = '') {
        const kode = String(kodeFile || '').trim();
        if (!kode) return 0;
        return allPembayaranData
            .filter(row => String(row.kode_file || '').trim() === kode)
            .filter(row => tanggalMasukSaldoInput(row.tanggal_realisasi_input || row.tanggal_input, sampaiInput, false))
            .reduce((sum, row) => sum + nominalNettoPembayaranTercatat(row), 0);
    }

    function totalRiRencanaKodeFile(kodeFile, sampaiInput = '') {
        const kode = String(kodeFile || '').trim();
        if (!kode) return 0;
        return rowsRiLedger(kode)
            .filter(row => row.sumber_ledger === 'ri' || row.sumber_ledger === 'ri_auto')
            .filter(row => tanggalMasukSaldoInput(tanggalInputRiInvoice(row), sampaiInput, true))
            .reduce((sum, row) => sum + (Number(row.ri) || 0), 0);
    }

    function totalRiDefinitifKodeFile(kodeFile, sampaiInput = '') {
        const kode = String(kodeFile || '').trim();
        if (!kode) return 0;
        return rowsRiLedger(kode)
            .filter(row => row.sumber_ledger !== 'ri' && row.sumber_ledger !== 'ri_auto')
            .filter(row => tanggalMasukSaldoInput(tanggalInputRiInvoice(row), sampaiInput, true))
            .reduce((sum, row) => sum + (Number(row.pengeluaran_ri) || Number(row.realisasi_ri) || 0), 0);
    }

    function saldoRiProyektifTersediaKodeFile(kodeFile, sampaiInput = '') {
        return totalPenerimaanKodeFile(kodeFile, sampaiInput) - totalRiRencanaKodeFile(kodeFile, sampaiInput);
    }

    function saldoRiDefinitifTersediaKodeFile(kodeFile, sampaiInput = '') {
        return totalPenerimaanKodeFile(kodeFile, sampaiInput) - totalRiDefinitifKodeFile(kodeFile, sampaiInput);
    }

    function sisaRiDapatDirealisasikanKodeFile(kodeFile, sampaiInput = '') {
        return totalRiRencanaKodeFile(kodeFile, sampaiInput) - totalRiDefinitifKodeFile(kodeFile, sampaiInput);
    }

    function saldoProyektifKodeFile(kodeFile) {
        return sisaRiDapatDirealisasikanKodeFile(kodeFile);
    }

    function updateRingkasanRealisasiRiInvoice(kodeFile, rows = []) {
        const program = programDariKodeFile(kodeFile);
        if (!kodeFile) {
            setText(nilaiKontrakRealisasiRi, 'Rp 0,-');
            setText(saldoDefinitifRealisasiRi, 'Rp 0,-');
            setText(infoKontrakRealisasiRi, 'Pilih kode file untuk melihat data.');
            return;
        }
        if (!program) {
            setText(nilaiKontrakRealisasiRi, 'Rp 0,-');
            setText(saldoDefinitifRealisasiRi, 'Rp 0,-');
            setText(infoKontrakRealisasiRi, 'Kode file tidak ditemukan pada daftar Kerma.');
            return;
        }
        setText(nilaiKontrakRealisasiRi, formatRupiahKomaDash(totalRiRencanaKodeFile(kodeFile)));
        setText(saldoDefinitifRealisasiRi, formatRupiahKomaDash(saldoProyektifKodeFile(kodeFile)));
        setText(infoKontrakRealisasiRi, `${program.nama_mitra || '-'} · ${rows.length.toLocaleString('id-ID')} baris RI`);
    }

    function angkaPaguAnggaran(value) {
        const angka = Number(value);
        if (!Number.isFinite(angka)) return 0;
        return Math.max(0, Math.round(angka));
    }

    function punyaNilaiPaguAnggaran(value) {
        if (value === null || value === undefined || value === '') return false;
        return Number.isFinite(Number(value));
    }

    function totalPaguRow(row = {}) {
        return angkaPaguAnggaran(row.pagu_pegawai)
            + angkaPaguAnggaran(row.pagu_barang)
            + angkaPaguAnggaran(row.pagu_jasa)
            + angkaPaguAnggaran(row.pagu_modal);
    }

    function sisaPenerimaanPaguRow(row = {}) {
        if (keuanganKodeFileDitutup(row.kode_file, row.id_program)) return 0;
        return angkaPaguAnggaran(row.realisasi_penerimaan) - totalPaguRow(row);
    }

    function totalRkaTerkunciPaguRow(row = {}) {
        return angkaPaguAnggaran(row.rka_terkunci_pegawai)
            + angkaPaguAnggaran(row.rka_terkunci_barang)
            + angkaPaguAnggaran(row.rka_terkunci_jasa)
            + angkaPaguAnggaran(row.rka_terkunci_modal);
    }

    function lengkapiKunciPaguRow(row = {}, source = {}) {
        row.status_alokasi = source.status_alokasi || row.status_alokasi || statusAlokasiKodeFile(row.kode_file, row.id_program);
        row.sisa_pagu_total = Object.prototype.hasOwnProperty.call(source, 'sisa_pagu_total')
            ? source.sisa_pagu_total
            : row.sisa_pagu_total ?? null;
        row.rka_terkunci_pegawai = angkaPaguAnggaran(source.rka_terkunci_pegawai);
        row.rka_terkunci_barang = angkaPaguAnggaran(source.rka_terkunci_barang);
        row.rka_terkunci_jasa = angkaPaguAnggaran(source.rka_terkunci_jasa);
        row.rka_terkunci_modal = angkaPaguAnggaran(source.rka_terkunci_modal);
        row.total_rka_terkunci = totalRkaTerkunciPaguRow(row);
        if (keuanganKodeFileDitutup(row.kode_file, row.id_program)) {
            row.sisa_pagu_pegawai = 0;
            row.sisa_pagu_barang = 0;
            row.sisa_pagu_jasa = 0;
            row.sisa_pagu_modal = 0;
            row.sisa_pagu = 0;
            return row;
        }
        row.sisa_pagu_pegawai = angkaPaguAnggaran(row.pagu_pegawai) - row.rka_terkunci_pegawai;
        row.sisa_pagu_barang = angkaPaguAnggaran(row.pagu_barang) - row.rka_terkunci_barang;
        row.sisa_pagu_jasa = angkaPaguAnggaran(row.pagu_jasa) - row.rka_terkunci_jasa;
        row.sisa_pagu_modal = angkaPaguAnggaran(row.pagu_modal) - row.rka_terkunci_modal;
        row.sisa_pagu = punyaNilaiPaguAnggaran(row.sisa_pagu_total)
            ? angkaPaguAnggaran(row.sisa_pagu_total)
            : totalPaguRow(row) - row.total_rka_terkunci;
        return row;
    }

    function angkaSaldoPagu(value) {
        const angka = parseNominalRupiah(value);
        return Number.isFinite(angka) ? Math.round(angka) : 0;
    }

    function nilaiPaguKategoriTampil(row = {}, field = '') {
        if (modeTampilanPagu === 'sisa' && keuanganKodeFileDitutup(row.kode_file, row.id_program)) return 0;
        if (modeTampilanPagu !== 'sisa') return angkaPaguAnggaran(row[field]);
        const sisaFieldByPaguField = {
            pagu_pegawai: 'sisa_pagu_pegawai',
            pagu_barang: 'sisa_pagu_barang',
            pagu_jasa: 'sisa_pagu_jasa',
            pagu_modal: 'sisa_pagu_modal'
        };
        return angkaSaldoPagu(row[sisaFieldByPaguField[field]]);
    }

    function totalPaguTampilRow(row = {}) {
        if (modeTampilanPagu !== 'sisa') return totalPaguRow(row);
        if (keuanganKodeFileDitutup(row.kode_file, row.id_program)) return 0;
        return angkaSaldoPagu(row.sisa_pagu);
    }

    function sinkronkanHeaderModePagu() {
        const tampilSisa = modeTampilanPagu === 'sisa';
        btnModePagu?.classList.toggle('active', !tampilSisa);
        btnModeSisaPagu?.classList.toggle('active', tampilSisa);
        btnModePagu?.setAttribute('aria-pressed', String(!tampilSisa));
        btnModeSisaPagu?.setAttribute('aria-pressed', String(tampilSisa));
        setText(paguHeaderPegawai, tampilSisa ? 'Sisa Pegawai' : 'PAGU Pegawai');
        setText(paguHeaderBarang, tampilSisa ? 'Sisa Barang' : 'PAGU Barang');
        setText(paguHeaderJasa, tampilSisa ? 'Sisa Jasa' : 'PAGU Jasa');
        setText(paguHeaderModal, tampilSisa ? 'Sisa Modal' : 'PAGU Modal');
        setText(paguHeaderTotal, tampilSisa ? 'Total Sisa PAGU' : 'Total PAGU');
    }

    function setModeTampilanPagu(mode = 'pagu', options = {}) {
        modeTampilanPagu = mode === 'sisa' ? 'sisa' : 'pagu';
        sinkronkanHeaderModePagu();
        if (options.render !== false) renderTabelPaguAnggaran();
    }

    function semuaDataPagu() {
        const savedByKode = new Map(allPaguAnggaranData
            .map(row => [String(row.kode_file || '').trim(), row])
            .filter(([kode]) => Boolean(kode)));
        const rowsByKode = new Map();

        allData.forEach(program => {
            const kode = String(program.kode_file || '').trim();
            if (!kode || rowsByKode.has(kode)) return;
            const saved = savedByKode.get(kode) || {};
            const realisasiPenerimaan = totalPenerimaanKodeFile(kode) || angkaPaguAnggaran(saved.realisasi_penerimaan);
            const row = {
                id_pagu: saved.id_pagu || '',
                id_program: program.id_program || saved.id_program || '',
                kode_file: kode,
                nama_mitra: program.nama_mitra || saved.nama_mitra || '',
                judul_pks: program.judul_pks || saved.judul_pks || '',
                status_alokasi: saved.status_alokasi || program.status_alokasi || statusAlokasiKodeFile(kode, program.id_program || saved.id_program),
                realisasi_penerimaan: realisasiPenerimaan,
                pagu_pegawai: angkaPaguAnggaran(saved.pagu_pegawai),
                pagu_barang: angkaPaguAnggaran(saved.pagu_barang),
                pagu_jasa: angkaPaguAnggaran(saved.pagu_jasa),
                pagu_modal: angkaPaguAnggaran(saved.pagu_modal),
                sisa_pagu_total: saved.sisa_pagu_total ?? null
            };
            row.total_pagu = totalPaguRow(row);
            lengkapiKunciPaguRow(row, saved);
            rowsByKode.set(kode, row);
        });

        allPaguAnggaranData.forEach(saved => {
            const kode = String(saved.kode_file || '').trim();
            if (!kode || rowsByKode.has(kode)) return;
            const program = programDariKodeFile(kode) || {};
            const realisasiPenerimaan = totalPenerimaanKodeFile(kode) || angkaPaguAnggaran(saved.realisasi_penerimaan);
            const row = {
                id_pagu: saved.id_pagu || '',
                id_program: saved.id_program || program.id_program || '',
                kode_file: kode,
                nama_mitra: saved.nama_mitra || program.nama_mitra || '',
                judul_pks: saved.judul_pks || program.judul_pks || '',
                status_alokasi: saved.status_alokasi || program.status_alokasi || statusAlokasiKodeFile(kode, saved.id_program || program.id_program),
                realisasi_penerimaan: realisasiPenerimaan,
                pagu_pegawai: angkaPaguAnggaran(saved.pagu_pegawai),
                pagu_barang: angkaPaguAnggaran(saved.pagu_barang),
                pagu_jasa: angkaPaguAnggaran(saved.pagu_jasa),
                pagu_modal: angkaPaguAnggaran(saved.pagu_modal),
                sisa_pagu_total: saved.sisa_pagu_total ?? null
            };
            row.total_pagu = totalPaguRow(row);
            lengkapiKunciPaguRow(row, saved);
            rowsByKode.set(kode, row);
        });

        return [...rowsByKode.values()].sort(urutKodeFileTerbaru);
    }

    function dataPaguTampil() {
        const kodeAktif = tabPaguAnggaran?.classList.contains('active') ? normalisasiKodeFileSaldo(kodeFilePaguAktif()) : '';
        return semuaDataPagu().filter(row => !kodeAktif || String(row.kode_file || '').trim() === kodeAktif);
    }

    function dataPaguUntukFilter(data = dataPaguTampil()) {
        return data.map((row, index) => {
            const kode = String(row.kode_file || '').trim();
            const statusAlokasi = row.status_alokasi || statusAlokasiKodeFile(kode, row.id_program);
            const paguPegawai = nilaiPaguKategoriTampil(row, 'pagu_pegawai');
            const paguBarang = nilaiPaguKategoriTampil(row, 'pagu_barang');
            const paguJasa = nilaiPaguKategoriTampil(row, 'pagu_jasa');
            const paguModal = nilaiPaguKategoriTampil(row, 'pagu_modal');
            const totalPagu = totalPaguTampilRow(row);
            const sisaPenerimaan = sisaPenerimaanPaguRow(row);
            return {
                ...row,
                no: index + 1,
                status_alokasi: statusAlokasi,
                realisasi_penerimaan_display: formatRupiahKomaDash(row.realisasi_penerimaan || 0),
                pagu_pegawai_tampil: formatRupiahKomaDash(paguPegawai),
                pagu_barang_tampil: formatRupiahKomaDash(paguBarang),
                pagu_jasa_tampil: formatRupiahKomaDash(paguJasa),
                pagu_modal_tampil: formatRupiahKomaDash(paguModal),
                total_pagu_tampil: formatRupiahKomaDash(totalPagu),
                sisa_penerimaan_display: formatRupiahKomaDash(sisaPenerimaan)
            };
        });
    }

    function rowPaguDariKodeFile(kodeFile) {
        const kode = normalisasiKodeFileSaldo(kodeFile);
        if (!kode) return null;
        return semuaDataPagu().find(row => String(row.kode_file || '').trim() === kode) || null;
    }

    function totalPembayaranKodeFile(kodeFile) {
        const kode = normalisasiKodeFileSaldo(kodeFile);
        if (!kode) return 0;
        return allPembayaranData
            .filter(row => normalisasiKodeFileSaldo(row.kode_file) === kode)
            .reduce((sum, row) => sum + nominalBrutoPembayaranTercatat(row), 0);
    }

    function totalRkaKermaKodeFile(kodeFile) {
        const kode = normalisasiKodeFileSaldo(kodeFile);
        if (!kode) return 0;
        return allRabAnggaranData
            .filter(row => normalisasiKodeFileSaldo(row.kode_file) === kode)
            .reduce((sum, row) => {
                const total = Number.isFinite(Number(row.total))
                    ? Number(row.total)
                    : totalNominalRabPayload(row);
                return sum + angkaPaguAnggaran(total);
            }, 0);
    }

